    BaniLine(id = "ramkali-ki-vaar-35", gurmukhi = "ਆਪੇ ਪੀਸੈ. ਆਪੇ ਘਸੈ; ਆਪੇ ਹੀ ਲਾਇ ਲਏਇ ॥", transliteration = "aape peesai. aape ghsai; aape hee laai laei ||", translation = "He Himself grinds me, and He Himself rubs me; He Himself applies me to His feet.", hindi = "आपे पीसै. आपे घसै; आपे ही लाइ लएइ ॥", punjabi = "ਉਹ ਆਪ ਹੀ (ਮਹਿਦੀ ਨੂੰ) ਪੀਂਹਦਾ ਹੈ, ਆਪ ਹੀ (ਮਹਿਦੀ ਨੂੰ) ਰਗੜਦਾ ਹੈ, ਆਪ ਹੀ (ਆਪਣੀ ਪੈਰੀਂ) ਲਾ ਲੈਂਦਾ ਹੈ (ਭਾਵ, ਬੰਦਗੀ ਦੀ ਘਾਲ-ਕਮਾਈ ਵਿਚ ਬੰਦੇ ਨੂੰ ਆਪ ਹੀ ਲਾਂਦਾ ਹੈ)।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-36", gurmukhi = "ਇਹੁ ਪਿਰਮ ਪਿਆਲਾ ਖਸਮ ਕਾ; ਜੈ ਭਾਵੈ ਤੈ ਦੇਇ ॥੨॥", transliteration = "ih piram piaalaa khasam kaa; jai bhaavai tai dei ||2||", translation = "This is the cup of love of my Lord and Master; He gives it as He chooses. ||2||", hindi = "इहु पिरम पिआला खसम का; जै भावै तै देइ ॥२॥", punjabi = "ਇਹ ਪ੍ਰੇਮ ਦਾ ਪਿਆਲਾ ਖਸਮ ਪ੍ਰਭੂ ਦੀ ਆਪਣੀ (ਵਸਤੁ) ਹੈ, ਉਸ ਮਨੁੱਖ ਨੂੰ ਦੇਂਦਾ ਹੈ ਜੋ ਉਸ ਨੂੰ ਪਿਆਰਾ ਲੱਗਦਾ ਹੈ ॥੨॥", wordMeaning = "ਪਿਰਮ ਪਿਆਲਾ = ਪ੍ਰੇਮ ਦਾ ਪਿਆਲਾ। ਜੈ ਭਾਵੈ = ਜੋ ਉਸ ਨੂੰ ਭਾਉਂਦਾ ਹੈ ॥੨॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-37", gurmukhi = "ਵੇਕੀ ਸ੍ਰਿਸਟਿ ਉਪਾਈਅਨੁ; ਸਭ ਹੁਕਮਿ, ਆਵੈ ਜਾਇ ਸਮਾਹੀ ॥", transliteration = "vekee srisat upaaeean; sabh hukam, aavai jaai smaahee ||", translation = "You created the world with its variety; by the Hukam of Your Command, it comes, goes, and merges again in You.", hindi = "वेकी स्रिसटि उपाईअनु; सभ हुकमि, आवै जाइ समाही ॥", punjabi = "ਉਸ (ਪ੍ਰਭੂ) ਨੇ ਰੰਗਾ-ਰੰਗ ਦੀ ਸ੍ਰਿਸ਼ਟੀ ਪੈਦਾ ਕੀਤੀ ਹੈ, ਸਾਰੇ ਜੀਵ ਉਸ ਦੇ ਹੁਕਮ ਵਿਚ ਜੰਮਦੇ ਤੇ ਸਮਾ ਜਾਂਦੇ ਹਨ;", wordMeaning = "ਵੇਕੀ = ਵਖੋ ਵਖ ਕਿਸਮ ਦੀ। ਉਪਾਈਅਨੁ = ਉਸ ਨੇ ਉਪਾਈ ਹੈ। ਹੁਕਮਿ = ਹੁਕਮ ਵਿਚ, ਹੁਕਮ ਅਨੁਸਾਰ। ਸਮਾਹੀ = ਸਮਾ ਜਾਂਦੇ ਹਨ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-38", gurmukhi = "ਪਉੜੀ ॥", transliteration = "pauree ||", translation = "Pauree:", hindi = "पउड़ी ॥", punjabi = "ਪਉੜੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-39", gurmukhi = "ਜਿਉ ਭਾਵੈ ਤਿਉ ਰਖੁ ਤੂ; ਗੁਰ ਸਬਦਿ ਬੁਝਾਹੀ ॥", transliteration = "jiu bhaavai tiu rakh too; gur sabad bujhaahee ||", translation = "As it pleases You, You keep me. Through the Word of the Guru's Shabad, I understand You.", hindi = "जिउ भावै तिउ रखु तू; गुर सबदि बुझाही ॥", punjabi = "(ਹੇ ਪ੍ਰਭੂ!) ਜਿਵੇਂ ਤੈਨੂੰ ਚੰਗਾ ਲੱਗੇ ਤਿਵੇਂ (ਜੀਵਾਂ ਨੂੰ) ਰੱਖ, ਤੂੰ ਆਪ ਹੀ ਗੁਰੂ ਦੇ ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ (ਜੀਵਾਂ ਨੂੰ) ਮੱਤ ਦੇਂਦਾ ਹੈਂ।", wordMeaning = "ਬੁਝਾਹੀ = (ਤੂੰ) ਸਮਝ ਦੇਂਦਾ ਹੈਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-40", gurmukhi = "ਆਪੇ ਵੇਖਿ ਵਿਗਸਦਾ; ਦੂਜਾ ਕੋ ਨਾਹੀ ॥", transliteration = "aape vekh vigasdaa; doojaa ko naahee ||", translation = "You Yourself see, and blossom forth; there is no one else at all.", hindi = "आपे वेखि विगसदा; दूजा को नाही ॥", punjabi = "ਪ੍ਰਭੂ ਹੀ (ਆਪਣੀ ਰਚਨਾ ਨੂੰ) ਵੇਖ ਕੇ ਖ਼ੁਸ਼ ਹੋ ਰਿਹਾ ਹੈ, ਉਸ ਦਾ ਕੋਈ ਸ਼ਰੀਕ ਨਹੀਂ।", wordMeaning = "ਵਿਗਸਦਾ = ਖ਼ੁਸ਼ ਹੁੰਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-41", gurmukhi = "ਸਭਨਾ ਤੇਰਾ ਜੋਰੁ ਹੈ; ਜਿਉ ਭਾਵੈ ਤਿਵੈ ਚਲਾਹੀ ॥", transliteration = "sabhnaa teraa jor hai; jiu bhaavai tivai chlaahee ||", translation = "You are the strength of all. As it pleases You, You lead us on.", hindi = "सभना तेरा जोरु है; जिउ भावै तिवै चलाही ॥", punjabi = "ਸਭ ਜੀਵਾਂ ਨੂੰ ਤੇਰਾ ਆਸਰਾ ਹੈ, ਜਿਵੇਂ ਤੈਨੂੰ ਭਾਵੇਂ ਤਿਵੇਂ (ਜੀਵਾਂ ਨੂੰ) ਤੂੰ ਤੋਰਦਾ ਹੈਂ।", wordMeaning = "ਚਲਾਹੀ = ਤੂੰ ਚਲਾਂਦਾ ਹੈਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-42", gurmukhi = "ਭਰਮਿ ਭੁਲਾਈ. ਸਭੁ ਜਗੁ ਫਿਰੀ; ਫਾਵੀ ਹੋਈ ਭਾਲਿ ॥", transliteration = "bharam bhulaaee. sabh jag phiree; phaavee hoee bhaal ||", translation = "Deluded by doubt, I wandered over the whole world. Searching, I became frustrated.", hindi = "भरमि भुलाई. सभु जगु फिरी; फावी होई भालि ॥", punjabi = "ਭੁਲੇਖੇ ਵਿਚ ਭੁੱਲੀ ਹੋਈ ਮੈਂ (ਪਰਮਾਤਮਾ ਨੂੰ ਲੱਭਣ ਵਾਸਤੇ) ਸਾਰਾ ਜਗਤ ਭਵੀਂ ਤੇ ਢੂੰਢ ਢੂੰਢ ਕੇ ਖਪ ਗਈ,", wordMeaning = "ਭਰਮਿ = ਭਰਮ ਵਿਚ। ਭਾਲਿ = ਭਾਲ ਕੇ, ਢੂੰਢ ਕੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-43", gurmukhi = "ਸਲੋਕੁ ਮਃ ੩ ॥", transliteration = "salok mh 3 ||", translation = "Salok, Third Mehl:", hindi = "सलोकु मः ३ ॥", punjabi = "ਸਲੋਕ ਤੀਜੀ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-44", gurmukhi = "ਤੁਧੁ ਜੇਵਡ. ਮੈ ਨਾਹਿ ਕੋ; ਕਿਸੁ ਆਖਿ ਸੁਣਾਈ ॥੨॥", transliteration = "tudh jevad. mai naah ko; kis aakh sunaaee ||2||", translation = "There is no other as great as You; unto whom should I speak and talk? ||2||", hindi = "तुधु जेवड. मै नाहि को; किसु आखि सुणाई ॥२॥", punjabi = "ਮੈਨੂੰ, (ਹੇ ਪ੍ਰਭੂ!) ਤੇਰੇ ਜੇਡਾ ਕੋਈ ਦਿੱਸਦਾ ਨਹੀਂ; ਕਿਸ ਦੀ ਬਾਬਤ ਆਖ ਕੇ ਦੱਸਾਂ (ਕਿ ਉਹ ਤੇਰੇ ਜੇਡਾ ਹੈ)? ॥੨॥", wordMeaning = "ਕਿਸੁ = ਕਿਸ ਦੀ ਬਾਬਤ? ਸੁਣਾਈ = ਮੈਂ ਸੁਣਾਵਾਂ ॥੨॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-45", gurmukhi = "ਗੁਰ ਪਰਸਾਦੀ ਹਰਿ ਧਿਆਈਐ; ਅੰਤਰਿ ਰਖੀਐ ਉਰ ਧਾਰਿ ॥", transliteration = "gur parsaadee har dhiaaeeai; antar rkheeai ur dhaar ||", translation = "By Guru's Grace, I meditate on the Lord; I enshrine Him deep within my heart.", hindi = "गुर परसादी हरि धिआईऐ; अंतरि रखीऐ उर धारि ॥", punjabi = "(ਪਰ, ਹਾਂ) ਸਤਿਗੁਰੂ ਦੀ ਮੇਹਰ ਨਾਲ ਪ੍ਰਭੂ ਸਿਮਰਿਆ ਜਾ ਸਕਦਾ ਹੈ ਤੇ ਹਿਰਦੇ ਦੇ ਅੰਦਰ ਰੱਖਿਆ ਜਾ ਸਕਦਾ ਹੈ।", wordMeaning = "ਅੰਤਰਿ = {ਨੋਟ: ਪਹਿਲੀ ਪਉੜੀ ਦੇ ਸ਼ਲੋਕ ਨੰ: ੩ ਵਿਚ ਦੇ ਲਫ਼ਜ਼ \"ਅੰਤਰੁ\" ਦਾ ਤੇ ਇਸ ਲਫ਼ਜ਼ ਦਾ ਫ਼ਰਕ ਚੇਤੇ ਰੱਖਣ-ਯੋਗ ਹੈ}।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-46", gurmukhi = "ਸੋ ਸਹੁ ਸਾਂਤਿ. ਨ ਦੇਵਈ; ਕਿਆ ਚਲੈ ਤਿਸੁ ਨਾਲਿ ॥", transliteration = "so sah saant. na devaee; kiaa chlai tis naal ||", translation = "My Husband Lord has not blessed me with peace and tranquility; what will work with Him?", hindi = "सो सहु सांति. न देवई; किआ चलै तिसु नालि ॥", punjabi = "(ਪਰ ਇਸ ਤਰ੍ਹਾਂ) ਉਹ ਖਸਮ (ਪ੍ਰਭੂ) (ਹਿਰਦੇ ਵਿਚ) ਸ਼ਾਂਤੀ ਨਹੀਂ ਦੇਂਦਾ, ਉਹ ਨਾਲ ਕੋਈ ਜ਼ੋਰ ਨਹੀਂ ਚੱਲ ਸਕਦਾ।", wordMeaning = "ਨ ਦੇਵਈ = ਨ ਦੇਵੈ, ਨਹੀਂ ਦੇਂਦਾ। ਤਿਸੁ ਨਾਲਿ = ਉਸ ਪ੍ਰਭੂ ਨਾਲ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-47", gurmukhi = "ਨਾਨਕ. ਘਰਿ ਬੈਠਿਆ. ਸਹੁ ਪਾਇਆ; ਜਾ ਕਿਰਪਾ ਕੀਤੀ ਕਰਤਾਰਿ ॥੧॥", transliteration = "naanak. ghar baithiaa. sah paaiaa; jaa kirpaa keetee kartaar ||1||", translation = "O Nanak, seated in his her own home, she finds her Husband Lord, when the Creator Lord grants His Grace. ||1||", hindi = "नानक. घरि बैठिआ. सहु पाइआ; जा किरपा कीती करतारि ॥१॥", punjabi = "ਹੇ ਨਾਨਕ! (ਗੁਰੂ ਦੀ ਮੇਹਰ ਨਾਲ) ਮੈਂ ਘਰ ਵਿਚ ਬੈਠਿਆਂ ਖਸਮ ਲੱਭ ਲਿਆ ਜਦੋਂ ਕਰਤਾਰ ਨੇ (ਮੇਰੇ ਉਤੇ) ਕਿਰਪਾ ਕੀਤੀ (ਤੇ ਗੁਰੂ ਮਿਲਾਇਆ) ॥੧॥", wordMeaning = "ਕਰਤਾਰਿ = ਕਰਤਾਰ ਨੇ ॥੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-48", gurmukhi = "ਧੰਧਾ ਧਾਵਤ ਦਿਨੁ ਗਇਆ; ਰੈਣਿ ਗਵਾਈ ਸੋਇ ॥", transliteration = "dhandhaa dhaavat din gaiaa; rain gvaaee soi ||", translation = "Chasing after worldly affairs, the day is wasted, and the night passes in sleep.", hindi = "धंधा धावत दिनु गइआ; रैणि गवाई सोइ ॥", punjabi = "ਜੋ ਮਨੁੱਖ ਆਪਣੇ ਮਨ ਦੇ ਪਿੱਛੇ ਤੁਰਦਾ ਹੈ ਉਸ ਦਾ (ਸਾਰਾ) ਦਿਨ (ਦੁਨੀਆ ਦੇ) ਧੰਧਿਆਂ ਵਿਚ ਭਟਕਦਿਆਂ ਬੀਤ ਜਾਂਦਾ ਹੈ, ਤੇ ਰਾਤ ਨੂੰ ਉਹ ਸੌਂ ਕੇ ਗੰਵਾ ਲੈਂਦਾ ਹੈ,", wordMeaning = "ਧਾਵਤ = ਦੌੜਦਿਆਂ, ਭਟਕਦਿਆਂ। ਰੈਣਿ = (ਸੰ: रजनी) ਰਾਤ। ਸੋਇ = ਸੌਂ ਕੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-49", gurmukhi = "ਮਃ ੩ ॥", transliteration = "mh 3 ||", translation = "Third Mehl:", hindi = "मः ३ ॥", punjabi = "ਤੀਜੀ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-50", gurmukhi = "ਕੂੜੁ ਬੋਲਿ ਬਿਖੁ ਖਾਇਆ; ਮਨਮੁਖਿ ਚਲਿਆ ਰੋਇ ॥", transliteration = "koor bol bikh khaaiaa; manmukh chliaa roi ||", translation = "Speaking lies, one eats poison; the self-willed manmukh departs, crying out in pain.", hindi = "कूड़ु बोलि बिखु खाइआ; मनमुखि चलिआ रोइ ॥", punjabi = "(ਇਹਨਾਂ ਧੰਧਿਆਂ ਵਿਚ ਪਿਆ ਹੋਇਆ) ਝੂਠ ਬੋਲ ਕੇ ਜ਼ਹਿਰ ਖਾਂਦਾ ਹੈ (ਭਾਵ, ਦੁਨੀਆ ਦੇ ਪਦਾਰਥ ਮਾਣਦਾ ਹੈ) ਤੇ (ਅੰਤ ਨੂੰ ਏਥੋਂ) ਰੋ ਕੇ ਤੁਰ ਪੈਂਦਾ ਹੈ।", wordMeaning = "ਬਿਖੁ = ਵਿਹੁ। ਮਨਮੁਖਿ = ਜੋ ਮਨੁੱਖ ਆਪਣੇ ਮਨ ਦੇ ਪਿੱਛੇ ਤੁਰਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-51", gurmukhi = "ਹਰਿ ਨਾਮੁ ਕਦੇ. ਨ ਚੇਤਿਓ; ਫਿਰਿ ਆਵਣ ਜਾਣਾ ਹੋਇ ॥", transliteration = "har naam kde. na chetio; phir aavan jaanaa hoi ||", translation = "He never even thinks of the Name of the Lord; over and over again, he comes and goes in reincarnation.", hindi = "हरि नामु कदे. न चेतिओ; फिरि आवण जाणा होइ ॥", punjabi = "ਉਸ ਨੇ ਪਰਮਾਤਮਾ ਦਾ ਨਾਮ ਤਾਂ ਕਦੇ ਯਾਦ ਨਹੀਂ ਕੀਤਾ ਹੁੰਦਾ (ਇਸ ਲਈ) ਮੁੜ ਮੁੜ ਜਨਮ ਮਰਨ ਦਾ ਗੇੜ (ਉਸ ਨੂੰ ਨਸੀਬ) ਹੁੰਦਾ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-52", gurmukhi = "ਸਿਰੈ ਉਪਰਿ ਜਮ ਡੰਡੁ ਹੈ; ਦੂਜੈ ਭਾਇ ਪਤਿ ਖੋਇ ॥", transliteration = "sirai upar jam dand hai; doojai bhaai pat khoi ||", translation = "The Mesenger of Death holds his club over the mortal's head; in the love of duality, he loses his honor.", hindi = "सिरै उपरि जम डंडु है; दूजै भाइ पति खोइ ॥", punjabi = "ਉਸ ਦੇ ਸਿਰ ਉਤੇ ਮੌਤ ਦਾ ਡੰਡਾ (ਤਿਆਰ ਰਹਿੰਦਾ) ਹੈ, (ਭਾਵ, ਹਰ ਵੇਲੇ ਮੌਤ ਤੋਂ ਡਰਦਾ ਹੈ), (ਪ੍ਰਭੂ ਨੂੰ ਵਿਸਾਰ ਕੇ) ਹੋਰ ਵਿਚ ਪਿਆਰ ਦੇ ਕਾਰਣ (ਆਪਣੀ) ਇੱਜ਼ਤ ਗੰਵਾ ਲੈਂਦਾ ਹੈ।", wordMeaning = "ਡੰਡੁ = ਡੰਡ, ਡੰਡਾ। ਦੂਜੈ ਭਾਇ = (ਪ੍ਰਭੂ ਨੂੰ ਛੱਡ ਕੇ) ਹੋਰ ਵਿਚ ਪਿਆਰ ਦੇ ਕਾਰਣ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-53", gurmukhi = "ਗੁਰ ਪਰਸਾਦੀ ਹਰਿ ਮਨਿ ਵਸੈ; ਜਮ ਡੰਡੁ. ਨ ਲਾਗੈ ਕੋਇ ॥", transliteration = "gur parsaadee har man vsai; jam dand. na laagai koi ||", translation = "But if, by Guru's Grace, the Lord's Name comes to dwell in his mind, then the Messenger of Death will not strike him down with his club.", hindi = "गुर परसादी हरि मनि वसै; जम डंडु. न लागै कोइ ॥", punjabi = "(ਪਰ ਜਿਸ ਮਨੁੱਖ ਦੇ) ਮਨ ਵਿਚ ਸਤਿਗੁਰੂ ਦੀ ਮੇਹਰ ਨਾਲ ਪਰਮਾਤਮਾ ਵੱਸਦਾ ਹੈ ਉਸ ਨੂੰ ਕੋਈ ਮੌਤ ਦਾ ਡੰਡਾ ਨਹੀਂ ਲੱਗਦਾ (ਭਾਵ, ਉਸ ਨੂੰ ਮੌਤ ਡਰਾ ਨਹੀਂ ਸਕਦੀ)।", wordMeaning = "ਮਨਿ = ਮਨ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
