    BaniLine(id = "ramkali-ki-vaar-69", gurmukhi = "ਮਃ ੩ ॥", transliteration = "mh 3 ||", translation = "Third Mehl:", hindi = "मः ३ ॥", punjabi = "ਤੀਜੀ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-70", gurmukhi = "ਜੀਵਤ ਮਰਣਾ. ਸਭੁ ਕੋ ਕਹੈ; ਜੀਵਨ ਮੁਕਤਿ ਕਿਉ ਹੋਇ ॥", transliteration = "jeevat marnaa. sabh ko khai; jeevan mukat kiu hoi ||", translation = "Everyone can say that they are dead while yet alive; how can they be liberated while yet alive?", hindi = "जीवत मरणा. सभु को कहै; जीवन मुकति किउ होइ ॥", punjabi = "(ਜਗਤ ਵਿਚ) ਜਿਊਂਦਿਆਂ (ਜਗਤ ਵਲੋਂ) ਮਰਨ ਦੀਆਂ ਗੱਲਾਂ ਹਰ ਕੋਈ ਕਰਦਾ ਹੈ, ਪਰ ਇਹ 'ਜੀਵਨ-ਮੁਕਤੀ' (ਦੀ ਅਵਸਥਾ) ਪ੍ਰਾਪਤ ਕਿਵੇਂ ਹੋਵੇ?", wordMeaning = "ਸਭੁ ਕੋ = ਹਰ ਕੋਈ, ਹਰੇਕ ਮਨੁੱਖ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-71", gurmukhi = "ਅਨਦਿਨੁ ਗੁਣ ਗਾਵੈ ਸੁਖ ਸਹਜੇ; ਬਿਖੁ ਭਵਜਲੁ. ਨਾਮਿ ਤਰੇਇ ॥", transliteration = "andin gun gaavai sukh sahje; bikh bhavajal. naam trei ||", translation = "night and day, he sings the Glorious Praises of the Lord. In celestial peace and poise, he crosses over the poisonous, terrifying world-ocean, through the Naam, the Name of the Lord.", hindi = "अनदिनु गुण गावै सुख सहजे; बिखु भवजलु. नामि तरेइ ॥", punjabi = "ਤੇ ਹਰ ਰੋਜ਼ ਨਿੱਤ ਆਨੰਦ ਨਾਲ ਅਡੋਲਤਾ ਵਿਚ ਟਿਕ ਕੇ ਪ੍ਰਭੂ ਦੇ ਗੁਣ ਗਾਏ ਤਾਂ ਪ੍ਰਭੂ ਦੇ ਨਾਮ ਦੀ ਰਾਹੀਂ ਉਹ ਇਸ ਵਿਹੁ-ਰੂਪ ਸੰਸਾਰ-ਸਮੁੰਦਰ ਨੂੰ ਤਰ ਜਾਂਦਾ ਹੈ।", wordMeaning = "ਨਾਮਿ = ਨਾਮ ਦੀ ਰਾਹੀਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-72", gurmukhi = "ਭੈ ਕਾ ਸੰਜਮੁ. ਜੇ ਕਰੇ; ਦਾਰੂ ਭਾਉ ਲਾਏਇ ॥", transliteration = "bhai kaa sanjam. je kre; daaroo bhaau laaei ||", translation = "If someone restrains himself through the Fear of God, and takes the medicine of the Love of God,", hindi = "भै का संजमु. जे करे; दारू भाउ लाएइ ॥", punjabi = "ਜੇ ਮਨੁੱਖ (ਦੁਨੀਆ ਦੇ ਚਸਕਿਆਂ ਦੀ ਵਿਹੁ ਨੂੰ ਦੂਰ ਕਰਨ ਲਈ) ਪਰਮਾਤਮਾ ਦਾ ਪਿਆਰ (-ਰੂਪ) ਦਵਾਈ ਵਰਤੇ ਤੇ ਪ੍ਰਭੂ ਦੇ ਡਰ ਦਾ ਪਰਹੇਜ਼ ਬਣਾਏ (ਭਾਵ, ਜਿਉਂ ਜਿਉਂ ਮਨੁੱਖ ਇਹ ਡਰ ਦਿਲ ਵਿਚ ਰੱਖੇਗਾ ਕਿ ਪ੍ਰਭੂ ਤਾਂ ਹਰ ਵੇਲੇ ਅੰਗ-ਸੰਗ ਹੈ ਉਸ ਤੋਂ ਕੋਈ ਲੁਕਾ ਨਹੀਂ ਹੋ ਸਕਦਾ)", wordMeaning = "ਸੰਜਮੁ = ਪਰਹੇਜ਼। ਦਾਰੂ = ਦਵਾਈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-73", gurmukhi = "ਦੂਜਾ ਭਾਉ ਰਚਾਇਓਨੁ; ਤ੍ਰੈ ਗੁਣ ਵਰਤਾਰਾ ॥", transliteration = "doojaa bhaau rchaaion; trai gun vartaaraa ||", translation = "God created the love of duality, and the three modes which pervade the universe.", hindi = "दूजा भाउ रचाइओनु; त्रै गुण वरतारा ॥", punjabi = "(ਜੀਵਾਂ ਦਾ) ਮਾਇਆ ਨਾਲ ਪਿਆਰ ਤੇ ਮਾਇਆ ਦੇ ਤਿੰਨਾਂ ਗੁਣਾਂ ਦਾ ਵਰਤਾਰਾ (ਭਾਵ, ਪ੍ਰਭਾਵ) ਭੀ ਉਸ ਸਿਰਜਣਹਾਰ ਨੇ (ਆਪ ਹੀ) ਪੈਦਾ ਕੀਤਾ ਹੈ;", wordMeaning = "ਦੂਜਾ ਭਾਉ = (ਪਰਮਾਤਮਾ ਤੋਂ ਬਿਨਾ) ਹੋਰ ਪਿਆਰ। ਰਚਾਇਓਨੁ = ਰਚਾਇਆ ਉਸ ਨੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-74", gurmukhi = "ਪਉੜੀ ॥", transliteration = "pauree ||", translation = "Pauree:", hindi = "पउड़ी ॥", punjabi = "ਪਉੜੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-75", gurmukhi = "ਨਾਨਕ ਗੁਰਮੁਖਿ ਪਾਈਐ; ਜਾ ਕਉ ਨਦਰਿ ਕਰੇਇ ॥੩॥", transliteration = "naanak gurmukh paaeeai; jaa kau nadar krei ||3||", translation = "O Nanak, the Gurmukh finds the Lord; he is blessed with His Glance of Grace. ||3||", hindi = "नानक गुरमुखि पाईऐ; जा कउ नदरि करेइ ॥३॥", punjabi = "ਹੇ ਨਾਨਕ! ਜਿਸ ਉਤੇ ਪ੍ਰਭੂ ਮੇਹਰ ਦੀ ਨਜ਼ਰ ਕਰਦਾ ਹੈ ਉਸ ਨੂੰ ਇਹ (ਜੀਵਨ-ਮੁਕਤੀ ਦੀ ਅਵਸਥਾ) ਸਤਿਗੁਰੂ ਦੀ ਰਾਹੀਂ ਮਿਲਦੀ ਹੈ ॥੩॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-76", gurmukhi = "ਬ੍ਰਹਮਾ ਬਿਸਨੁ ਮਹੇਸੁ ਉਪਾਇਅਨੁ; ਹੁਕਮਿ ਕਮਾਵਨਿ ਕਾਰਾ ॥", transliteration = "brahmaa bisan mhes upaaian; hukam kmaavan kaaraa ||", translation = "He created Brahma, Vishnu and Shiva, who act according to His Will.", hindi = "ब्रहमा बिसनु महेसु उपाइअनु; हुकमि कमावनि कारा ॥", punjabi = "(ਤਿੰਨਾਂ ਗੁਣਾਂ ਤੋਂ ਤਿੰਨੇ ਦੇਵਤੇ) ਬ੍ਰਹਮਾ ਵਿਸ਼ਨੂ ਤੇ ਸ਼ਿਵ ਉਸ ਨੇ (ਆਪ ਹੀ) ਉਪਾਏ ਹਨ, (ਇਹ ਤ੍ਰੈਵੇ) ਉਸ ਦੇ ਹੁਕਮ ਵਿਚ ਹੀ ਕਾਰ ਕਰ ਰਹੇ ਹਨ।", wordMeaning = "ਉਪਾਇਅਨੁ = ਉਪਾਏ ਉਸ ਨੇ (ਦੂਜੀ ਪਉੜੀ ਵਿਚ ਵੇਖੋ ਲਫ਼ਜ਼ \"ਉਪਾਈਅਨੁ\" ਇਹ ਫ਼ਰਕ ਸਮਝਣ ਲਈ ਪੜ੍ਹੋ 'ਗੁਰਬਾਣੀ ਵਿਆਕਰਣ')।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-77", gurmukhi = "ਪੰਡਿਤ ਪੜਦੇ ਜੋਤਕੀ; ਨਾ ਬੂਝਹਿ ਬੀਚਾਰਾ ॥", transliteration = "pandit parde jotkee; naa boojhah beechaaraa ||", translation = "The Pandits, the religious scholars, and the astrologers study their books, but they do not understand contemplation.", hindi = "पंडित पड़दे जोतकी; ना बूझहि बीचारा ॥", punjabi = "ਜੋਤਸ਼ੀ (ਆਦਿਕ) ਵਿਦਵਾਨ ਲੋਕ (ਵਿਚਾਰ ਵਾਲੀਆਂ ਪੁਸਤਕਾਂ) ਪੜ੍ਹਦੇ ਹਨ ਪਰ (ਪ੍ਰਭੂ ਦੇ ਇਸ ਕੌਤਕ ਦੀ) ਵੀਚਾਰ ਨੂੰ ਸਮਝਦੇ ਨਹੀਂ ਹਨ।", wordMeaning = "ਜੋਤਕੀ = ਜੋਤਸ਼ੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-78", gurmukhi = "ਜਿਸੁ ਭਾਵੈ ਤਿਸੁ ਬਖਸਿ ਲੈਹਿ; ਸਚਿ ਸਬਦਿ ਸਮਾਈ ॥੪॥", transliteration = "jis bhaavai tis bakhas laih; sach sabad smaaee ||4||", translation = "As it pleases You, You bless us with forgiveness, and merge us in the True Word of the Shabad. ||4||", hindi = "जिसु भावै तिसु बखसि लैहि; सचि सबदि समाई ॥४॥", punjabi = "ਜੋ ਤੈਨੂੰ ਭਾਉਂਦਾ ਹੈ ਉਸ ਉਤੇ ਬਖ਼ਸ਼ਸ਼ ਕਰਦਾ ਹੈਂ ਤੇ ਉਹ ਗੁਰੂ ਦੇ ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ ਤੇਰੇ ਸੱਚੇ ਸਰੂਪ ਵਿਚ ਟਿਕਿਆ ਰਹਿੰਦਾ ਹੈ ॥੪॥", wordMeaning = "ਬਖਸਿ ਲੈਹਿ = ਤੂੰ ਬਖ਼ਸ਼ ਲੈਂਦਾ ਹੈ। ਸਚਿ = ਸੱਚ ਵਿਚ ॥੪॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-79", gurmukhi = "ਸਭੁ ਕਿਛੁ ਤੇਰਾ ਖੇਲੁ ਹੈ; ਸਚੁ ਸਿਰਜਣਹਾਰਾ ॥", transliteration = "sabh kichh teraa khel hai; sach sirajanhaaraa ||", translation = "Everything is Your play, O True Creator Lord.", hindi = "सभु किछु तेरा खेलु है; सचु सिरजणहारा ॥", punjabi = "(ਹੇ ਪ੍ਰਭੂ!) (ਇਹ ਜਗਤ-ਰਚਨਾ) ਸਾਰਾ ਹੀ ਤੇਰਾ (ਇਕ) ਖੇਲ ਹੈ, ਤੂੰ (ਇਸ ਖੇਲ ਨੂੰ) ਬਣਾਣ ਵਾਲਾ ਹੈਂ ਤੇ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ ਹੈਂ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-80", gurmukhi = "ਮਾਇਆ ਨੋ ਫਿਰੈ; ਤਪਾ ਸਦਾਵੈ ॥", transliteration = "maaiaa no phirai; tpaa sdaavai ||", translation = "He runs after Maya, and yet pretends to be a man of disciplined meditation.", hindi = "माइआ नो फिरै; तपा सदावै ॥", punjabi = "(ਉਂਞ ਤਾਂ) ਮਾਇਆ ਦੀ ਖ਼ਾਤਰ ਫਿਰਦਾ ਹੈ (ਪਰ ਆਪਣੇ ਆਪ ਨੂੰ) ਤਪਾ ਅਖਵਾਂਦਾ ਹੈ,", wordMeaning = "ਮਾਇਆ ਨੋ = ਮਾਇਆ ਦੀ ਖ਼ਾਤਰ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-81", gurmukhi = "ਸਲੋਕੁ ਮਃ ੩ ॥", transliteration = "salok mh 3 ||", translation = "Salok, Third Mehl:", hindi = "सलोकु मः ३ ॥", punjabi = "ਸਲੋਕ ਤੀਜੀ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-82", gurmukhi = "ਮਨ ਕਾ ਝੂਠਾ; ਝੂਠੁ ਕਮਾਵੈ ॥", transliteration = "man kaa jhoothaa; jhooth kmaavai ||", translation = "The man of false mind practices falsehood.", hindi = "मन का झूठा; झूठु कमावै ॥", punjabi = "(ਜੋ ਮਨੁੱਖ) ਮਨ ਦਾ ਝੂਠਾ ਹੈ (ਭਾਵ, ਮਨ ਵਿਚ ਝੂਠ ਹੈ, ਤਪ ਦੇ ਉਲਟ ਭਾਵ ਹਨ) ਤੇ ਝੂਠ ਕਮਾਂਦਾ ਹੈ (ਭਾਵ, ਬਾਹਰੋਂ ਤਪਾ ਹੈ ਪਰ ਕਮਾਈ ਤਪੇ ਵਾਲੀ ਨਹੀਂ),", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-83", gurmukhi = "ਭਰਮੇ ਭੂਲਾ; ਸਭਿ ਤੀਰਥ ਗਹੈ ॥", transliteration = "bharme bhoolaa; sabh teerath ghai ||", translation = "Deluded by doubt, he visits all the sacred shrines of pilgrimage.", hindi = "भरमे भूला; सभि तीरथ गहै ॥", punjabi = "(ਆਪਣੇ ਆਪ ਨੂੰ ਤਪਾ ਸਮਝਣ ਦੇ) ਭੁਲੇਖੇ ਵਿਚ ਭੁੱਲਾ ਹੋਇਆ ਸਾਰੇ ਤੀਰਥ ਗਾਂਹਦਾ ਹੈ,", wordMeaning = "ਗਹੈ = ਫੜਦਾ ਹੈ, ਗਾਂਹਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-84", gurmukhi = "ਗੁਰ ਪਰਸਾਦੀ; ਕੋ ਸਚੁ ਕਮਾਵੈ ॥", transliteration = "gur parsaadee; ko sach kmaavai ||", translation = "By Guru's Grace, one lives the Truth.", hindi = "गुर परसादी; को सचु कमावै ॥", punjabi = "ਜੋ ਤਪਾ ਗੁਰੂ ਦੀ ਕਿਰਪਾ ਨਾਲ ਸੱਚ ਕਮਾਂਦਾ ਹੈ (ਭਾਵ, ਪ੍ਰਭੂ ਦੀ ਹੋਂਦ ਨੂੰ ਆਪਣੀ ਜ਼ਿੰਦਗੀ ਦਾ ਹਿੱਸਾ ਬਣਾਂਦਾ ਹੈ)", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-85", gurmukhi = "ਨਾਨਕ. ਸੋ ਤਪਾ; ਮੋਖੰਤਰੁ ਪਾਵੈ ॥੧॥", transliteration = "naanak. so tpaa; mokhantar paavai ||1||", translation = "O Nanak, such a man of disciplined meditation attains liberation. ||1||", hindi = "नानक. सो तपा; मोखंतरु पावै ॥१॥", punjabi = "ਹੇ ਨਾਨਕ! ਉਹ ਅੰਦਰਲੀ ਮੁਕਤੀ ਪ੍ਰਾਪਤ ਕਰਦਾ ਹੈ ॥੧॥", wordMeaning = "ਮੋਖੰਤਰੁ = ਮੋਖ-ਅੰਤਰੁ, ਅੰਦਰਲੀ ਮੁਕਤੀ ॥੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-86", gurmukhi = "ਓਹੁ ਤਪਾ; ਕੈਸੇ ਪਰਮ ਗਤਿ ਲਹੈ ॥", transliteration = "oh tpaa; kaise param gat lhai ||", translation = "How can such a man of disciplined meditation attain the supreme status?", hindi = "ओहु तपा; कैसे परम गति लहै ॥", punjabi = "ਅਜੇਹਾ ਤਪਾ ਉੱਚੀ ਆਤਮਕ ਅਵਸਥਾ ਕਿਵੇਂ ਪ੍ਰਾਪਤ ਕਰੇ?", wordMeaning = "ਪਰਮ = ਸਭ ਤੋਂ ਉੱਚੀ। ਗਤਿ = ਆਤਮਕ ਅਵਸਥਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-87", gurmukhi = "ਸਤਿਗੁਰ ਨੋ ਮਿਲੈ; ਸਬਦੁ ਸਮਾਲੇ ॥", transliteration = "satigur no milai; sabad smaale ||", translation = "Meeting with the True Guru, he contemplates the Word of the Shabad.", hindi = "सतिगुर नो मिलै; सबदु समाले ॥", punjabi = "ਸਤਿਗੁਰੂ ਨੂੰ ਮਿਲਦਾ ਹੈ (ਗੁਰੂ ਦੀ ਸਰਣ ਪੈਂਦਾ ਹੈ) ਤੇ ਗੁਰੂ ਦਾ ਸ਼ਬਦ (ਹਿਰਦੇ ਵਿਚ) ਸਾਂਭ ਕੇ ਰੱਖਦਾ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-88", gurmukhi = "ਸਤਿਗੁਰ ਕੀ ਸੇਵਾ; ਇਹੁ ਤਪੁ ਪਰਵਾਣੁ ॥", transliteration = "satigur kee sevaa; ih tap parvaan ||", translation = "Serving the True Guru - this is the only acceptable disciplined meditation.", hindi = "सतिगुर की सेवा; इहु तपु परवाणु ॥", punjabi = "ਸਤਿਗੁਰ ਦੀ (ਦੱਸੀ ਹੋਈ) ਕਾਰ ਕਰਨੀ-ਇਹ ਤਪ (ਪ੍ਰਭੂ ਦੀਆਂ ਨਜ਼ਰਾਂ ਵਿਚ) ਕਬੂਲ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-89", gurmukhi = "ਮਃ ੩ ॥", transliteration = "mh 3 ||", translation = "Third Mehl:", hindi = "मः ३ ॥", punjabi = "ਤੀਜੀ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-90", gurmukhi = "ਸੋ ਤਪਾ; ਜਿ ਇਹੁ ਤਪੁ ਘਾਲੇ ॥", transliteration = "so tpaa; ji ih tap ghaale ||", translation = "He alone is a man of disciplined meditation, who practices this self-discipline.", hindi = "सो तपा; जि इहु तपु घाले ॥", punjabi = "ਉਹ ਮਨੁੱਖ (ਅਸਲ) ਤਪਾ ਹੈ ਜੋ ਇਹ ਤਪ ਕਮਾਂਦਾ ਹੈ-", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
