    BaniLine(id = "ramkali-ki-vaar-109", gurmukhi = "ਘਰੁ ਦਰੁ ਸਭੋ ਸਚੁ ਹੈ; ਜਿਸੁ ਵਿਚਿ ਸਚਾ ਨਾਉ ॥", transliteration = "ghar dar sbho sach hai; jis vich schaa naau ||", translation = "True are all those homes and gates, within which the True Name is enshrined.", hindi = "घरु दरु सभो सचु है; जिसु विचि सचा नाउ ॥", punjabi = "(ਇਸ ਸ੍ਰਿਸ਼ਟੀ ਵਿਚ) ਹਰੇਕ ਘਰ ਹਰੇਕ ਦਰ ਸਦਾ-ਥਿਰ ਪ੍ਰਭੂ (ਦਾ ਟਿਕਾਣਾ) ਹੈ ਕਿਉਂਕਿ ਇਸ ਵਿਚ (ਹਰ ਥਾਂ) ਸੱਚਾ 'ਨਾਮ' ਮੌਜੂਦ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-110", gurmukhi = "ਅੰਬਰੁ ਧਰਤਿ ਵਿਛੋੜਿਅਨੁ; ਵਿਚਿ ਸਚਾ ਅਸਰਾਉ ॥", transliteration = "ambar dharat vichhorian; vich schaa asraau ||", translation = "They sky and the earth are separate, but the True Lord supports them from within.", hindi = "अंबरु धरति विछोड़िअनु; विचि सचा असराउ ॥", punjabi = "(ਇਸ \"ਵੇਕੀ ਸ੍ਰਿਸਟਿ\" ਵਿਚ) ਆਕਾਸ਼ ਤੇ ਧਰਤੀ ਉਸ ਪ੍ਰਭੂ ਨੇ ਆਪ ਹੀ ਵੱਖ ਵੱਖ ਕੀਤੇ ਹਨ, ਤੇ ਇਹਨਾਂ ਦੇ ਅੰਦਰ ਉਹ ਸਦਾ-ਥਿਰ ਪ੍ਰਭੂ ਆਪਣਾ ਹੁਕਮ ਚਲਾ ਰਿਹਾ ਹੈ;", wordMeaning = "ਅੰਬਰੁ = ਆਕਾਸ਼। ਵਿਛੋੜਿਅਨੁ = ਵਿਛੋੜੇ ਹਨ ਉਸ (ਪ੍ਰਭੂ) ਨੇ। ਸਚਾ = ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ ਪ੍ਰਭੂ। ਅਸਰਾਉ = ਅਸਰਾਜੁ, ਸ੍ਵਰਾਜੁ, ਆਪਣਾ ਹੁਕਮ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-111", gurmukhi = "ਸਭੁ ਸਚਾ ਹੁਕਮੁ ਵਰਤਦਾ; ਗੁਰਮੁਖਿ ਸਚਿ ਸਮਾਉ ॥", transliteration = "sabh schaa hukam varatdaa; gurmukh sach smaau ||", translation = "The Hukam of the True Lord's Command is effective everywhere. The Gurmukh merges in the True Lord.", hindi = "सभु सचा हुकमु वरतदा; गुरमुखि सचि समाउ ॥", punjabi = "ਹਰ ਥਾਂ (ਪ੍ਰਭੂ ਦਾ) ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ ਹੁਕਮ ਚੱਲ ਰਿਹਾ ਹੈ, ਗੁਰੂ ਦੇ ਹੁਕਮ ਵਿਚ ਤੁਰ ਕੇ ਉਸ ਸਦਾ-ਥਿਰ ਪ੍ਰਭੂ ਵਿਚ ਲੀਨਤਾ ਹੁੰਦੀ ਹੈ।", wordMeaning = "ਸਚਿ = ਸੱਚੇ ਵਿਚ। ਸਭੁ = ਸਭ ਥਾਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-112", gurmukhi = "ਸਚਾ ਆਪਿ ਤਖਤੁ ਸਚਾ; ਬਹਿ ਸਚਾ ਕਰੇ ਨਿਆਉ ॥", transliteration = "sachaa aap takhat schaa; bah schaa kre niaau ||", translation = "He Himself is True, and True is His throne. Seated upon it, He administers true justice.", hindi = "सचा आपि तखतु सचा; बहि सचा करे निआउ ॥", punjabi = "ਪ੍ਰਭੂ ਆਪ ਸਦਾ ਇਕ-ਰਸ ਰਹਿਣ ਵਾਲਾ ਹੈ, (ਜਗਤ-ਰੂਪ ਉਸ ਦਾ) ਤਖ਼ਤ (ਭੀ) (ਉਸੇ ਦਾ ਸਰੂਪ) ਸੱਚਾ ਹੈ, (ਇਸ ਤਖ਼ਤ ਉਤੇ) ਬੈਠ ਕੇ ਉਹ ਅਟੱਲ ਨਿਆਂ ਕਰ ਰਿਹਾ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-113", gurmukhi = "ਸਲੋਕੁ ਮਃ ੩ ॥", transliteration = "salok mh 3 ||", translation = "Salok, Third Mehl:", hindi = "सलोकु मः ३ ॥", punjabi = "ਸਲੋਕ ਤੀਜੀ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-114", gurmukhi = "ਸਭੁ ਸਚੋ ਸਚੁ ਵਰਤਦਾ; ਗੁਰਮੁਖਿ ਅਲਖੁ ਲਖਾਈ ॥੬॥", transliteration = "sabh scho sach varatdaa; gurmukh alakh lkhaaee ||6||", translation = "The Truest of the True is all-pervading everywhere; the Gurmukh sees the unseen. ||6||", hindi = "सभु सचो सचु वरतदा; गुरमुखि अलखु लखाई ॥६॥", punjabi = "ਹਰ ਥਾਂ ਨਿਰੋਲ ਉਹੀ ਸੱਚਾ ਪ੍ਰਭੂ ਮੌਜੂਦ ਹੈ, (ਪਰ) ਉਹ ਅਲੱਖ ਪ੍ਰਭੂ ਲਖਿਆ ਤਾਂ ਹੀ ਜਾ ਸਕਦਾ ਹੈ ਜੇ ਸਤਿਗੁਰੂ ਦੇ ਸਨਮੁਖ ਹੋਵੀਏ (ਘਰ ਘਾਟ ਨੂੰ ਤਿਆਗ ਕੇ ਨਹੀਂ) ॥੬॥", wordMeaning = "ਅਲਖੁ = ਜਿਸ ਦਾ ਕੋਈ ਖ਼ਾਸ ਚਿਹਨ ਲੱਛਣ ਨਹੀਂ ॥੬॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-115", gurmukhi = "ਰੈਣਾਇਰ ਮਾਹਿ ਅਨੰਤੁ ਹੈ; ਕੂੜੀ ਆਵੈ ਜਾਇ ॥", transliteration = "rainaair maah anant hai; kooree aavai jaai ||", translation = "In the world-ocean, the Infinite Lord abides. The false come and go in reincarnation.", hindi = "रैणाइर माहि अनंतु है; कूड़ी आवै जाइ ॥", punjabi = "(ਇਸ ਸੰਸਾਰ-) ਸਮੁੰਦਰ ਵਿਚ ਬੇਅੰਤ ਪ੍ਰਭੂ ਆਪ ਵੱਸ ਰਿਹਾ ਹੈ, ਪਰ (ਉਸ 'ਅਨੰਤ' ਨੂੰ ਛੱਡ ਕੇ) ਨਾਸਵੰਤ ਪਦਾਰਥਾਂ ਵਿਚ ਲੱਗੀ ਹੋਈ ਜਿੰਦ ਜੰਮਦੀ ਮਰਦੀ ਰਹਿੰਦੀ ਹੈ।", wordMeaning = "ਰੈਣਾਇਰ = {संः रय-नार। रय (ਰਯ) = ਨਦੀ ਦਾ ਵਹਣ। नार (ਨਾਰ) = ਜਲ} ਨਦੀਆਂ ਦਾ ਸਾਰਾ ਜਲ, ਸਮੁੰਦਰ। ਕੂੜੀ = ਕੂੜ (ਨਾਸਵੰਤ ਪਦਾਰਥਾਂ) ਵਿਚ ਲੱਗੀ ਹੋਈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-116", gurmukhi = "ਭਾਣੈ ਚਲੈ ਆਪਣੈ; ਬਹੁਤੀ ਲਹੈ ਸਜਾਇ ॥", transliteration = "bhaanai chlai aapnai; bhutee lhai sjaai ||", translation = "One who walks according to his own will, suffers terrible punishment.", hindi = "भाणै चलै आपणै; बहुती लहै सजाइ ॥", punjabi = "ਜੋ ਮਨੁੱਖ ਆਪਣੀ ਮਰਜ਼ੀ ਅਨੁਸਾਰ ਤੁਰਦਾ ਹੈ ਉਸ ਨੂੰ ਬਹੁਤ ਦੁੱਖ ਪ੍ਰਾਪਤ ਹੁੰਦਾ ਹੈ (ਕਿਉਂਕਿ ਉਹ \"ਅਨੰਤ\" ਨੂੰ ਛੱਡ ਕੇ ਨਾਸਵੰਤ ਪਦਾਰਥਾਂ ਪਿੱਛੇ ਦੌੜਦਾ ਹੈ);", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-117", gurmukhi = "ਰੈਣਾਇਰ ਮਹਿ ਸਭੁ ਕਿਛੁ ਹੈ; ਕਰਮੀ ਪਲੈ ਪਾਇ ॥", transliteration = "rainaair mah sabh kichh hai; karmee plai paai ||", translation = "All things are in the world-ocean, but they are obtained only by the karma of good actions.", hindi = "रैणाइर महि सभु किछु है; करमी पलै पाइ ॥", punjabi = "ਸਭ ਕੁਝ ਇਸ ਸਾਗਰ ਵਿਚ ਮੌਜੂਦ ਹੈ, ਪਰ ਪ੍ਰਭੂ ਦੀ ਮਿਹਰ ਨਾਲ ਮਿਲਦਾ ਹੈ।", wordMeaning = "ਕਰਮੀ = ਮਿਹਰ ਨਾਲ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-118", gurmukhi = "ਸਹਜੇ ਸਤਿਗੁਰੁ. ਨ ਸੇਵਿਓ; ਵਿਚਿ ਹਉਮੈ ਜਨਮਿ ਬਿਨਾਸੁ ॥", transliteration = "sahje stigur. na sevio; vich haumai janam binaas ||", translation = "One who doesn't intuitively serve the True Guru, loses his life in egotism.", hindi = "सहजे सतिगुरु. न सेविओ; विचि हउमै जनमि बिनासु ॥", punjabi = "ਜੋ ਮਨੁੱਖ ਸਿਦਕ ਸਰਧਾ ਨਾਲ ਸਤਿਗੁਰ ਦੇ ਹੁਕਮ ਵਿਚ ਨਹੀਂ ਤੁਰਿਆ, ਉਹ ਹਉਮੈ ਵਿਚ (ਰਹਿ ਕੇ) (ਜਗਤ ਵਿਚ) ਜਨਮ ਲੈ ਕੇ (ਜੀਵਨ) ਅਜਾਂਈ ਗਵਾ ਗਿਆ;", wordMeaning = "ਸਹਜੇ = ਸਹਜ ਅਵਸਥਾ ਵਿਚ, ਅਡੋਲਤਾ ਵਿਚ, ਸਿਦਕ ਸਰਧਾ ਨਾਲ। ਜਨਮਿ = ਜਨਮ ਕੇ, ਜੰਮ ਕੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-119", gurmukhi = "ਮਃ ੩ ॥", transliteration = "mh 3 ||", translation = "Third Mehl:", hindi = "मः ३ ॥", punjabi = "ਤੀਜੀ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-120", gurmukhi = "ਨਾਨਕ. ਨਉ ਨਿਧਿ ਪਾਈਐ; ਜੇ ਚਲੈ ਤਿਸੈ ਰਜਾਇ ॥੧॥", transliteration = "naanak. nau nidh paaeeai; je chlai tisai rjaai ||1||", translation = "O Nanak, he alone obtains the nine treasures, who walks in the Will of the Lord. ||1||", hindi = "नानक. नउ निधि पाईऐ; जे चलै तिसै रजाइ ॥१॥", punjabi = "ਹੇ ਨਾਨਕ! ਮਨੁੱਖ ਨੂੰ ਸਾਰੇ ਹੀ ਨੌ ਖ਼ਜ਼ਾਨੇ ਮਿਲ ਜਾਂਦੇ ਹਨ ਜੇ ਮਨੁੱਖ (ਇਸ ਸਾਗਰ ਵਿਚ ਵਿਆਪਕ ਪ੍ਰਭੂ ਦੀ) ਰਜ਼ਾ ਵਿਚ ਤੁਰੇ ॥੧॥", wordMeaning = "ਨਉਨਿਧਿ = ਨੌ ਖ਼ਜ਼ਾਨੇ (ਪ੍ਰਭੂ ਦਾ ਨਾਮ ਜੋ, ਮਾਨੋ, ਸ੍ਰਿਸ਼ਟੀ ਦੇ ਨੌ ਖ਼ਜ਼ਾਨੇ ਹੈ) ॥੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-121", gurmukhi = "ਬਿਖੁ ਖਾਧੀ ਮਨਮੁਖੁ ਮੁਆ; ਮਾਇਆ ਮੋਹਿ ਵਿਣਾਸੁ ॥", transliteration = "bikh khaadhee manmukh muaa; maaiaa moh vinaas ||", translation = "The self-willed manmukh eats poison and dies; he is ruined by love and attachment to Maya.", hindi = "बिखु खाधी मनमुखु मुआ; माइआ मोहि विणासु ॥", punjabi = "ਆਪਣੇ ਮਨ ਦੇ ਪਿੱਛੇ ਤੁਰਨ ਵਾਲਾ ਮਨੁੱਖ (ਵਿਕਾਰਾਂ ਦੀ) ਵਿਹੁ ਖਾਂਦਾ ਰਿਹਾ, (ਅਸਲ ਜੀਵਨ ਵੱਲੋਂ) ਮੋਇਆ ਹੀ ਰਿਹਾ ਤੇ ਮਾਇਆ ਦੇ ਮੋਹ ਵਿਚ ਉਸ ਦੀ ਜ਼ਿੰਦਗੀ ਤਬਾਹ ਹੋ ਗਈ।", wordMeaning = "ਮੋਹਿ = ਮੋਹ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-122", gurmukhi = "ਰਸਨਾ ਹਰਿ ਰਸੁ. ਨ ਚਖਿਓ; ਕਮਲੁ. ਨ ਹੋਇਓ ਪਰਗਾਸੁ ॥", transliteration = "rasnaa har ras. na chkhio; kamal. na hoio pargaas ||", translation = "His tongue does not taste the sublime essence of the Lord, and his heart-lotus does not blossom forth.", hindi = "रसना हरि रसु. न चखिओ; कमलु. न होइओ परगासु ॥", punjabi = "ਜਿਸ ਨੇ ਜੀਭ ਨਾਲ ਪ੍ਰਭੂ ਦੇ ਨਾਮ ਦਾ ਆਨੰਦ ਨਹੀਂ ਲਿਆ ਉਸ ਦਾ ਹਿਰਦਾ-ਰੂਪ ਕਉਲ ਫੁੱਲ ਨਹੀਂ ਖਿੜਿਆ।", wordMeaning = "ਰਸਨਾ = ਜੀਭ (ਨਾਲ)। ਪਰਗਾਸੁ = ਖਿੜਾਉ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-123", gurmukhi = "ਜਾ ਆਪੇ ਨਦਰਿ ਕਰੇ ਪ੍ਰਭੁ ਸਚਾ; ਤਾ ਹੋਵੈ ਦਾਸਨਿ ਦਾਸੁ ॥", transliteration = "jaa aape nadar kre prabh schaa; taa hovai daasan daas ||", translation = "When God Himself bestows His Glance of Grace, then one becomes the slave of His slaves.", hindi = "जा आपे नदरि करे प्रभु सचा; ता होवै दासनि दासु ॥", punjabi = "ਜਦੋਂ ਸੱਚਾ ਪ੍ਰਭੂ ਆਪ ਹੀ ਮੇਹਰ ਦੀ ਨਜ਼ਰ ਕਰਦਾ ਹੈ ਤਾਂ ਮਨੁੱਖ (ਪ੍ਰਭੂ ਦੇ) ਸੇਵਕਾਂ ਦਾ ਸੇਵਕ ਬਣ ਜਾਂਦਾ ਹੈ।", wordMeaning = "ਦਾਸਨਿ ਦਾਸੁ = ਦਾਸਾਂ ਦਾ ਦਾਸ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-124", gurmukhi = "ਇਕਸੁ ਹਰਿ ਕੇ ਨਾਮ ਵਿਣੁ; ਧ੍ਰਿਗੁ ਜੀਵਣੁ. ਧ੍ਰਿਗੁ ਵਾਸੁ ॥", transliteration = "ikas har ke naam vin; dhrig jeevan. dhrig vaas ||", translation = "Without the Name of the One Lord, his life is cursed, and his home is cursed as well.", hindi = "इकसु हरि के नाम विणु; ध्रिगु जीवणु. ध्रिगु वासु ॥", punjabi = "ਇਕ ਪ੍ਰਭੂ ਦਾ ਨਾਮ ਸਿਮਰਨ ਤੋਂ ਬਿਨਾ (ਜਗਤ ਵਿਚ) ਜੀਊਣਾ ਵੱਸਣਾ ਫਿਟਕਾਰ-ਜੋਗ ਹੈ।", wordMeaning = "ਧ੍ਰਿਗੁ = ਫਿਟਕਾਰ-ਯੋਗ। ਵਾਸੁ = ਵਸੇਬਾ, ਵਾਸਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-125", gurmukhi = "ਜਿਉ ਜਲ ਮਹਿ. ਕਮਲੁ ਅਲਿਪਤੋ ਵਰਤੈ; ਤਿਉ ਵਿਚੇ ਗਿਰਹ ਉਦਾਸੁ ॥", transliteration = "jiu jal mah. kamal alipto vartai; tiu viche girah udaas ||", translation = "As the lotus flower floats unaffected in the water, so does he remain detached in his own household.", hindi = "जिउ जल महि. कमलु अलिपतो वरतै; तिउ विचे गिरह उदासु ॥", punjabi = "ਉਹ ਗ੍ਰਿਹਸਤ ਵਿਚ ਰਹਿੰਦਾ ਹੋਇਆ ਭੀ ਇਉਂ ਉਪਰਾਮ ਜਿਹਾ ਰਹਿੰਦਾ ਹੈ ਜਿਵੇਂ ਪਾਣੀ ਵਿਚ (ਉੱਗਾ ਹੋਇਆ) ਕਉਲ-ਫੁੱਲ (ਪਾਣੀ ਦੇ ਅਸਰ ਤੋਂ) ਬਚਿਆ ਰਹਿੰਦਾ ਹੈ।", wordMeaning = "ਅਲਿਪਤੋ = ਨਿਰਲੇਪ, ਨਿਰਾਲਾ। ਗਿਰਹੁ = ਗ੍ਰਿਹਸਤ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-126", gurmukhi = "ਤਾ ਅਨਦਿਨੁ ਸੇਵਾ ਕਰੇ ਸਤਿਗੁਰੂ ਕੀ; ਕਬਹਿ. ਨ ਛੋਡੈ ਪਾਸੁ ॥", transliteration = "taa andin sevaa kre stiguroo kee; kabah. na chhodai paas ||", translation = "And then, night and day, he serves the True Guru, and never leaves His side.", hindi = "ता अनदिनु सेवा करे सतिगुरू की; कबहि. न छोडै पासु ॥", punjabi = "(ਫਿਰ) ਉਹ ਨਿੱਤ ਸਤਿਗੁਰੂ ਦੇ ਹੁਕਮ ਵਿਚ ਤੁਰਦਾ ਹੈ, ਕਦੇ ਗੁਰੂ ਦਾ ਪੱਲਾ ਨਹੀਂ ਛੱਡਦਾ।", wordMeaning = "ਅਨਦਿਨੁ = ਹਰ ਰੋਜ਼, ਨਿੱਤ। ਪਾਸੁ = ਪਾਸਾ, ਸਾਥ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-127", gurmukhi = "ਜਨ ਨਾਨਕ. ਕਰੇ ਕਰਾਇਆ ਸਭੁ ਕੋ; ਜਿਉ ਭਾਵੈ. ਤਿਵ ਹਰਿ ਗੁਣਤਾਸੁ ॥੨॥", transliteration = "jan naanak. kre kraaiaa sabh ko; jiu bhaavai. tiv har guntaas ||2||", translation = "O servant Nanak, the Lord acts, and inspires everyone to act, according to the Pleasure of His Will. He is the treasure of virtue. ||2||", hindi = "जन नानक. करे कराइआ सभु को; जिउ भावै. तिव हरि गुणतासु ॥२॥", punjabi = "ਹੇ ਦਾਸ ਨਾਨਕ! ਜਿਵੇਂ ਗੁਣਾਂ ਦੇ ਖ਼ਜ਼ਾਨੇ ਪਰਮਾਤਮਾ ਨੂੰ ਭਾਉਂਦਾ ਹੈ ਤਿਵੇਂ ਹਰੇਕ ਜੀਵ ਉਸ ਦਾ ਕਰਾਇਆ ਕਰਦਾ ਹੈ ॥੨॥", wordMeaning = "ਗੁਣਤਾਸੁ = ਗੁਣਾਂ ਦਾ ਖ਼ਜ਼ਾਨਾ ॥੨॥", startsAtMs = 0L, endsAtMs = 0L),
