    BaniLine(id = "ramkali-ki-vaar-141", gurmukhi = "ਮਃ ੩ ॥", transliteration = "mh 3 ||", translation = "Third Mehl:", hindi = "मः ३ ॥", punjabi = "ਤੀਜੀ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-142", gurmukhi = "ਗੁਰ ਕੈ ਸਬਦਿ ਕਮਲੁ ਬਿਗਸਿਆ; ਤਾ ਸਉਪਿਆ ਭਗਤਿ ਭੰਡਾਰੁ ॥", transliteration = "gur kai sabad kamal bigsiaa; taa saupiaa bhagat bhandaar ||", translation = "Through the Word of the Guru's Shabad, my heart-lotus has blossomed forth; the Lord blessed me with the treasure of devotional worship.", hindi = "गुर कै सबदि कमलु बिगसिआ; ता सउपिआ भगति भंडारु ॥", punjabi = "ਜੇ ਸਤਿਗੁਰੂ ਦੇ ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ ਹਿਰਦਾ ਕਮਲ ਖਿੜ ਪਏ ਤਾਂ ਹੀ ਭਗਤੀ ਦਾ ਖ਼ਜ਼ਾਨਾ ਮਿਲਦਾ ਹੈ।", wordMeaning = "ਭੰਡਾਰੁ = ਖ਼ਜ਼ਾਨਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-143", gurmukhi = "ਭਰਮੁ ਗਇਆ ਤਾ ਜਾਗਿਆ; ਚੂਕਾ ਅਗਿਆਨ ਅੰਧਾਰੁ ॥", transliteration = "bharam gaiaa taa jaagiaa; chookaa agiaan andhaar ||", translation = "My doubt was dispelled, and I woke up; the darkness of ignorance was dispelled.", hindi = "भरमु गइआ ता जागिआ; चूका अगिआन अंधारु ॥", punjabi = "ਜੇ (ਗੁਰ-ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ) ਮਨ ਦੀ ਭਟਕਣਾ ਦੂਰ ਹੋ ਜਾਏ ਤਾਂ ਹੀ ਮਨ ਜਾਗਿਆ (ਸਮਝੋ, ਕਿਉਂਕਿ) ਅਗਿਆਨ ਦਾ ਹਨੇਰਾ ਮੁੱਕ ਜਾਂਦਾ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-144", gurmukhi = "ਸਦਾ ਰਵੈ ਪਿਰੁ ਆਪਣਾ; ਸੋਭਾਵੰਤੀ ਨਾਰਿ ॥", transliteration = "sadaa rvai pir aapnaa; sobhaavantee naar ||", translation = "Such a beautiful, happy soul-bride enjoys her Husband Lord forever.", hindi = "सदा रवै पिरु आपणा; सोभावंती नारि ॥", punjabi = "ਉਹ ਸੋਭਾਵੰਤੀ (ਜੀਵ-) ਇਸਤ੍ਰੀ ਸਦਾ ਆਪਣੇ (ਪ੍ਰਭੂ-) ਪਤੀ ਨੂੰ ਸਿਮਰਦੀ ਹੈ।", wordMeaning = "ਰਵੈ = ਮਾਣਦੀ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-145", gurmukhi = "ਤਿਸ ਨੋ ਰੂਪੁ ਅਤਿ ਅਗਲਾ; ਜਿਸੁ ਹਰਿ ਨਾਲਿ ਪਿਆਰੁ ॥", transliteration = "tis no roop at aglaa; jis har naal piaar ||", translation = "She who is in love with her Lord, is the most infinitely beautiful.", hindi = "तिस नो रूपु अति अगला; जिसु हरि नालि पिआरु ॥", punjabi = "ਜਿਸ (ਜੀਵ-ਇਸਤ੍ਰੀ ਦਾ ਪ੍ਰਭੂ (-ਪਤੀ) ਨਾਲ ਪਿਆਰ ਬਣ ਜਾਂਦਾ ਹੈ ਉਸ (ਦੀ ਆਤਮਾ) ਨੂੰ ਬਹੁਤ ਸੋਹਣਾ ਰੂਪ ਚੜ੍ਹਦਾ ਹੈ।", wordMeaning = "ਅਗਲਾ = ਬਹੁਤਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-146", gurmukhi = "ਮਨਮੁਖਿ ਸੀਗਾਰੁ. ਨ ਜਾਣਨੀ; ਜਾਸਨਿ ਜਨਮੁ ਸਭੁ ਹਾਰਿ ॥", transliteration = "manmukh seegaar. na jaannee; jaasan janam sabh haar ||", translation = "The self-willed manmukhs do not know how to decorate themselves; wasting their whole lives, they depart.", hindi = "मनमुखि सीगारु. न जाणनी; जासनि जनमु सभु हारि ॥", punjabi = "ਮਨ ਦੇ ਪਿੱਛੇ ਤੁਰਨ ਵਾਲੀਆਂ (ਜੀਵ-ਇਸਤ੍ਰੀਆਂ ਪ੍ਰਭੂ ਨੂੰ ਪ੍ਰਸੰਨ ਕਰਨ ਵਾਲਾ) ਸਿੰਗਾਰ ਕਰਨਾ ਨਹੀਂ ਜਾਣਦੀਆਂ; ਉਹ ਸਾਰਾ (ਮਨੁੱਖ-) ਜਨਮ ਹਾਰ ਕੇ ਜਾਣਗੀਆਂ।", wordMeaning = "ਜਾਸਨਿ = ਜਾਵਨਗੇ। ਹਾਰਿ = ਹਾਰ ਕੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-147", gurmukhi = "ਬਿਨੁ ਹਰਿ ਭਗਤੀ. ਸੀਗਾਰੁ ਕਰਹਿ; ਨਿਤ ਜੰਮਹਿ ਹੋਇ ਖੁਆਰੁ ॥", transliteration = "bin har bhagtee. seegaar karah; nit jammah hoi khuaar ||", translation = "Those who decorate themselves without devotional worship to the Lord, are continually reincarnated to suffer.", hindi = "बिनु हरि भगती. सीगारु करहि; नित जंमहि होइ खुआरु ॥", punjabi = "ਪ੍ਰਭੂ (-ਪਤੀ) ਦੀ ਭਗਤੀ ਤੋਂ ਬਿਨਾ (ਹੋਰ ਕਰਮ ਧਰਮ ਆਦਿਕ) ਸਿੰਗਾਰ ਜੋ (ਜੀਵ-ਇਸਤ੍ਰੀਆਂ) ਕਰਦੀਆਂ ਹਨ ਉਹ ਨਿੱਤ ਖ਼ੁਆਰ ਹੋ ਕੇ ਜੰਮਦੀਆਂ ਹਨ (ਭਾਵ, ਜਨਮ ਮਰਨ ਦੇ ਗੇੜ ਵਿਚ ਪੈਂਦੀਆਂ ਹਨ ਤੇ ਦੁਖੀ ਰਹਿੰਦੀਆਂ ਹਨ)।", wordMeaning = "ਹੋਇ ਖੁਆਰੁ = ਖ਼ੁਆਰ ਹੋ ਕੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-148", gurmukhi = "ਨਾਨਕ. ਸਚਾ ਏਕੁ ਹੈ; ਦੁਹੁ ਵਿਚਿ ਹੈ ਸੰਸਾਰੁ ॥", transliteration = "naanak. schaa ek hai; duh vich hai sansaar ||", translation = "O Nanak, the True Lord is the One and only; duality exists only in the world.", hindi = "नानक. सचा एकु है; दुहु विचि है संसारु ॥", punjabi = "ਹੇ ਨਾਨਕ! (ਜਨਮ ਮਰਨ ਤੋਂ ਰਹਿਤ) ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ ਇਕ ਪਰਮਾਤਮਾ ਹੀ ਹੈ, ਸੰਸਾਰ (ਭਾਵ, ਦੁਨੀਆਦਾਰ) ਜਨਮ ਮਰਨ (ਦੇ ਚੱਕਰ) ਵਿਚ ਹੈ।", wordMeaning = "ਦੁਹੁ ਵਿਚਿ = ਜਨਮ ਮਰਨ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-149", gurmukhi = "ਸੈਸਾਰੈ ਵਿਚਿ ਸੋਭ. ਨ ਪਾਇਨੀ; ਅਗੈ ਜਿ ਕਰੇ, ਸੁ ਜਾਣੈ ਕਰਤਾਰੁ ॥", transliteration = "saisaarai vich sobh. na paainee; agai ji kre, su jaanai kartaar ||", translation = "They do not obtain respect in this world; the Creator Lord alone knows what will happen to them in the world hereafter.", hindi = "सैसारै विचि सोभ. न पाइनी; अगै जि करे, सु जाणै करतारु ॥", punjabi = "ਨਾਹ ਤਾਂ ਉਹਨਾਂ ਨੂੰ ਇਸ ਲੋਕ ਵਿਚ ਸੋਭਾ ਮਿਲਦੀ ਹੈ ਤੇ ਪਰਲੋਕ ਵਿਚ ਜੋ ਉਹਨਾਂ ਨਾਲ ਵਰਤਦੀ ਹੈ ਉਹ ਪ੍ਰਭੂ ਹੀ ਜਾਣਦਾ ਹੈ।", wordMeaning = "ਪਾਇਨੀ = ਪਾਂਦੇ ਹਨ। ਅਗੈ = ਪਰਲੋਕ ਵਿਚ। ਜਿ ਕਰੇ = ਜੋ ਕੁਝ (ਪ੍ਰਭੂ) ਕਰਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-150", gurmukhi = "ਚੰਗੈ ਮੰਦੈ ਆਪਿ ਲਾਇਅਨੁ; ਸੋ ਕਰਨਿ. ਜਿ ਆਪਿ ਕਰਾਏ ਕਰਤਾਰੁ ॥੨॥", transliteration = "changai mandai aap laaian; so karan. ji aap kraae kartaar ||2||", translation = "He Himself enjoins them to good and bad; they do only that which the Creator Lord causes them to do. ||2||", hindi = "चंगै मंदै आपि लाइअनु; सो करनि. जि आपि कराए करतारु ॥२॥", punjabi = "ਚੰਗੇ ਕੰਮ ਵਿਚ ਤੇ ਮੰਦੇ ਕੰਮ ਵਿਚ (ਜੀਵ) ਪ੍ਰਭੂ ਨੇ ਆਪ ਹੀ ਲਾਏ ਹੋਏ ਹਨ, ਜੋ ਕੁਝ ਕਰਤਾਰ (ਉਹਨਾਂ ਪਾਸੋਂ) ਕਰਾਂਦਾ ਹੈ ਉਹੀ ਉਹ ਕਰਦੇ ਹਨ ॥੨॥", wordMeaning = "ਚੰਗੈ = ਚੰਗੇ ਕੰਮ ਵਿਚ। ਲਾਇਅਨੁ = ਲਾਏ ਹਨ ਉਸ ਨੇ ॥੨॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-151", gurmukhi = "ਮਃ ੩ ॥", transliteration = "mh 3 ||", translation = "Third Mehl:", hindi = "मः ३ ॥", punjabi = "ਤੀਜੀ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-152", gurmukhi = "ਬਿਨੁ ਸਤਿਗੁਰ ਸੇਵੇ. ਸਾਂਤਿ, ਨ ਆਵਈ; ਦੂਜੀ ਨਾਹੀ ਜਾਇ ॥", transliteration = "bin stigur seve. saant, na aavaee; doojee naahee jaai ||", translation = "Without serving the True Guru, tranquility is not obtained. It cannot be found anywhere else.", hindi = "बिनु सतिगुर सेवे. सांति, न आवई; दूजी नाही जाइ ॥", punjabi = "ਸਤਿਗੁਰੂ ਦੇ ਹੁਕਮ ਵਿਚ ਤੁਰਨ ਤੋਂ ਬਿਨਾ (ਮਨ ਵਿਚ) ਸ਼ਾਂਤੀ ਨਹੀਂ ਆਉਂਦੀ (ਤੇ ਇਸ ਸ਼ਾਂਤੀ ਵਾਸਤੇ ਗੁਰੂ ਤੋਂ ਬਿਨਾ) ਕੋਈ (ਹੋਰ) ਥਾਂ ਨਹੀਂ।", wordMeaning = "ਜਾਇ = ਥਾਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-153", gurmukhi = "ਜੇ ਬਹੁਤੇਰਾ ਲੋਚੀਐ; ਵਿਣੁ ਕਰਮਾ ਪਾਇਆ. ਨ ਜਾਇ ॥", transliteration = "je bhuteraa locheeai; vin karmaa paaiaa. na jaai ||", translation = "No matter how much one may long for it, without the karma of good actions, it cannot be found.", hindi = "जे बहुतेरा लोचीऐ; विणु करमा पाइआ. न जाइ ॥", punjabi = "ਭਾਵੇਂ ਕਿਤਨੀ ਤਾਂਘ ਕਰੀਏ, ਭਾਗਾਂ ਤੋਂ ਬਿਨਾ (ਗੁਰੂ) ਮਿਲਦਾ ਭੀ ਨਹੀਂ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-154", gurmukhi = "ਅੰਤਰਿ ਲੋਭੁ ਵਿਕਾਰੁ ਹੈ; ਦੂਜੈ ਭਾਇ ਖੁਆਇ ॥", transliteration = "antar lobh vikaar hai; doojai bhaai khuaai ||", translation = "Those whose inner beings are filled with greed and corruption, are ruined through the love of duality.", hindi = "अंतरि लोभु विकारु है; दूजै भाइ खुआइ ॥", punjabi = "(ਕਿਉਂਕਿ ਜਿਤਨਾ ਚਿਰ ਮਨੁੱਖ ਦੇ) ਅੰਦਰ ਲੋਭ-ਰੂਪ ਵਿਕਾਰ ਹੈ (ਉਤਨਾ ਚਿਰ ਉਹ ਪ੍ਰਭੂ ਨੂੰ ਛੱਡ ਕੇ) ਹੋਰ ਦੇ ਪਿਆਰ ਵਿਚ ਖੁੰਝਿਆ ਫਿਰਦਾ ਹੈ।", wordMeaning = "ਖੁਆਇ = ਖ਼ੁਆਰ ਹੁੰਦਾ ਹੈ। ਦੂਜੈ ਭਾਇ = (ਪ੍ਰਭੂ ਤੋਂ ਬਿਨਾ) ਹੋਰ ਨਾਲ ਪਿਆਰ ਦੇ ਕਾਰਣ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-155", gurmukhi = "ਤਿਨ ਜੰਮਣੁ ਮਰਣੁ. ਨ ਚੁਕਈ; ਹਉਮੈ ਵਿਚਿ ਦੁਖੁ ਪਾਇ ॥", transliteration = "tin jamman maran. na chukaee; haumai vich dukh paai ||", translation = "The cycle of birth and death is not ended, and filled with egotism, they suffer in pain.", hindi = "तिन जंमणु मरणु. न चुकई; हउमै विचि दुखु पाइ ॥", punjabi = "(ਜਿਨ੍ਹਾਂ ਦਾ ਇਹ ਹਾਲ ਹੈ) ਉਹਨਾਂ ਦਾ ਜਨਮ ਮਰਨ ਦਾ ਗੇੜ ਨਹੀਂ ਮੁੱਕਦਾ, ਉਹਨਾਂ ਨੂੰ ਹਉਮੈ ਵਿਚ (ਗ੍ਰਸਿਆਂ ਨੂੰ) ਦੁੱਖ ਮਿਲਦਾ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-156", gurmukhi = "ਜਿਨੀ ਸਤਿਗੁਰ ਸਿਉ ਚਿਤੁ ਲਾਇਆ; ਸੋ ਖਾਲੀ ਕੋਈ ਨਾਹਿ ॥", transliteration = "jinee stigur siu chit laaiaa; so khaalee koee naah ||", translation = "Those who focus their consciousness on the True Guru, do not remain unfulfilled.", hindi = "जिनी सतिगुर सिउ चितु लाइआ; सो खाली कोई नाहि ॥", punjabi = "ਜਿਨ੍ਹਾਂ ਮਨੁੱਖਾਂ ਨੇ ਸਤਿਗੁਰੂ ਨਾਲ ਮਨ ਲਾਇਆ ਹੈ ਉਹਨਾਂ ਵਿਚੋਂ ਕੋਈ ਭੀ (ਪਿਆਰ ਤੋਂ) ਸੁੰਞੇ ਹਿਰਦੇ ਵਾਲਾ ਨਹੀਂ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-157", gurmukhi = "ਤਿਨ ਜਮ ਕੀ ਤਲਬ. ਨ ਹੋਵਈ; ਨਾ ਓਇ ਦੁਖ ਸਹਾਹਿ ॥", transliteration = "tin jam kee talab. na hovaee; naa oi dukh shaah ||", translation = "They are not summoned by the Messenger of Death, and they do not suffer in pain.", hindi = "तिन जम की तलब. न होवई; ना ओइ दुख सहाहि ॥", punjabi = "ਉਹਨਾਂ ਨੂੰ ਜਮ ਦਾ ਸੱਦਾ ਨਹੀਂ ਆਉਂਦਾ (ਭਾਵ, ਉਹਨਾਂ ਨੂੰ ਮੌਤ ਤੋਂ ਡਰ ਨਹੀਂ ਲੱਗਦਾ) ਨਾਹ ਹੀ ਉਹ ਕਿਸੇ ਤਰ੍ਹਾਂ ਦੁਖੀ ਹੁੰਦੇ ਹਨ।", wordMeaning = "ਤਲਬ = ਸੱਦਾ। ਓਇ = ਉਹ ਬੰਦੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-158", gurmukhi = "ਪਉੜੀ ॥", transliteration = "pauree ||", translation = "Pauree:", hindi = "पउड़ी ॥", punjabi = "ਪਉੜੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-159", gurmukhi = "ਨਾਨਕ. ਗੁਰਮੁਖਿ ਉਬਰੇ; ਸਚੈ ਸਬਦਿ ਸਮਾਹਿ ॥੩॥", transliteration = "naanak. gurmukh ubre; schai sabad smaah ||3||", translation = "O Nanak, the Gurmukh is saved, merging in the True Word of the Shabad. ||3||", hindi = "नानक. गुरमुखि उबरे; सचै सबदि समाहि ॥३॥", punjabi = "ਹੇ ਨਾਨਕ! ਗੁਰੂ ਦੇ ਹੁਕਮ ਵਿਚ ਤੁਰਨ ਵਾਲੇ ਬੰਦੇ (\"ਜਮ ਦੀ ਤਲਬ\" ਤੋਂ) ਬਚੇ ਹੋਏ ਹਨ (ਕਿਉਂਕਿ) ਉਹ ਗੁਰੂ ਦੇ ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ ਸੱਚੇ ਪ੍ਰਭੂ ਵਿਚ ਲੀਨ ਰਹਿੰਦੇ ਹਨ ॥੩॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-160", gurmukhi = "ਆਪਿ ਅਲਿਪਤੁ ਸਦਾ ਰਹੈ; ਹੋਰਿ ਧੰਧੈ ਸਭਿ ਧਾਵਹਿ ॥", transliteration = "aap alipat sdaa rhai; hor dhandhai sabh dhaavah ||", translation = "He Himself remains unattached forever; all others run after worldly affairs.", hindi = "आपि अलिपतु सदा रहै; होरि धंधै सभि धावहि ॥", punjabi = "(ਪਰਮਾਤਮਾ) ਆਪ (ਮਾਇਆ ਦੇ ਪ੍ਰਭਾਵ ਤੋਂ) ਨਿਰਾਲਾ ਰਹਿੰਦਾ ਹੈ, ਹੋਰ ਸਾਰੇ ਜੀਵ (ਮਾਇਆ ਦੇ) ਝੰਬੇਲੇ ਵਿਚ ਭਟਕ ਰਹੇ ਹਨ।", wordMeaning = "ਅਲਿਪਤੁ = ਨਿਰਲੇਪ, ਨਿਰਾਲਾ। ਹੋਰਿ = ਹੋਰ ਸਾਰੇ ਜੀਵ। ਧੰਧੈ = ਦੁਨੀਆ ਦੇ ਝੰਬੇਲੇ ਵਿਚ। ਧਾਵਹਿ = ਦੌੜਦੇ ਹਨ।", startsAtMs = 0L, endsAtMs = 0L)
