    BaniLine(id = "ramkali-ki-vaar-172", gurmukhi = "ਓਇ ਥਾਉ ਕੁਥਾਉ. ਨ ਜਾਣਨੀ; ਉਨ ਅੰਤਰਿ ਲੋਭੁ ਵਿਕਾਰੁ ॥", transliteration = "oi thaau kuthaau. na jaannee; un antar lobh vikaar ||", translation = "They do not understand right places and wrong places; they are filled with greed and corruption.", hindi = "ओइ थाउ कुथाउ. न जाणनी; उन अंतरि लोभु विकारु ॥", punjabi = "ਉਹ ਨਾਹ ਹੀ ਥਾਂ ਕੁਥਾਂ ਸਮਝਦੇ ਹਨ ਤੇ ਨਾਹ ਹੀ ਸਮੇ-ਸਿਰ ਢੁਕਦੀ ਗੱਲ ਕਰਨੀ ਜਾਣਦੇ ਹਨ ਕਿਉਂਕਿ ਉਹਨਾਂ ਦੇ ਮਨ ਵਿਚ ਲੋਭ ਵਿਕਾਰ ਪ੍ਰਬਲ ਹਨ।", wordMeaning = "ਥਾਉ ਕੁਥਾਉ = ਚੰਗਾ ਮੰਦਾ ਥਾਂ। ਉਨ ਅੰਤਰਿ = ਉਹਨਾਂ ਦੇ ਅੰਦਰ।", startsAtMs = 0L, endsAtMs = 0L),
