    BaniLine(id = "ramkali-ki-vaar-174", gurmukhi = "ਅਗੈ ਦਰਗਹ ਲੇਖੈ ਮੰਗਿਐ; ਮਾਰਿ ਖੁਆਰੁ ਕੀਚਹਿ ਕੂੜਿਆਰ ॥", transliteration = "agai daragah lekhai mangiai; maar khuaar keechah kooriaar ||", translation = "Hereafter, they are called to account in the Court of the Lord; the false ones are struck down and humiliated.", hindi = "अगै दरगह लेखै मंगिऐ; मारि खुआरु कीचहि कूड़िआर ॥", punjabi = "ਅਗਾਂਹ ਪ੍ਰਭੂ ਦੀ ਹਜ਼ੂਰੀ ਵਿਚ ਲੇਖਾ ਮੰਗਿਆ ਜਾਣ ਤੇ ਉਹ ਕੂੜ ਦੇ ਵਪਾਰੀ ਮਾਰ ਮਾਰ ਕੇ ਖ਼ੁਆਰ ਕੀਤੇ ਜਾਂਦੇ ਹਨ।", wordMeaning = "ਲੇਖੈ ਮੰਗਿਐ = ਲੇਖਾ ਮੰਗਿਆ ਜਾਣ ਤੇ (ਨੋਟ: ਪਾਠਕ ਜਨ ਲਫ਼ਜ਼ 'ਮੰਗੀਐ' ਅਤੇ 'ਮੰਗਿਐ' ਵਿਚ ਫ਼ਰਕ ਚੇਤੇ ਰੱਖਣ)। ਕੀਚਹਿ = ਕੀਤੇ ਜਾਂਦੇ ਹਨ। ਕੂੜਿਆਰ = ਕੂੜ ਦੇ ਵਪਾਰੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-175", gurmukhi = "ਏਹ ਕੂੜੈ ਕੀ ਮਲੁ. ਕਿਉ ਉਤਰੈ; ਕੋਈ ਕਢਹੁ ਇਹੁ ਵੀਚਾਰੁ ॥", transliteration = "eh koorai kee mal. kiu utrai; koee kadhah ih veechaar ||", translation = "How can this filth of falsehood be washed off? Can anyone think about this, and find the way?", hindi = "एह कूड़ै की मलु. किउ उतरै; कोई कढहु इहु वीचारु ॥", punjabi = "ਕੋਈ ਮਨੁੱਖ ਇਹ ਵਿਚਾਰ ਦੱਸੇ ਕਿ ਇਹ ਕੂੜ ਦੀ ਮੈਲ (ਭਾਵ, ਉਹਨਾਂ ਪਦਾਰਥਾਂ ਦਾ ਮੋਹ ਜੋ ਨਾਲ ਨਹੀਂ ਨਿਭਣੇ) ਕਿਵੇਂ ਦੂਰ ਹੋਵੇ।", wordMeaning = "ਕੂੜੈ ਕੀ = ਉਸ ਪਦਾਰਥ ਦੀ ਜੋ ਨਾਲ ਨਹੀਂ ਨਿਭਣਾ। ਕਿਉ = ਕਿਵੇਂ? ਕਢਹੁ = ਦੱਸੋ, ਲੱਭੋ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-176", gurmukhi = "ਸਤਿਗੁਰੁ ਮਿਲੈ ਤਾ ਨਾਮੁ ਦਿੜਾਏ; ਸਭਿ ਕਿਲਵਿਖ ਕਟਣਹਾਰੁ ॥", transliteration = "satigur milai taa naam diraae; sabh kilvikh katanhaar ||", translation = "If one meets with the True Guru, He implants the Naam, the Name of the Lord within; all his sins are destroyed.", hindi = "सतिगुरु मिलै ता नामु दिड़ाए; सभि किलविख कटणहारु ॥", punjabi = "ਜੇ ਸਤਿਗੁਰੂ ਮਿਲ ਪਏ ਤਾਂ ਉਹ ਪ੍ਰਭੂ ਦਾ ਨਾਮ (ਹਿਰਦੇ ਵਿਚ) ਪੱਕਾ ਬਿਠਾ ਦੇਂਦਾ ਹੈ (ਗੁਰੂ ਇਹ ਗੱਲ ਨਿਸ਼ਚੇ ਕਰਾ ਦੇਂਦਾ ਹੈ ਕਿ) 'ਨਾਮ' ਸਾਰੇ ਪਾਪਾਂ ਨੂੰ ਕੱਟਣ ਦੇ ਸਮਰੱਥ ਹੈ।", wordMeaning = "ਦਿੜਾਏ = ਪੱਕਾ ਕਰਾਂਦਾ ਹੈ। ਕਿਲਵਿਖ = ਪਾਪ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-177", gurmukhi = "ਨਾਮੁ ਜਪੇ. ਨਾਮੋ ਆਰਾਧੇ; ਤਿਸੁ ਜਨ ਕਉ ਕਰਹੁ ਸਭਿ ਨਮਸਕਾਰੁ ॥", transliteration = "naam jpe. naamo aaraadhe; tis jan kau karah sabh namaskaar ||", translation = "Let all bow in humility to that humble being who chants the Naam, and worships the Naam in adoration.", hindi = "नामु जपे. नामो आराधे; तिसु जन कउ करहु सभि नमसकारु ॥", punjabi = "(ਸੋ, ਗੁਰੂ ਦੇ ਸਨਮੁਖ ਹੋ ਕੇ) ਜੋ ਮਨੁੱਖ ਨਾਮ ਜਪਦਾ ਹੈ ਨਾਮ ਹੀ ਸਿਮਰਦਾ ਹੈ ਉਸ ਮਨੁੱਖ ਨੂੰ ਸਾਰੇ ਸਿਰ ਨਿਵਾਓ,", wordMeaning = "ਸਭਿ = ਸਾਰੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-178", gurmukhi = "ਮਲੁ ਕੂੜੀ. ਨਾਮਿ ਉਤਾਰੀਅਨੁ; ਜਪਿ ਨਾਮੁ ਹੋਆ ਸਚਿਆਰੁ ॥", transliteration = "mal kooree. naam utaareean; jap naam hoaa schiaar ||", translation = "The Naam washes off the filth of falsehood; chanting the Naam, one becomes truthful.", hindi = "मलु कूड़ी. नामि उतारीअनु; जपि नामु होआ सचिआरु ॥", punjabi = "ਕੂੜੇ ਪਦਾਰਥਾਂ (ਦੇ ਮੋਹ) ਦੀ ਮੈਲ ਉਸ ਮਨੁੱਖ ਨੇ ਪ੍ਰਭੂ ਦੇ ਨਾਮ ਦੀ ਰਾਹੀਂ ਉਤਾਰ ਲਈ ਹੈ, ਨਾਮ ਜਪ ਕੇ ਉਹ ਸੱਚ ਦਾ ਵਪਾਰੀ ਬਣ ਗਿਆ ਹੈ।", wordMeaning = "ਨਾਮਿ = ਨਾਮ ਦੀ ਰਾਹੀਂ। ਉਤਾਰੀਅਨੁ = ਉਤਾਰੀ ਹੈ ਉਸ ਨੇ। ਸਚਿਆਰੁ = ਸੱਚ ਦਾ ਵਣਜਾਰਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-179", gurmukhi = "ਜਨ ਨਾਨਕ. ਜਿਸ ਦੇ ਏਹਿ ਚਲਤ ਹਹਿ; ਸੋ ਜੀਵਉ ਦੇਵਣਹਾਰੁ ॥੨॥", transliteration = "jan naanak. jis de eh chalat hah; so jeevau devanhaar ||2||", translation = "O servant Nanak, wondrous are the plays of the Lord, the Giver of life. ||2||", hindi = "जन नानक. जिस दे एहि चलत हहि; सो जीवउ देवणहारु ॥२॥", punjabi = "ਹੇ ਦਾਸ ਨਾਨਕ! (ਅਰਦਾਸ ਕਰ ਕਿ) ਜਿਸ ਪ੍ਰਭੂ ਦੇ ਨਾਮ ਵਿਚ ਇਹ ਬਰਕਤਾਂ ਹਨ ਉਹ ਦਾਤਾ ਜੀਊਂਦਾ ਰਹੇ (ਭਾਵ, ਸਦਾ ਅਸਾਡੇ ਸਿਰ ਤੇ ਹੱਥ ਰੱਖੀ ਰੱਖੇ) ॥੨॥", wordMeaning = "ਹਹਿ = ਹਨ। ਜੀਵਉ = (ਰੱਬ ਕਰ ਕੇ) ਜੀਵੋ (ਵੇਖੋ 'ਗੁਰਬਾਣੀ ਵਿਆਕਰਣ') ॥੨॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-180", gurmukhi = "ਤੁਧੁ ਜੇਵਡੁ ਦਾਤਾ ਨਾਹਿ; ਕਿਸੁ ਆਖਿ ਸੁਣਾਈਐ ॥", transliteration = "tudh jevad daataa naah; kis aakh sunaaeeai ||", translation = "You are the Great Giver; no other is as great as You. Unto whom should I speak and talk?", hindi = "तुधु जेवडु दाता नाहि; किसु आखि सुणाईऐ ॥", punjabi = "(ਹੇ ਪ੍ਰਭੂ!) ਤੇਰੇ ਜੇਡਾ ਕੋਈ ਦਾਤਾ ਨਹੀਂ, ਕਿਸ ਦੀ ਬਾਬਤ ਆਖ ਕੇ ਦੱਸੀਏ (ਕਿ ਉਹ ਤੇਰੇ ਜੇਡਾ ਦਾਤਾ ਹੈ)? (ਭਾਵ, ਸਭ ਦਾਤਾਂ ਤੈਥੋਂ ਮਿਲਦੀਆਂ ਹਨ, ਨਾਮ-ਅੰਮ੍ਰਿਤ ਦਾ ਦਾਤਾ ਭੀ ਤੂੰ ਹੀ ਹੈਂ।", wordMeaning = "ਕਿਸੁ = ਕਿਸ ਦੀ ਬਾਬਤ?", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-181", gurmukhi = "ਪਉੜੀ ॥", transliteration = "pauree ||", translation = "Pauree:", hindi = "पउड़ी ॥", punjabi = "ਪਉੜੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-182", gurmukhi = "ਗੁਰ ਪਰਸਾਦੀ ਪਾਇ; ਜਿਥਹੁ ਹਉਮੈ ਜਾਈਐ ॥", transliteration = "gur parsaadee paai; jithah haumai jaaeeai ||", translation = "By Guru's Grace, I find You; You eradicate egotism from within.", hindi = "गुर परसादी पाइ; जिथहु हउमै जाईऐ ॥", punjabi = "('ਅੰਮ੍ਰਿਤ') ਸਤਿਗੁਰੂ ਦੀ ਕਿਰਪਾ ਨਾਲ ਮਿਲਦਾ ਹੈ, ਜਿਥੋਂ (ਭਾਵ, ਗੁਰੂ ਤੋਂ ਹੀ) ਹਉਮੈ ਨਾਸ ਹੁੰਦੀ ਹੈ;", wordMeaning = "ਜਿਥਹੁ = (ਭਾਵ) ਸਤਿਗੁਰੂ ਤੋਂ", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-183", gurmukhi = "ਰਸ ਕਸ ਸਾਦਾ ਬਾਹਰਾ; ਸਚੀ ਵਡਿਆਈਐ ॥", transliteration = "ras kas saadaa baahraa; schee vdiaaeeai ||", translation = "You are beyond sweet and salty flavors; True is Your glorious greatness.", hindi = "रस कस सादा बाहरा; सची वडिआईऐ ॥", punjabi = "(ਨਾਮ-ਅੰਮ੍ਰਿਤ ਦਾ ਦਾਤਾ ਪ੍ਰਭੂ) ਸਾਰੇ ਰਸਾਂ ਤੇ ਸੁਆਦਾਂ (ਦੇ ਪ੍ਰਭਾਵ) ਤੋਂ ਉਤਾਂਹ ਹੈ, ਉਸ ਦੀ ਬਜ਼ੁਰਗੀ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲੀ ਹੈ।", wordMeaning = "ਰਸ = ਰਸ ਛੇ ਕਿਸਮ ਦੇ ਹਨ (कटु, अम्ल, मधुर, लवण, तिक्त, कषाय)। ਕਸ = ਕਸੈਲਾ ਰਸ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-184", gurmukhi = "ਜਿਸ ਨੋ ਬਖਸੇ ਤਿਸੁ ਦੇਇ; ਆਪਿ ਲਏ ਮਿਲਾਈਐ ॥", transliteration = "jis no bakhse tis dei; aap lae milaaeeai ||", translation = "You bless those whom You forgive, and unite them with Yourself.", hindi = "जिस नो बखसे तिसु देइ; आपि लए मिलाईऐ ॥", punjabi = "ਪ੍ਰਭੂ ਜਿਸ ਉੱਤੇ ਮੇਹਰ ਕਰਦਾ ਹੈ ਉਸ ਨੂੰ (ਅੰਮ੍ਰਿਤ) ਬਖ਼ਸ਼ਦਾ ਹੈ ਤੇ ਉਸ ਨੂੰ ਆਪ ਹੀ (ਆਪਣੇ ਵਿਚ) ਜੋੜ ਲੈਂਦਾ ਹੈ।", wordMeaning = "ਦੇਇ = ਦੇਂਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-185", gurmukhi = "ਘਟ ਅੰਤਰਿ ਅੰਮ੍ਰਿਤੁ ਰਖਿਓਨੁ; ਗੁਰਮੁਖਿ ਕਿਸੈ ਪਿਆਈ ॥੯॥", transliteration = "ghat antar amrit rkhion; gurmukh kisai piaaee ||9||", translation = "You have placed the Ambrosial Nectar deep within the heart; the Gurmukh drinks it in. ||9||", hindi = "घट अंतरि अंम्रितु रखिओनु; गुरमुखि किसै पिआई ॥९॥", punjabi = "(ਉਂਞ ਤਾਂ ਇਹ) ਅੰਮ੍ਰਿਤ ਉਸ ਨੇ ਹਰੇਕ ਦੇ ਹਿਰਦੇ ਵਿਚ ਰੱਖਿਆ ਹੋਇਆ ਹੈ ਪਰ ਜਿਸ ਕਿਸੇ ਨੂੰ ਮਿਲਾਂਦਾ ਹੈ ਗੁਰੂ ਦੀ ਰਾਹੀਂ ਮਿਲਾਂਦਾ ਹੈ ॥੯॥", wordMeaning = "ਰਖਿਓਨੁ = ਰੱਖਿਆ ਹੈ ਉਸ ਨੇ (ਵੇਖੋ 'ਗੁਰਬਾਣੀ ਵਿਆਕਰਣ')। ਪਿਆਈ = ਪਿਲਾਂਦਾ ਹੈ ॥੯॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-186", gurmukhi = "ਜਿ ਸਤਿਗੁਰ ਭਾਵੈ ਸੁ ਮੰਨਿ ਲੈਨਿ; ਸੇਈ ਕਰਮ ਕਰੇਨਿ ॥", transliteration = "ji stigur bhaavai su mann lain; seee karam kren ||", translation = "They accept what is pleasing to the Will of the True Guru, and act accordingly.", hindi = "जि सतिगुर भावै सु मंनि लैनि; सेई करम करेनि ॥", punjabi = "(ਗੁਰ-ਸਾਖੀਆਂ ਦੀ ਬਰਕਤਿ ਨਾਲ, ਗੁਰਮੁਖ ਸਿੱਖ-ਪੁਤ੍ਰ) ਉਹਨਾਂ ਗੱਲਾਂ ਵਿਚ ਯਕੀਨ ਲਿਆਉਂਦੇ ਹਨ ਤੇ ਉਹ ਕੰਮ ਕਰਦੇ ਹਨ ਜੋ ਸਤਿਗੁਰੂ ਨੂੰ ਭਾਉਂਦੇ ਹਨ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-187", gurmukhi = "ਸਲੋਕ ਮਃ ੩ ॥", transliteration = "salok mh 3 ||", translation = "Salok, Third Mehl:", hindi = "सलोक मः ३ ॥", punjabi = "ਸਲੋਕ ਤੀਜੀ ਪਾਤਿਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-188", gurmukhi = "ਬਾਬਾਣੀਆ ਕਹਾਣੀਆ; ਪੁਤ ਸਪੁਤ ਕਰੇਨਿ ॥", transliteration = "baabaaneeaa khaaneeaa; put sput kren ||", translation = "The stories of one's ancestors make the children good children.", hindi = "बाबाणीआ कहाणीआ; पुत सपुत करेनि ॥", punjabi = "ਸਤਿਗੁਰੂ ਦੀਆਂ ਸਾਖੀਆਂ (ਸਿੱਖ-) ਪੁਤ੍ਰਾਂ ਨੂੰ (ਗੁਰਮੁਖ) ਪੁੱਤਰ ਬਣਾ ਦੇਂਦੀਆਂ ਹਨ;", wordMeaning = "ਬਾਬਾਣੀ = ਬਾਬੇ ਦੀ। ਬਾਬਾਣੀਆਂ = ਬਾਬਿਆਂ ਦੀਆਂ, ਬਜ਼ੁਰਗਾਂ ਦੀਆਂ, ਸਤਿਗੁਰੂ ਦੀਆਂ। ਸਪੁਤ = ਚੰਗੇ ਪੁਤ੍ਰ। ਕਰੇਨਿ = ਬਣਾ ਦੇਂਦੀਆਂ ਹਨ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-189", gurmukhi = "ਸਚੈ ਲਾਏ ਸਚਿ ਲਗੇ; ਸਦਾ ਸਚੁ ਸਮਾਲੇਨਿ ॥", transliteration = "sachai laae sach lge; sdaa sach smaalen ||", translation = "Those, whom the True Lord attaches, are attached to the Truth; they contemplate the True Name forever.", hindi = "सचै लाए सचि लगे; सदा सचु समालेनि ॥", punjabi = "ਜਿਨ੍ਹਾਂ ਨੂੰ ਸੱਚੇ ਪ੍ਰਭੂ ਨੇ (ਸਤਿਗੁਰੂ ਦੇ ਕੌਤਕਾਂ ਦੀ ਯਾਦ ਵਿਚ) ਲਾਇਆ, ਉਹ ਸੱਚੇ ਪ੍ਰਭੂ ਵਿਚ (ਭੀ) ਜੁੜੇ, ਉਹ ਸਦਾ ਸੱਚੇ ਪ੍ਰਭੂ ਨੂੰ (ਭੀ) ਚੇਤੇ ਰੱਖਦੇ ਹਨ।", wordMeaning = "ਸਚੈ = ਸਦਾ-ਥਿਰ ਪ੍ਰਭੂ ਨੇ। ਸਚਿ = ਸੱਚੇ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-190", gurmukhi = "ਜਾਇ ਪੁਛਹੁ ਸਿਮ੍ਰਿਤਿ ਸਾਸਤ, ਬਿਆਸ ਸੁਕ ਨਾਰਦ; ਬਚਨ ਸਭ ਸ੍ਰਿਸਟਿ ਕਰੇਨਿ ॥", transliteration = "jaai puchhah simrit saasat, biaas suk naarad; bachan sabh srisat kren ||", translation = "Go and consult the Simritees, the Shaastras, the writings of Vyaas, Suk Dayv, Naarad, and all those who preach to the world.", hindi = "जाइ पुछहु सिम्रिति सासत, बिआस सुक नारद; बचन सभ स्रिसटि करेनि ॥", punjabi = "(ਜੇ ਇਸ ਗੱਲ ਦੀ ਤਸਦੀਕ ਕਰਨੀ ਹੋਵੇ ਤਾਂ ਪੁਰਾਤਨ ਧਰਮ-ਪੁਸਤਕ) ਸਿਮ੍ਰਿਤੀਆਂ ਤੇ ਸ਼ਾਸਤ੍ਰ (ਤੇ ਪੁਰਾਤਨ ਰਿਸ਼ੀ) ਵਿਆਸ ਸੁਕ ਤੇ ਨਾਰਦ (ਆਦਿਕਾਂ) ਨੂੰ ਪੁੱਛ ਵੇਖੋ (ਭਾਵ, ਉਹਨਾਂ ਦੀਆਂ ਲਿਖਤਾਂ ਪੜ੍ਹ ਵੇਖੋ) ਜੋ ਸਾਰੀ ਸ੍ਰਿਸ਼ਟੀ ਨੂੰ (ਸਾਂਝਾ) ਉਪਦੇਸ਼ ਕਰਦੇ ਰਹੇ ਹਨ।", wordMeaning = "ਬਿਆਸ = ਇਹ 'ਪਰਾਸ਼ਰ' ਰਿਸ਼ੀ ਦਾ ਪੁਤ੍ਰ ਸੀ, ਪਹਿਲਾਂ ਇਸ ਦਾ ਨਾਮ 'ਕ੍ਰਿਸ਼ਨਦ੍ਵੈਪਾਯਨ' ਸੀ ਕਿਉਂਕਿ ਇਸ ਦਾ ਰੰਗ ਕਾਲਾ (ਕ੍ਰਿਸ਼ਨ) ਸੀ ਤੇ ਇਹ ਜਜ਼ੀਰੇ (ਦ੍ਵੀਪ) ਵਿਚ ਜੰਮਿਆ ਸੀ; ਪਰ ਫਿਰ ਇਸ ਦਾ ਨਾਮ 'ਵਿਆਸ' ਪੈ ਗਿਆ। ਲਫ਼ਜ਼ 'ਵਿਆਸ' (ਬਿਆਸ) ਦਾ ਅਰਥ ਹੈ \"ਤਰਤੀਬ ਦੇਣ ਵਾਲਾ\"; ਇਸ ਦੀ ਬਾਬਤ ਖ਼ਿਆਲ ਹੈ ਕਿ ਇਸ ਰਿਸ਼ੀ ਨੇ ਵੇਦਾਂ ਨੂੰ ਮੌਜੂਦਾ ਤਰਤੀਬ ਦਿੱਤੀ ਸੀ (विव्यास वेदान् यस्मात्सः तस्माद् व्यास इति स्मृतः)। \"ਮਹਾਭਾਰਤ\" ਦਾ ਕਰਤਾ ਭੀ ਇਸੇ ਰਿਸ਼ੀ ਨੂੰ ਕਿਹਾ ਜਾਂਦਾ ਹੈ, ਅਠਾਰਾਂ ਪੁਰਾਣ, ਬ੍ਰਹਮ-ਸੂਤ੍ਰ ਤੇ ਹੋਰ ਕਈ ਪੁਸਤਕ ਭੀ ਇਸੇ ਦੇ ਲਿਖੇ ਮੰਨੇ ਜਾਂਦੇ ਹਨ। ਸੱਤ ਪ੍ਰਸਿੱਧ \"ਚਿਰਚੀਵੀਆਂ\" ਵਿਚੋਂ ਇਕ ਇਹ ਭੀ ਸੀ। ਸੁਕ = ਇਕ ਰਿਸ਼ੀ ਦਾ ਨਾਮ ਹੈ। ਨਾਰਦ = (नरस्य धर्मो नारं तत् ददाति स नारदः) ਬ੍ਰਹਮਾ ਦੇ ਦਸ ਪੁਤ੍ਰਾਂ ਵਿਚੋਂ ਇਕ ਸੀ, ਉਸ ਦੇ ਪੱਟ ਵਿਚੋਂ ਪੈਦਾ ਹੋਇਆ ਮੰਨਿਆ ਜਾਂਦਾ ਹੈ। ਇਸ ਦੀ ਬਾਬਤ ਇਹ ਮੰਨਿਆ ਜਾਂਦਾ ਹੈ ਕਿ ਇਹ ਦੇਵਤਿਆਂ ਦੇ ਸੁਨੇਹੇ ਮਨੁੱਖਾਂ ਪਾਸ ਤੇ ਮਨੁੱਖਾਂ ਦੀਆਂ ਲੋੜਾਂ ਦੇਵਤਿਆਂ ਪਾਸ ਅਪੜਾਂਦਾ ਸੀ। ਦੇਵਤਿਆਂ ਤੇ ਮਨੁੱਖਾਂ ਵਿਚ ਝਗੜੇ ਪਾਣ ਦਾ ਇਸ ਨੂੰ ਬੜਾ ਸ਼ੌਕ ਸੀ; ਸੋ, ਇਸ ਦਾ ਨਾਮ ਪੈ ਗਿਆ \"ਕਲਿਪ੍ਰਿਯ।\" \"ਵੀਣਾ\" ਸਾਜ਼ ਇਸੇ ਦੀ ਕਾਢ ਮੰਨਿਆ ਜਾਂਦਾ ਹੈ। ਇਸ ਨੇ ਇਕ 'ਸਿਮ੍ਰਿਤਿ' ਭੀ ਲਿਖੀ ਸੀ। ਬਚਨ = ਉਪਦੇਸ਼।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-191", gurmukhi = "ਮਃ ੩ ॥", transliteration = "mh 3 ||", translation = "Third Mehl:", hindi = "मः ३ ॥", punjabi = "ਤੀਜੀ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
