    BaniLine(id = "ramkali-ki-vaar-201", gurmukhi = "ਇਕਿ ਕੂੜਿ ਕੁਸਤਿ ਲਾਇਅਨੁ; ਮਨਮੁਖ ਵਿਗੂਤੀ ॥", transliteration = "ik koor kusat laaian; manmukh vigootee ||", translation = "He has linked some to falsehood and deception; these self-willed manmukhs are plundered.", hindi = "इकि कूड़ि कुसति लाइअनु; मनमुख विगूती ॥", punjabi = "ਉਸ ਨੇ ਕਈ ਜੀਵਾਂ ਨੂੰ ਝੂਠ ਤੇ ਠੱਗੀ ਵਿਚ ਲਾ ਰੱਖਿਆ ਹੈ, ਉਹ ਜੀਵ ਆਪਣੇ ਮਨ ਦੇ ਪਿੱਛੇ ਤੁਰ ਕੇ ਖ਼ੁਆਰ ਹੋ ਰਹੇ ਹਨ।", wordMeaning = "ਇਕਿ = ਕਈ ਜੀਵ। ਕੂੜਿ = ਕੂੜ ਵਿਚ। ਕੁਸਤਿ = ਕੁਸੱਤ ਵਿਚ। ਲਾਇਅਨੁ = ਲਾਏ ਹਨ ਉਸ ਨੇ।", startsAtMs = 0L, endsAtMs = 0L),
