    BaniLine(id = "ramkali-ki-vaar-251", gurmukhi = "ਸਭਨਾ ਸਾਹਿਬੁ ਏਕੁ ਹੈ; ਪੂਰੈ ਭਾਗਿ ਪਾਇਆ ਜਾਈ ॥੧੧॥", transliteration = "sabhnaa saahib ek hai; poorai bhaag paaiaa jaaee ||11||", translation = "The One Lord is the Master of all. He is found only by perfect destiny. ||11||", hindi = "सभना साहिबु एकु है; पूरै भागि पाइआ जाई ॥११॥", punjabi = "ਸਾਰੇ ਜੀਵਾਂ ਦਾ ਮਾਲਕ ਉਹੀ ਇਕ ਪਰਮਾਤਮਾ ਹੈ, ਪਰ ਮਿਲਦਾ ਪੂਰੀ ਕਿਸਮਤ ਨਾਲ ਹੈ ॥੧੧॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-252", gurmukhi = "ਸਲੋਕ ਮਃ ੧ ॥", transliteration = "salok mh 1 ||", translation = "Salok, First Mehl:", hindi = "सलोक मः १ ॥", punjabi = "ਸਲੋਕ ਪਹਿਲੀ ਪਾਤਿਸ਼ਾਹਿ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-253", gurmukhi = "ਨਾ ਸਤਿ. ਮੂੰਡ ਮੁਡਾਈ ਕੇਸੀ; ਨਾ ਸਤਿ. ਪੜਿਆ ਦੇਸ ਫਿਰਹਿ ॥", transliteration = "naa sat. moond mudaaee kesee; naa sat. priaa des phirah ||", translation = "There is no Truth in shaving one's head; there is no Truth is studying the scriptures or wandering in foreign lands.", hindi = "ना सति. मूंड मुडाई केसी; ना सति. पड़िआ देस फिरहि ॥", punjabi = "ਸਿਰ ਦੇ ਕੇਸ ਮੁਨਾਣ ਵਿਚ (ਭਾਵ, ਰੁੰਡ-ਮੁੰਡ ਹੋ ਜਾਣ ਵਿਚ) ਸਿੱਧੀ ਨਹੀਂ ਹੈ; ਇਸ ਗੱਲ ਵਿਚ ਭੀ (ਜਨਮ-ਮਨੋਰਥ ਦੀ) ਸਿੱਧੀ ਨਹੀਂ ਕਿ ਵਿਦਵਾਨ ਬਣ ਕੇ (ਹੋਰ ਲੋਕਾਂ ਨੂੰ ਚਰਚਾ ਵਿਚ ਜਿੱਤਣ ਲਈ) ਦੇਸਾਂ ਦੇਸਾਂ ਵਿਚ ਫਿਰੀਏ।", wordMeaning = "ਮੂੰਡ = ਸਿਰ। ਮੂੰਡ ਕੇਸੀ ਮੁਡਾਈ = ਸਿਰ ਦੇ ਕੇਸ ਮੁਨਾਇਆਂ {ਨੋਟ: ਹਰੇਕ ਕਿਸਮ ਦੇ ਖ਼ਿਆਲ ਦੇ ਨਾਲ ਲਫ਼ਜ਼ \"ਨਾਸਤਿ\" ਹਰ ਵਾਰੀ ਵਰਤਿਆ ਹੈ; ਸੋ, \"ਮੂੰਡ ਮੁਡਾਈ ਕੇਸੀ\" ਇਕੱਠਾ ਹੀ ਇਕ ਖ਼ਿਆਲ ਹੈ)।", startsAtMs = 0L, endsAtMs = 0L),
