    BaniLine(id = "ramkali-ki-vaar-255", gurmukhi = "ਨਾ ਸਤਿ. ਰੁਖੀ ਬਿਰਖੀ ਪਥਰ; ਆਪੁ ਤਛਾਵਹਿ. ਦੁਖ ਸਹਹਿ ॥", transliteration = "naa sat. rukhee birkhee pathar; aap tchhaavah. dukh sahah ||", translation = "There is no Truth in trees, plants or stones, in mutilating oneself or suffering in pain.", hindi = "ना सति. रुखी बिरखी पथर; आपु तछावहि. दुख सहहि ॥", punjabi = "ਰੁੱਖਾਂ ਬਿਰਖਾਂ ਤੇ ਪੱਥਰਾਂ ਵਿਚ ਭੀ ਸਿੱਧੀ ਨਹੀਂ ਹੈ, ਇਹ ਆਪਣੇ ਆਪ ਨੂੰ ਕਟਾਂਦੇ ਹਨ ਤੇ (ਕਈ ਕਿਸਮ ਦੇ) ਦੁੱਖ ਸਹਾਰਦੇ ਹਨ (ਭਾਵ, ਰੁੱਖਾਂ ਬਿਰਖਾਂ ਪੱਥਰਾਂ ਵਾਂਗ ਜੜ੍ਹ ਹੋ ਕੇ ਆਪਣੇ ਉਤੇ ਕਈ ਕਸ਼ਟ ਸਹਾਰਿਆਂ ਭੀ ਜਨਮ-ਮਨੋਰਥ ਦੀ ਸਿੱਧੀ ਪ੍ਰਾਪਤ ਨਹੀਂ ਹੁੰਦੀ)।", wordMeaning = "ਆਪੁ = ਆਪਣੇ ਆਪ ਨੂੰ। ਤਛਾਵਹਿ = ਕਟਾਂਦੇ ਹਨ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-256", gurmukhi = "ਜਿਸੁ ਹਥਿ ਸਿਧਿ. ਦੇਵੈ ਜੇ ਸੋਈ; ਜਿਸ ਨੋ ਦੇਇ ਤਿਸੁ ਆਇ ਮਿਲੈ ॥", transliteration = "jis hath sidh. devai je soee; jis no dei tis aai milai ||", translation = "He alone grants it, whose hands hold spritual perfection; he alone receives it, unto whom it is given.", hindi = "जिसु हथि सिधि. देवै जे सोई; जिस नो देइ तिसु आइ मिलै ॥", punjabi = "ਜਿਸ ਪ੍ਰਭੂ ਦੇ ਹੱਥ ਵਿਚ ਸਫਲਤਾ ਹੈ ਜੇ ਉਹ ਆਪ ਦੇਵੇ ਤਾਂ ਜਿਸ ਨੂੰ ਦੇਂਦਾ ਹੈ ਉਸ ਨੂੰ ਪ੍ਰਾਪਤ ਹੁੰਦੀ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L)
)

