    BaniLine(id = "ramkali-ki-vaar-264", gurmukhi = "ਸੋ ਗਿਰਹੀ; ਜੋ ਨਿਗ੍ਰਹੁ ਕਰੈ ॥", transliteration = "so girhee; jo nigrah krai ||", translation = "He alone is a householder, who restrains his passions", hindi = "सो गिरही; जो निग्रहु करै ॥", punjabi = "(ਅਸਲ) ਗ੍ਰਿਹਸਤੀ ਉਹ ਹੈ ਜੋ ਇੰਦ੍ਰਿਆਂ ਨੂੰ ਵਿਕਾਰਾਂ ਵਲੋਂ ਰੋਕਦਾ ਹੈ,", wordMeaning = "ਗਿਰਹੀ = ਗ੍ਰਿਹਸਤੀ। ਨਿਗ੍ਰਹੁ = ਇੰਦ੍ਰਿਆਂ ਨੂੰ ਵਿਕਾਰਾਂ ਵਲੋਂ ਰੋਕਣਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-265", gurmukhi = "ਸੋ ਗਿਰਹੀ; ਗੰਗਾ ਕਾ ਨੀਰੁ ॥", transliteration = "so girhee; gangaa kaa neer ||", translation = "such a householder is as pure as the water of the Ganges.", hindi = "सो गिरही; गंगा का नीरु ॥", punjabi = "ਉਹ ਗ੍ਰਿਹਸਤੀ ਗੰਗਾ ਜਲ (ਵਰਗਾ ਪਵਿਤ੍ਰ) ਹੋ ਜਾਂਦਾ ਹੈ।", wordMeaning = "ਨੀਰੁ = ਜਲ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-266", gurmukhi = "ਬੋਲੈ ਈਸਰੁ ਸਤਿ ਸਰੂਪੁ ॥", transliteration = "bolai eesar sat sroop ||", translation = "Says Eeshar, the Lord is the embodiment of Truth.", hindi = "बोलै ईसरु सति सरूपु ॥", punjabi = "ਜੇ ਈਸ਼ਰ (ਜੋਗੀ ਭੀ ਅਸਲ ਗ੍ਰਿਹਸਤੀ ਵਾਲੀ ਇਹ ਜੁਗਤਿ ਵਰਤ ਕੇ) ਸਦਾ-ਥਿਰ ਰਹਿਣ ਵਾਲੇ ਪ੍ਰਭੂ ਨੂੰ ਜਪੇ ਤਾਂ ਇਹ ਭੀ ਪਰਮ ਬ੍ਰਹਮ ਵਿਚ ਲੀਨ ਹੋ ਜਾਏ, ਇਸ ਦਾ ਕੋਈ (ਵੱਖਰਾ) ਰੂਪ ਰੇਖ ਨਾਹ ਰਹਿ ਜਾਏ (ਭਾਵ, ਹੇ ਈਸ਼ਰ ਜੋਗੀ! ਜੇ ਤੂੰ ਭੀ ਉਪਰ-ਦੱਸੀ ਜੁਗਤਿ ਨਾਲ ਪ੍ਰਭੂ ਨੂੰ ਜਪੇਂ,", wordMeaning = "ਸਤਿ = ਪਰਮ ਜੋਤਿ, ਪਰਮ ਆਤਮਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-267", gurmukhi = "ਪਰਮ ਤੰਤ ਮਹਿ; ਰੇਖ ਨ ਰੂਪੁ ॥੨॥", transliteration = "param tant mah; rekh na roop ||2||", translation = "The supreme essence of reality has no shape or form. ||2||", hindi = "परम तंत महि; रेख न रूपु ॥२॥", punjabi = "ਤਾਂ ਤੂੰ ਭੀ ਪਰਮ ਬ੍ਰਹਮ ਵਿਚ ਇਕ-ਮਿਕ ਹੋ ਜਾਏਂ; ਗ੍ਰਿਹਸਤ ਤਿਆਗਣ ਦੀ ਲੋੜ ਹੀ ਨਾਹ ਪਏਗੀ) ॥੨॥", wordMeaning = "ਤੰਤ = (ਸੰ: तंतु = The Supreme Brahm) ਪਰਮ ਜੋਤਿ, ਅਕਾਲ ਪੁਰਖ। ਪੁੰਨ = ਭਲਾਈ। ਦਾਨ = ਸੇਵਾ ॥੨॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-268", gurmukhi = "ਪੁੰਨ ਦਾਨ ਕਾ; ਕਰੇ ਸਰੀਰੁ ॥", transliteration = "punn daan kaa; kre sreer ||", translation = "He gives donations to charity with his body;", hindi = "पुंन दान का; करे सरीरु ॥", punjabi = "ਜੋ ਆਪਣਾ ਸਰੀਰ (ਭੀ) ਪੁੰਨ ਦਾਨ ਵਾਲਾ ਹੀ ਬਣਾ ਲੈਂਦਾ ਹੈ (ਭਾਵ, ਖ਼ਲਕਤ ਦੀ ਸੇਵਾ ਤੇ ਭਲਾਈ ਕਰਨ ਦਾ ਸੁਭਾਵ ਜਿਸ ਦੇ ਸਰੀਰ ਨਾਲ ਰਚ-ਮਿਚ ਜਾਂਦਾ ਹੈ);", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-269", gurmukhi = "ਸੋ ਅਉਧੂਤੀ. ਜੋ ਧੂਪੈ ਆਪੁ ॥", transliteration = "so audhootee. jo dhoopai aap ||", translation = "He alone is a detached hermit, who burns away his self-conceit.", hindi = "सो अउधूती. जो धूपै आपु ॥", punjabi = "(ਅਸਲ) ਅਵਧੂਤ ਉਹ ਹੈ ਜੋ ਆਪਾ-ਭਾਵ ਨੂੰ ਸਾੜ ਦੇਂਦਾ ਹੈ;", wordMeaning = "ਅਉਧੂਤੀ = ਅਵਧੂਤ, ਜਿਸ ਨੇ ਮਾਇਆ ਦੇ ਬੰਧਨ ਤੋੜ ਦਿੱਤੇ ਹਨ। ਧੂਪੈ = ਧੁਖਾਂਦਾ ਹੈ, ਸਾੜ ਦੇਂਦਾ ਹੈ। ਆਪੁ = ਆਪਾ-ਭਾਵ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-270", gurmukhi = "ਭਿਖਿਆ ਭੋਜਨੁ ਕਰੈ ਸੰਤਾਪੁ ॥", transliteration = "bhikhiaa bhojan krai santaap ||", translation = "He begs for suffering as his food.", hindi = "भिखिआ भोजनु करै संतापु ॥", punjabi = "ਜੋ ਖਿੱਝ ਨੂੰ ਮੰਗ ਮੰਗ ਕੇ ਲਿਆਂਦਾ ਹੋਇਆ ਭੋਜਨ ਬਣਾਂਦਾ ਹੈ (ਜੋ ਮੰਗ ਮੰਗ ਕੇ ਲਿਆਂਦੇ ਹੋਏ ਟੁਕੜੇ ਖਾਣ ਦੇ ਥਾਂ ਖਿੱਝ ਨੂੰ ਛਕ ਜਾਵੇ, ਮੁਕਾ ਦੇਵੇ);", wordMeaning = "ਭਿਖਿਆ ਭੋਜਨੁ = ਮੰਗ ਮੰਗ ਕੇ ਲਿਆਂਦਾ ਹੋਇਆ ਭੋਜਨ। ਸੰਤਾਪੁ = ਖਿੱਝ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-271", gurmukhi = "ਮਃ ੧ ॥", transliteration = "mh 1 ||", translation = "First Mehl:", hindi = "मः १ ॥", punjabi = "ਪਹਿਲੀ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-272", gurmukhi = "ਅਉਹਠ ਪਟਣ ਮਹਿ; ਭੀਖਿਆ ਕਰੈ ॥", transliteration = "auhath patan mah; bheekhiaa krai ||", translation = "In the city of the heart, he begs for charity.", hindi = "अउहठ पटण महि; भीखिआ करै ॥", punjabi = "ਜੋ ਹਿਰਦੇ ਰੂਪ ਸ਼ਹਿਰ ਵਿਚ ਟਿਕ ਕੇ (ਪ੍ਰਭੂ ਤੋਂ) ਖ਼ੈਰ ਮੰਗਦਾ ਹੈ,", wordMeaning = "ਅਉਹਠ = ਅਵਘੱਟ, ਹਿਰਦਾ। ਪਟਣ = ਸ਼ਹਿਰ", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-273", gurmukhi = "ਸੋ ਅਉਧੂਤੀ ਸਿਵ ਪੁਰਿ ਚੜੈ ॥", transliteration = "so audhootee siv pur chrai ||", translation = "Such a renunciate ascends to the City of God.", hindi = "सो अउधूती सिव पुरि चड़ै ॥", punjabi = "ਉਹ ਅਵਧੂਤ ਕਲਿਆਣ-ਰੂਪ ਪ੍ਰਭੂ ਦੇ ਦੇਸ ਵਿਚ ਅੱਪੜ ਜਾਂਦਾ ਹੈ।", wordMeaning = "ਸਿਵ = ਕਲਿਆਣ-ਰੂਪ ਪ੍ਰਭੂ। ਪੁਰਿ = ਪੁਰੀ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-274", gurmukhi = "ਬੋਲੈ ਗੋਰਖੁ ਸਤਿ ਸਰੂਪੁ ॥", transliteration = "bolai gorakh sat sroop ||", translation = "Says Gorakh, God is the embodiment of Truth;", hindi = "बोलै गोरखु सति सरूपु ॥", punjabi = "ਜੇ ਗੋਰਖ (ਜੋਗੀ ਭੀ ਇਸ ਅਵਧੂਤ ਦੀ ਜੁਗਤਿ ਵਰਤ ਕੇ) ਸਤਿ-ਸਰੂਪ ਪ੍ਰਭੂ ਨੂੰ ਜਪੇ,", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-275", gurmukhi = "ਪਰਮ ਤੰਤ ਮਹਿ; ਰੇਖ ਨ ਰੂਪੁ ॥੩॥", transliteration = "param tant mah; rekh na roop ||3||", translation = "the supreme essence of reality has no shape or form. ||3||", hindi = "परम तंत महि; रेख न रूपु ॥३॥", punjabi = "ਤਾਂ (ਇਹ ਗੋਰਖ ਭੀ) ਪਰਮ ਬ੍ਰਹਮ ਵਿਚ ਲੀਨ ਹੋ ਜਾਏ, ਇਸ ਦਾ ਕੋਈ (ਵੱਖਰਾ) ਰੂਪ ਰੇਖ ਨਾਹ ਰਹਿ ਜਾਏ ॥੩॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-276", gurmukhi = "ਅਰਧ ਉਰਧ; ਕਰੇ ਨਿਰੰਜਨ ਵਾਸੁ ॥", transliteration = "aradh uradh; kre niranjan vaas ||", translation = "He sees the Immaculate Lord dwelling in both the upper and lower regions.", hindi = "अरध उरध; करे निरंजन वासु ॥", punjabi = "ਹਰ ਥਾਂ ਮਾਇਆ-ਰਹਿਤ ਪ੍ਰਭੂ ਦਾ ਨਿਵਾਸ ਜਾਣਦਾ ਹੈ;", wordMeaning = "ਅਰਧ = (संः अर्ध = ਨੇੜੇ; ਜਿਵੇਂ, \"ਅਰਧਦੇਵ\" ਦੇਵਤਿਆਂ ਦੇ ਨੇੜੇ ਰਹਿਣ ਵਾਲਾ), ਅੱਧ ਵਿਚਕਾਰ; ਨੇੜੇ। ਉਰਧ = (संः ऊध्र्व) ਉਤਾਂਹ। ਅਰਧ ਉਰਧ = ਨੇੜੇ ਤੇ ਉਤਾਂਹ, (ਭਾਵ) ਹਰ ਥਾਂ। ਨਿਰੰਜਨ = ਮਾਇਆ ਤੋਂ ਰਹਿਤ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-277", gurmukhi = "ਚੰਦ ਸੂਰਜ ਕੀ ਪਾਏ ਗੰਢਿ ॥", transliteration = "chand sooraj kee paae gandh ||", translation = "He balances the sun and the moon energies.", hindi = "चंद सूरज की पाए गंढि ॥", punjabi = "(ਆਪਣੇ ਹਿਰਦੇ ਵਿਚ) ਸ਼ਾਂਤੀ ਤੇ ਗਿਆਨ ਦੋਹਾਂ ਨੂੰ ਇਕੱਠਾ ਕਰਦਾ ਹੈ;", wordMeaning = "ਚੰਦ = ਸੀਤਲਤਾ, ਸ਼ਾਂਤੀ। ਸੂਰਜ = ਗਿਆਨ ਦਾ ਤੇਜ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-278", gurmukhi = "ਸੋ ਉਦਾਸੀ; ਜਿ ਪਾਲੇ ਉਦਾਸੁ ॥", transliteration = "so udaasee; ji paale udaas ||", translation = "He alone is an Udasi, a shaven-headed renunciate, who embraces renunciation.", hindi = "सो उदासी; जि पाले उदासु ॥", punjabi = "(ਅਸਲ) ਵਿਰਕਤ ਉਹ ਹੈ ਜੋ ਉਪਰਾਮਤਾ ਨੂੰ ਸਦਾ ਕਾਇਮ ਰੱਖਦਾ ਹੈ,", wordMeaning = "ਉਦਾਸੀ = ਵਿਰਕਤ, ਮਾਇਆ ਤੋਂ ਉਪਰਾਮ। ਉਦਾਸੁ = ਮਾਇਆ ਤੋਂ ਉਪਰਾਮਤਾ। ਪਾਲੇ = ਸਦਾ ਕਾਇਮ ਰੱਖਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-279", gurmukhi = "ਮਃ ੧ ॥", transliteration = "mh 1 ||", translation = "First Mehl:", hindi = "मः १ ॥", punjabi = "ਪਹਿਲੀ ਪਾਤਿਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-280", gurmukhi = "ਤਿਸੁ ਉਦਾਸੀ ਕਾ; ਪੜੈ ਨ ਕੰਧੁ ॥", transliteration = "tis udaasee kaa; prai na kandh ||", translation = "The body-wall of such an Udasi does not collapse.", hindi = "तिसु उदासी का; पड़ै न कंधु ॥", punjabi = "ਉਸ ਵਿਰਕਤ ਮਨੁੱਖ ਦਾ ਸਰੀਰ (ਵਿਕਾਰਾਂ ਵਿਚ) ਨਹੀਂ ਡਿੱਗਦਾ।", wordMeaning = "ਪੜੈ ਨ = ਨਹੀਂ ਢਹਿੰਦਾ। ਕੰਧੁ = ਸਰੀਰ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-281", gurmukhi = "ਬੋਲੈ ਗੋਪੀ ਚੰਦੁ ਸਤਿ ਸਰੂਪੁ ॥", transliteration = "bolai gopee chand sat sroop ||", translation = "Says Gopi Chand, God is the embodiment of Truth;", hindi = "बोलै गोपी चंदु सति सरूपु ॥", punjabi = "ਜੇ ਗੋਪੀ ਚੰਦ (ਭੀ ਇਸ ਉਦਾਸੀ ਦੀ ਜੁਗਤਿ ਵਰਤ ਕੇ) ਸਤਿ-ਸਰੂਪ ਪ੍ਰਭੂ ਨੂੰ ਜਪੇ,", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-282", gurmukhi = "ਪਰਮ ਤੰਤ ਮਹਿ; ਰੇਖ ਨ ਰੂਪੁ ॥੪॥", transliteration = "param tant mah; rekh na roop ||4||", translation = "the supreme essence of reality has no shape or form. ||4||", hindi = "परम तंत महि; रेख न रूपु ॥४॥", punjabi = "ਤਾਂ (ਇਹ ਗੋਪੀ ਚੰਦ ਭੀ) ਪਰਮ ਬ੍ਰਹਮ ਵਿਚ ਲੀਨ ਹੋ ਜਾਏ, ਇਸ ਦਾ ਕੋਈ (ਵੱਖਰਾ) ਰੂਪ ਰੇਖ ਨਾਹ ਰਹਿ ਜਾਏ ॥੪॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-283", gurmukhi = "ਸੋ ਪਾਖੰਡੀ; ਜਿ ਕਾਇਆ ਪਖਾਲੇ ॥", transliteration = "so paakhandee; ji kaaiaa pkhaale ||", translation = "He alone is a Paakhandi, who cleanses his body of filth.", hindi = "सो पाखंडी; जि काइआ पखाले ॥", punjabi = "(ਅਸਲੀ) ਨਾਸਤਕ ਉਹ ਹੈ ਜੋ (ਪਰਮਾਤਮਾ ਦੀ ਹਸਤੀ ਨਾਹ ਮੰਨਣ ਦੇ ਥਾਂ) ਸਰੀਰ ਨੂੰ ਧੋਵੇ (ਭਾਵ, ਸਰੀਰ ਵਿਚੋਂ ਪਾਪਾਂ ਦੀ ਹਸਤੀ ਮਿਟਾ ਦੇਵੇ),", wordMeaning = "ਪਾਖੰਡੀ = ਨਾਸਤਕ ਵਾਮ-ਮਾਰਗੀਆਂ ਦਾ ਇਕ ਫ਼ਿਰਕਾ। संः पाखंड = a heretic)। ਪਖਾਲੇ = ਧੋਵੇ, ਪਾਪਾਂ ਤੋਂ ਸਾਫ਼ ਰੱਖੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-284", gurmukhi = "ਮਃ ੧ ॥", transliteration = "mh 1 ||", translation = "First Mehl:", hindi = "मः १ ॥", punjabi = "ਪਹਿਲੀ ਪਾਤਿਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-285", gurmukhi = "ਸੁਪਨੈ ਬਿੰਦੁ; ਨ ਦੇਈ ਝਰਣਾ ॥", transliteration = "supnai bind; na deee jharnaa ||", translation = "He does not waste his energy in wet dreams.", hindi = "सुपनै बिंदु; न देई झरणा ॥", punjabi = "ਸੁਫ਼ਨੇ ਵਿਚ ਭੀ ਵੀਰਜ ਨੂੰ ਡਿੱਗਣ ਨਹੀਂ ਦੇਂਦਾ (ਭਾਵ, ਸੁਫ਼ਨੇ ਵਿਚ ਭੀ ਆਪਣੇ ਆਪ ਨੂੰ ਕਾਮ-ਵੱਸ ਨਹੀਂ ਹੋਣ ਦੇਂਦਾ);", wordMeaning = "ਬਿੰਦੁ = ਵੀਰਜ।", startsAtMs = 0L, endsAtMs = 0L),
