    BaniLine(id = "ramkali-ki-vaar-312", gurmukhi = "ਮਨਮੁਖ. ਹਰਿ ਮੰਦਰ ਕੀ ਸਾਰ, ਨ ਜਾਣਨੀ; ਤਿਨੀ ਜਨਮੁ ਗਵਾਤਾ ॥", transliteration = "manmukh. har mandar kee saar, na jaannee; tinee janam gvaataa ||", translation = "The self-willed manmukh does not appreciate the value of the Lord's temple; they waste away and lose their lives.", hindi = "मनमुख. हरि मंदर की सार, न जाणनी; तिनी जनमु गवाता ॥", punjabi = "ਪਰ ਮਨ ਦੇ ਪਿੱਛੇ ਤੁਰਨ ਵਾਲੇ ਬੰਦੇ (ਇਸ ਮਨੁੱਖਾ ਸਰੀਰ) \"ਹਰਿ ਮੰਦਰੁ\" ਦੀ ਕਦਰ ਨਹੀਂ ਜਾਣਦੇ, ਉਹ ਮਨੁੱਖਾ ਜਨਮ (ਮਨ ਦੇ ਪਿੱਛੇ ਤੁਰ ਕੇ ਹੀ) ਗੰਵਾ ਜਾਂਦੇ ਹਨ।", wordMeaning = "ਹਰਿ ਮੰਦਰ = ਰੱਬ ਦੇ ਘਰ ਦੀ। ਸਾਰ = ਮੁੱਲ, ਕਦਰ।", startsAtMs = 0L, endsAtMs = 0L),
