    BaniLine(id = "ramkali-ki-vaar-314", gurmukhi = "ਸਭ ਮਹਿ ਇਕੁ ਵਰਤਦਾ; ਗੁਰਸਬਦੀ ਪਾਇਆ ਜਾਈ ॥੧੨॥", transliteration = "sabh mah ik varatdaa; gurasabdee paaiaa jaaee ||12||", translation = "The One Lord is pervading in all; through the Word of the Guru's Shabad, He can be found. ||12||", hindi = "सभ महि इकु वरतदा; गुरसबदी पाइआ जाई ॥१२॥", punjabi = "(ਉਂਞ ਤਾਂ) ਸਾਰਿਆਂ ਵਿਚ ਇਕ ਪ੍ਰਭੂ ਹੀ ਵਿਆਪਕ ਹੈ, ਪਰ ਲੱਭਦਾ ਹੈ ਗੁਰੂ ਦੇ ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ ॥੧੨॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
