    BaniLine(id = "ramkali-ki-vaar-316", gurmukhi = "ਮੂਰਖੁ ਓਹੁ ਜਿ ਮੁਗਧੁ ਹੈ; ਅਹੰਕਾਰੇ ਮਰਣਾ ॥", transliteration = "moorakh oh ji mugadh hai; ahankaare marnaa ||", translation = "A fool is stupid; he dies of egotism.", hindi = "मूरखु ओहु जि मुगधु है; अहंकारे मरणा ॥", punjabi = "ਜੋ ਮਨੁੱਖ ਮਾਇਆ ਦਾ ਠੱਗਿਆ ਹੋਇਆ ਹੋਵੇ ਤੇ ਜੋ ਅਹੰਕਾਰ ਵਿਚ ਆਤਮਕ ਮੌਤੇ ਮਰਿਆ ਹੋਇਆ ਹੋਵੇ, ਉਸ ਨੂੰ ਮੂਰਖ ਕਹੀਦਾ ਹੈ।", wordMeaning = "ਮੁਗਧੁ = ਮੋਹਿਆ ਹੋਇਆ, ਮਾਇਆ ਦਾ ਠੱਗਿਆ ਹੋਇਆ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-317", gurmukhi = "ਮੂਰਖ ਕੇ ਕਿਆ ਲਖਣ ਹੈ; ਕਿਆ ਮੂਰਖ ਕਾ ਕਰਣਾ ॥", transliteration = "moorakh ke kiaa lakhan hai; kiaa moorakh kaa karnaa ||", translation = "What are the signs of the fool? What does the fool do?", hindi = "मूरख के किआ लखण है; किआ मूरख का करणा ॥", punjabi = "ਮੂਰਖ ਦੇ ਲੱਛਣ ਕੀਹ ਹਨ? ਮੂਰਖ ਦੀ ਕਰਤੂਤ ਕੈਸੀ ਹੁੰਦੀ ਹੈ?", wordMeaning = "ਲਖਣ = ਲੱਛਣ, ਇਲਾਮਤਾਂ। ਕਰਣਾ = ਕਰਤੱਬ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-318", gurmukhi = "ਅਤਿ ਪਿਆਰਾ ਪਵੈ ਖੂਹਿ; ਕਿਹੁ ਸੰਜਮੁ ਕਰਣਾ ॥", transliteration = "at piaaraa pvai khooh; kih sanjam karnaa ||", translation = "If someone's beloved friend falls into the pit, what can be used to pull him out?", hindi = "अति पिआरा पवै खूहि; किहु संजमु करणा ॥", punjabi = "ਮਾਇਆ ਨਾਲ ਬਹੁਤਾ ਪਿਆਰ ਕਰਨ ਵਾਲਾ ਮਨੁੱਖ (ਮਾਇਆ ਦੇ ਮੋਹ ਦੇ) ਖੂਹ ਵਿਚ ਡਿੱਗਾ ਰਹਿੰਦਾ ਹੈ। ਉਸ ਦੇ ਬਚਾਉ ਦਾ ਕੇਹੜਾ ਉੱਦਮ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ?", wordMeaning = "ਅਤਿ ਪਿਆਰਾ = ਮਾਇਆ ਨਾਲ ਬਹੁਤ ਪਿਆਰ ਕਰਨ ਵਾਲਾ। ਕਿਹੁ ਸੰਜਮ ਕਰਣਾ = ਬਚਾਉ ਦਾ ਕੇਹੜਾ ਉੱਦਮ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ? ਖੂਹਿ = ਮਾਇਆ ਦੇ ਖੂਹ ਵਿਚ। ਸੰਜਮੁ = ਬਚਾਉ ਦਾ ਉੱਦਮ। ਕਿਹੁ = ਕਿਛੁ, ਕੋਈ।", startsAtMs = 0L, endsAtMs = 0L),
