    BaniLine(id = "ramkali-ki-vaar-320", gurmukhi = "ਗੁਰਮੁਖਿ ਹੋਇ ਸੁ ਕਰੇ ਵੀਚਾਰੁ; ਓਸੁ ਅਲਿਪਤੋ ਰਹਣਾ ॥", transliteration = "gurmukh hoi su kre veechaar; os alipto rahnaa ||", translation = "One who becomes Gurmukh contemplates the Lord, and remains detached.", hindi = "गुरमुखि होइ सु करे वीचारु; ओसु अलिपतो रहणा ॥", punjabi = "ਜਿਹੜਾ ਮਨੁੱਖ ਗੁਰੂ ਦੀ ਸਰਨ ਪੈਂਦਾ ਹੈ ਉਹ ਇਸ ਤੇ ਵਿਚਾਰ ਕਰਦਾ ਹੈ ਤੇ (ਇਸ ਮਾਇਆ ਦੇ ਮੋਹ-ਰੂਪ ਖੂਹ ਤੋਂ) ਵੱਖਰਾ ਰਹਿੰਦਾ ਹੈ।", wordMeaning = "ਅਲਿਪਤ = ਵੱਖਰਾ, ਨਿਰਾਲਾ।", startsAtMs = 0L, endsAtMs = 0L)
)

