    BaniLine(id = "ramkali-ki-vaar-325", gurmukhi = "ਮਃ ੧ ॥", transliteration = "mh 1 ||", translation = "First Mehl:", hindi = "मः १ ॥", punjabi = "ਪਹਿਲੀ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-326", gurmukhi = "ਤਲਬਾ ਪਉਸਨਿ ਆਕੀਆ; ਬਾਕੀ ਜਿਨਾ ਰਹੀ ॥", transliteration = "talbaa pausan aakeeaa; baakee jinaa rhee ||", translation = "Those rebels who have unpaid accounts shall be called out.", hindi = "तलबा पउसनि आकीआ; बाकी जिना रही ॥", punjabi = "ਜਿਨ੍ਹਾਂ ਜਿਨ੍ਹਾਂ ਵਲ ਲੇਖੇ ਦੀ ਬਾਕੀ ਰਹਿ ਜਾਂਦੀ ਹੈ ਉਹਨਾਂ ਉਹਨਾਂ ਮਨਮੁਖਾਂ ਨੂੰ ਸੱਦੇ ਪੈਣਗੇ।", wordMeaning = "ਤਲਬਾ = ਸੱਦੇ। ਆਕੀ = ਬਾਗ਼ੀ। ਬਾਕੀ = ਲੇਖੇ ਵਿਚੋਂ ਬਕਾਇਆ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-327", gurmukhi = "ਅਜਰਾਈਲੁ ਫਰੇਸਤਾ; ਹੋਸੀ ਆਇ ਤਈ ॥", transliteration = "ajraaeel phrestaa; hosee aai taee ||", translation = "Azraa-eel, the Angel of Death, shall be appointed to punish them.", hindi = "अजराईलु फरेसता; होसी आइ तई ॥", punjabi = "ਮੌਤ ਦਾ ਫ਼ਰਿਸ਼ਤਾ (ਕੀਤੇ ਕਰਮਾਂ ਅਨੁਸਾਰ ਦੁੱਖ ਦੇਣ ਲਈ ਸਿਰ ਤੇ) ਆ ਤਿਆਰ ਖੜਾ ਹੋਵੇਗਾ।", wordMeaning = "ਅਜਰਾਈਲੁ ਫਰੇਸਤਾ = ਮੌਤ ਦਾ ਫ਼ਰਿਸ਼ਤਾ। ਤਈ = ਤਿਆਰ, ਤਈਨਾਤ, ਮੁਕੱਰਰ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-328", gurmukhi = "ਆਵਣੁ ਜਾਣੁ. ਨ ਸੁਝਈ; ਭੀੜੀ ਗਲੀ ਫਹੀ ॥", transliteration = "aavan jaan. na sujhaee; bheeree glee phhee ||", translation = "They will find no way to escape coming and going in reincarnation; they are trapped in the narrow path.", hindi = "आवणु जाणु. न सुझई; भीड़ी गली फही ॥", punjabi = "ਉਸ ਔਕੜ ਵਿਚ ਫਸੀ ਹੋਈ ਜਿੰਦ ਨੂੰ (ਉਸ ਵੇਲੇ) ਕੁਝ ਅਹੁੜਦਾ ਨਹੀਂ।", wordMeaning = "ਫਹੀ = ਫਸੀ ਹੋਈ (ਜਿੰਦ) ਨੂੰ। ਆਵਣ ਜਾਣੁ = ਕੋਈ ਚਾਰਾ, ਕਿੱਧਰ ਜਾਵਾਂ ਕੀਹ ਕਰਾਂ? = ਇਹ ਗੱਲ", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-329", gurmukhi = "ਕੂੜ ਨਿਖੁਟੇ ਨਾਨਕਾ; ਓੜਕਿ ਸਚਿ ਰਹੀ ॥੨॥", transliteration = "koor nikhute naankaa; orak sach rhee ||2||", translation = "Falsehood will come to an end, O Nanak, and Truth will prevail in the end. ||2||", hindi = "कूड़ निखुटे नानका; ओड़कि सचि रही ॥२॥", punjabi = "ਹੇ ਨਾਨਕ! ਕੂੜ ਦੇ ਵਪਾਰੀ ਹਾਰ ਕੇ ਜਾਂਦੇ ਹਨ, ਸੱਚ ਦਾ ਸਉਦਾ ਕੀਤਿਆਂ ਹੀ ਅੰਤ ਨੂੰ ਰਹਿ ਆਉਂਦੀ ਹੈ ॥੨॥", wordMeaning = "ਕੂੜ = ਕੂੜ ਕਮਾਣ ਵਾਲੇ। ਨਿਖੁਟੇ = ਹਾਰ ਜਾਂਦੇ ਹਨ। ਸਚਿ = ਸੱਚ ਦੀ ਰਾਹੀਂ, ਸੱਚਾ ਸੌਦਾ ਕੀਤਿਆਂ ॥੨॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-330", gurmukhi = "ਪਉੜੀ ॥", transliteration = "pauree ||", translation = "Pauree:", hindi = "पउड़ी ॥", punjabi = "ਪਉੜੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-331", gurmukhi = "ਹਰਿ ਕੀ ਕੀਮਤਿ. ਨਾ ਪਵੈ; ਕਿਛੁ ਕਹਣੁ. ਨ ਜਾਪੈ ॥", transliteration = "har kee keemat. naa pvai; kichh kahan. na jaapai ||", translation = "The Lord's value cannot be estimated; nothing can be said about it.", hindi = "हरि की कीमति. ना पवै; किछु कहणु. न जापै ॥", punjabi = "ਪਰਮਾਤਮਾ (ਦੀ ਵਡਿਆਈ) ਦਾ ਮੁੱਲ ਨਹੀਂ ਪੈ ਸਕਦਾ, ਕੋਈ ਗੱਲ ਅਹੁੜਦੀ ਨਹੀਂ (ਜਿਸ ਨਾਲ) ਉਸ ਦੀ ਵਡਿਆਈ ਬਿਆਨ ਕਰ ਸਕੀਏ।", wordMeaning = "ਨ ਜਾਪੈ = ਨਹੀਂ ਸੁੱਝਦਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-332", gurmukhi = "ਹਰਿ ਕਾ ਸਭੁ ਸਰੀਰੁ ਹੈ; ਹਰਿ ਰਵਿ ਰਹਿਆ ਸਭੁ ਆਪੈ ॥", transliteration = "har kaa sabh sreer hai; har rav rhiaa sabh aapai ||", translation = "The body and everything belongs to the Lord; the Lord Himself is all-pervading.", hindi = "हरि का सभु सरीरु है; हरि रवि रहिआ सभु आपै ॥", punjabi = "ਇਹ ਸਾਰਾ (ਜਗਤ ਦਾ ਆਕਾਰ) ਪਰਮਾਤਮਾ ਦਾ (ਮਾਨੋ) ਸਰੀਰ ਹੈ, ਹਰ ਥਾਂ ਪ੍ਰਭੂ ਆਪ ਹੀ ਵਿਆਪਕ ਹੈ।", wordMeaning = "ਸਚੁ = ਹਰ ਥਾਂ। ਆਪੈ = ਆਪ ਹੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-333", gurmukhi = "ਸਭੁ ਮਨੁ ਤਨੁ ਹਰਿਆ ਹੋਇਆ; ਅਹੰਕਾਰੁ ਗਵਾਪੈ ॥", transliteration = "sabh man tan hriaa hoiaa; ahankaar gvaapai ||", translation = "The mind and body are totally rejuvenated, and egotism is eradicated.", hindi = "सभु मनु तनु हरिआ होइआ; अहंकारु गवापै ॥", punjabi = "ਉਸ ਦਾ ਮਨ ਤੇ ਤਨ ਖਿੜ ਆਉਂਦਾ ਹੈ ਤੇ ਅਹੰਕਾਰ ਨਾਸ ਹੋ ਜਾਂਦਾ ਹੈ)।", wordMeaning = "ਗਵਾਪੈ = ਨਾਸ ਹੋ ਜਾਂਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-334", gurmukhi = "ਗੁਰ ਪਰਸਾਦੀ ਸਾਲਾਹੀਐ; ਹਰਿ ਭਗਤੀ ਰਾਪੈ ॥", transliteration = "gur parsaadee saalaaheeai; har bhagtee raapai ||", translation = "By Guru's Grace, one praises the Lord, imbued with feelings of devotion.", hindi = "गुर परसादी सालाहीऐ; हरि भगती रापै ॥", punjabi = "ਸਤਿਗੁਰੂ ਦੀ ਕਿਰਪਾ ਨਾਲ ਪਰਮਾਤਮਾ ਦੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਕੀਤੀ ਜਾ ਸਕਦੀ ਹੈ (ਜੋ ਕਰਦਾ ਹੈ ਉਹ ਪ੍ਰਭੂ ਦੀ ਭਗਤੀ ਵਿਚ ਰੰਗਿਆ ਜਾਂਦਾ ਹੈ।", wordMeaning = "ਰਾਪੈ = ਰੰਗਿਆ ਜਾਈਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-335", gurmukhi = "ਸਹੰਸਰ ਦਾਨ ਦੇ; ਇੰਦ੍ਰੁ ਰੋਆਇਆ ॥", transliteration = "sahansar daan de; indr roaaiaa ||", translation = "Branded with a thousand marks of disgrace, Indra cried in shame.", hindi = "सहंसर दान दे; इंद्रु रोआइआ ॥", punjabi = "(ਗੋਤਮ ਰਿਸ਼ੀ ਨੇ) ਹਜ਼ਾਰ (ਭਗਾਂ) ਦਾ ਡੰਨ ਦੇ ਕੇ ਇੰਦਰ ਨੂੰ ਰੁਆ ਦਿੱਤਾ;", wordMeaning = "ਸਹੰਸਰ = ਹਜ਼ਾਰ। ਦਾਨ = ਡੰਨ। ਹਜ਼ਾਰ ਭਗਾਂ ਦਾ ਡੰਨ ਜੋ ਇੰਦਰ ਦੇਵਤੇ ਨੂੰ ਗੋਤਮ ਰਿਸ਼ੀ ਨੇ ਸਰਾਪ ਦੇ ਕੇ ਲਾਇਆ ਸੀ। ਇੰਦਰ ਨੇ ਰਿਸ਼ੀ ਦੀ ਇਸਤ੍ਰੀ ਅਹੱਲਿਆ ਨਾਲ ਧੋਖਾ ਦੇ ਕੇ ਸੰਗ ਕੀਤਾ ਸੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-336", gurmukhi = "ਸਭੁ ਕਿਛੁ ਹਰਿ ਕਾ ਖੇਲੁ ਹੈ; ਗੁਰਮੁਖਿ ਕਿਸੈ ਬੁਝਾਈ ॥੧੩॥", transliteration = "sabh kichh har kaa khel hai; gurmukh kisai bujhaaee ||13||", translation = "Everything is the play of the Lord. The Gurmukh understands this. ||13||", hindi = "सभु किछु हरि का खेलु है; गुरमुखि किसै बुझाई ॥१३॥", punjabi = "ਇਹ ਸਾਰਾ ਜਗਤ ਪ੍ਰਭੂ ਦਾ ਬਣਾਇਆ ਹੋਇਆ ਤਮਾਸ਼ਾ ਹੈ, ਸਤਿਗੁਰੂ ਦੀ ਰਾਹੀਂ ਕਿਸੇ ਵਿਰਲੇ ਨੂੰ ਇਸ ਖੇਡ ਦੀ ਸਮਝ ਦੇਂਦਾ ਹੈ ॥੧੩॥", wordMeaning = "ਕਿਸੈ = ਕਿਸੇ ਵਿਰਲੇ ਨੂੰ ॥੧੩॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-337", gurmukhi = "ਸਲੋਕੁ ਮਃ ੧ ॥", transliteration = "salok mh 1 ||", translation = "Salok, First Mehl:", hindi = "सलोकु मः १ ॥", punjabi = "ਸਲੋਕ ਪਹਿਲੀ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-338", gurmukhi = "ਐਸੀ; ਦਰਗਹ ਮਿਲੈ ਸਜਾਇ ॥", transliteration = "aisee; daragah milai sjaai ||", translation = "Such is the punishment received in the Court of the Lord.", hindi = "ऐसी; दरगह मिलै सजाइ ॥", punjabi = "ਪ੍ਰਭੂ ਦੀ ਹਜ਼ੂਰੀ ਵਿਚੋਂ ਅਜੇਹੀ ਹੀ ਸਜ਼ਾ ਮਿਲਦੀ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-339", gurmukhi = "ਪਰਸ ਰਾਮੁ ਰੋਵੈ; ਘਰਿ ਆਇਆ ॥", transliteration = "paras raam rovai; ghar aaiaa ||", translation = "Paras Raam returned home crying.", hindi = "परस रामु रोवै; घरि आइआ ॥", punjabi = "(ਸ੍ਰੀ ਰਾਮ ਚੰਦ੍ਰ ਤੋਂ ਆਪਣਾ ਬਲ ਖੁਹਾ ਕੇ) ਪਰਸ ਰਾਮ ਘਰ ਆ ਕੇ ਰੋਇਆ।", wordMeaning = "ਪਰਸ ਰਾਮੁ = ਬ੍ਰਾਹਮਣ ਸੀ, ਇਸ ਦੇ ਪਿਤਾ ਜਮਦਗਨੀ ਨੂੰ ਸਹੱਸ੍ਰਬਾਹੂ ਨੇ ਮਾਰ ਦਿੱਤਾ ਸੀ; ਬਦਲੇ ਦੀ ਅੱਗ ਵਿਚ ਪਰਸਰਾਮ ਨੇ ਖੱਤ੍ਰੀ-ਕੁਲ ਦਾ ਨਾਸ ਕਰਨਾ ਸ਼ੁਰੂ ਕੀਤਾ, ਪਰ ਜਦੋਂ ਇਸ ਨੇ ਸ੍ਰੀ ਰਾਮ ਚੰਦ੍ਰ ਜੀ ਤੇ ਆਪਣਾ ਕੁਹਾੜਾ ਚੁੱਕਿਆ ਤਾਂ ਉਹਨਾਂ ਇਸ ਦਾ ਬਲ ਖਿੱਚ ਲਿਆ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-340", gurmukhi = "ਰੋਵੈ ਰਾਮੁ; ਨਿਕਾਲਾ ਭਇਆ ॥", transliteration = "rovai raam; nikaalaa bhaiaa ||", translation = "Rama wept when he was sent into exile,", hindi = "रोवै रामु; निकाला भइआ ॥", punjabi = "ਰਾਮ ਜੀ ਭੀ ਰੋਏ, ਜਦੋਂ ਰਾਮ (ਜੀ) ਨੂੰ ਦੇਸ-ਨਿਕਾਲਾ ਮਿਲਿਆ,", wordMeaning = "ਨਿਕਾਲਾ = ਦੇਸ-ਨਿਕਾਲਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-341", gurmukhi = "ਅਜੈ ਸੁ ਰੋਵੈ; ਭੀਖਿਆ ਖਾਇ ॥", transliteration = "ajai su rovai; bheekhiaa khaai ||", translation = "Ajai cried and wept, when he was made to eat the manure he had given, pretending it was charity.", hindi = "अजै सु रोवै; भीखिआ खाइ ॥", punjabi = "ਰਾਜਾ ਅਜੈ ਰੋਇਆ ਜਦੋਂ ਉਸ ਨੂੰ (ਲਿੱਦ ਦੀ ਦਿੱਤੀ) ਭਿੱਖਿਆ ਖਾਣੀ ਪਈ,", wordMeaning = "ਅਜੈ = ਰਾਜਾ ਅਜੈ ਨੇ (ਜੋ ਸ੍ਰੀ ਰਾਮ ਚੰਦ੍ਰ ਜੀ ਦਾ ਦਾਦਾ ਸੀ) ਇਕ ਸਾਧੂ ਨੂੰ ਭਿੱਖਿਆ ਵਿਚ ਲਿੱਦ ਦਿੱਤੀ ਸੀ, ਪਿੱਛੋਂ ਉਸ ਨੂੰ ਆਪ ਖਾਣੀ ਪਈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-342", gurmukhi = "ਜਿਨਿ ਸੀਤਾ ਆਦੀ; ਡਉਰੂ ਵਾਇ ॥", transliteration = "jin seetaa aadee; dauroo vaai ||", translation = "Wept when he lost Sri Lanka.", hindi = "जिनि सीता आदी; डउरू वाइ ॥", punjabi = "ਜਿਸ ਨੇ ਸਾਧੂ ਬਣ ਕੇ ਸੀਤਾ (ਚੁਰਾ) ਲਿਆਂਦੀ ਸੀ।", wordMeaning = "ਡਉਰੂ ਵਾਇ = ਡਉਰੂ ਵਜਾ ਕੇ, ਸਾਧੂ ਦਾ ਭੇਸ ਕਰ ਕੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-343", gurmukhi = "ਸੀਤਾ ਲਖਮਣੁ; ਵਿਛੁੜਿ ਗਇਆ ॥", transliteration = "seetaa lakhaman; vichhur gaiaa ||", translation = "and separated from Sita and Lakhshman.", hindi = "सीता लखमणु; विछुड़ि गइआ ॥", punjabi = "ਅਤੇ ਸੀਤਾ ਲਛਮਣ ਵਿਛੁੜੇ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-344", gurmukhi = "ਰੋਵੈ ਦਹਸਿਰੁ; ਲੰਕ ਗਵਾਇ ॥", transliteration = "rovai dahsir; lank gvaai ||", translation = "The ten-headed Raawan, who stole away Sita with the beat of his tambourine,", hindi = "रोवै दहसिरु; लंक गवाइ ॥", punjabi = "ਰਾਵਣ ਲੰਕਾ ਗੁਆ ਕੇ ਰੋਇਆ,", wordMeaning = "ਦਹਸਿਰੁ = (संः दशशिर) ਦਸ ਸਿਰਾਂ ਵਾਲਾ, ਰਾਵਣ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-345", gurmukhi = "ਰੋਵੈ ਜਨਮੇਜਾ; ਖੁਇ ਗਇਆ ॥", transliteration = "rovai janmejaa; khui gaiaa ||", translation = "Janmayjaa wept, that he had lost his way.", hindi = "रोवै जनमेजा; खुइ गइआ ॥", punjabi = "ਰਾਜਾ ਜਨਮੇਜਾ ਖੁੰਝ ਗਿਆ, (੧੮ ਬ੍ਰਾਹਮਣਾਂ ਨੂੰ ਜਾਨੋਂ ਮਾਰ ਬੈਠਾ, ਪ੍ਰਾਸ਼ਚਿਤ ਵਾਸਤੇ 'ਮਹਾਭਾਰਤ' ਸੁਣਿਆ, ਪਰ ਸ਼ੰਕਾ ਕੀਤਾ, ਇਸ)", wordMeaning = "ਖੁਇ ਗਇਆ = ਖੁੰਝ ਗਿਆ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-346", gurmukhi = "ਜਿਨ ਕੈ; ਸੁਆਮੀ ਰਹਤ ਹਦੂਰਿ ॥", transliteration = "jin kai; suaamee rahat hdoor ||", translation = "They were made slaves, and wept.", hindi = "जिन कै; सुआमी रहत हदूरि ॥", punjabi = "(ਭਾਵੇਂ ਕਿ) ਜਿਨ੍ਹਾਂ (ਪਾਂਡਵਾਂ) ਦੇ ਪਾਸ ਹੀ ਸ੍ਰੀ ਕ੍ਰਿਸ਼ਨ ਜੀ ਰਹਿੰਦੇ ਸਨ (ਭਾਵ, ਜਿਨ੍ਹਾਂ ਦਾ ਪੱਖ ਕਰਦੇ ਸਨ)", wordMeaning = "ਸੁਆਮੀ = ਕ੍ਰਿਸ਼ਨ ਜੀ।", startsAtMs = 0L, endsAtMs = 0L),
