    BaniLine(id = "ramkali-ki-vaar-386", gurmukhi = "ਅੰਧੇ ਏਹਿ. ਨ ਆਖੀਅਨਿ; ਜਿਨ ਮੁਖਿ ਲੋਇਣ ਨਾਹਿ ॥", transliteration = "andhe eh. na aakheean; jin mukh loin naah ||", translation = "Do not call them blind, who have no eyes in their face.", hindi = "अंधे एहि. न आखीअनि; जिन मुखि लोइण नाहि ॥", punjabi = "(ਪਰ ਆਤਮਕ ਜੀਵਨ ਵਿਚ) ਇਹੋ ਜਿਹੇ ਬੰਦਿਆਂ ਨੂੰ ਅੰਨ੍ਹੇ ਨਹੀਂ ਕਹੀਦਾ ਜਿਨ੍ਹਾਂ ਦੇ ਮੂੰਹ ਉਤੇ ਅੱਖਾਂ ਨਹੀਂ ਹਨ,", wordMeaning = "ਏਹਿ = (ਲਫ਼ਜ਼ 'ਇਹ' ਜਾਂ 'ਏਹ' ਤੋਂ 'ਏਹਿ' ਬਹੁ-ਵਚਨ ਹੈ) ਇਹ ਬੰਦੇ। ਆਖੀਅਨਿ = ਆਖੇ ਜਾਂਦੇ ਹਨ (ਨੋਟ: ਲਫ਼ਜ਼ 'ਆਖੀਅਨੁ' ਅਤੇ 'ਆਖਿਅਨਿ' ਵਿਚ ਫ਼ਰਕ ਵੇਖਣ ਜੋਗ ਹੈ, ਵੇਖੋ 'ਗੁਰਬਾਣੀ ਵਿਆਕਰਣ')। ਮੁਖਿ = ਮੂੰਹ ਉਤੇ। ਲੋਇਣ = ਅੱਖਾਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-387", gurmukhi = "ਜੇਹਾ ਜਾਣੈ ਤੇਹੋ ਵਰਤੈ; ਜੇ ਸਉ ਆਖੈ ਕੋਇ ॥", transliteration = "jehaa jaanai teho vartai; je sau aakhai koi ||", translation = "He acts only as he knows, although he may be spoken to a hundred times.", hindi = "जेहा जाणै तेहो वरतै; जे सउ आखै कोइ ॥", punjabi = "(ਨਹੀਂ ਤਾਂ, ਅੰਨ੍ਹਾ ਮਨੁੱਖ ਤਾਂ) ਜਿਹੋ ਜਿਹੀ ਸਮਝ ਰੱਖਦਾ ਹੈ ਉਸੇ ਤਰ੍ਹਾਂ ਕਰੀ ਜਾਂਦਾ ਹੈ ਭਾਵੇਂ ਉਸ ਨੂੰ ਕੋਈ ਸੌ ਵਾਰੀ ਸਮਝਾਏ।", wordMeaning = "ਜੇਹਾ ਜਾਣੈ = (ਅੰਨ੍ਹਾ ਮਨੁੱਖ) ਜਿਵੇਂ ਸਮਝਦਾ ਹੈ। ਸਉ = ਸੌ ਵਾਰੀ। ਜੇ = ਭਾਵੇਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-388", gurmukhi = "ਮਃ ੨ ॥", transliteration = "mh 2 ||", translation = "Second Mehl:", hindi = "मः २ ॥", punjabi = "ਦੂਜੀ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-389", gurmukhi = "ਸਾਹਿਬਿ. ਅੰਧਾ ਜੋ ਕੀਆ; ਕਰੇ ਸੁਜਾਖਾ ਹੋਇ ॥", transliteration = "saahib. andhaa jo keeaa; kre sujaakhaa hoi ||", translation = "One whom the Lord has made blind - the Lord can make him see again.", hindi = "साहिबि. अंधा जो कीआ; करे सुजाखा होइ ॥", punjabi = "ਜਿਸ ਮਨੁੱਖ ਨੂੰ ਮਾਲਕ-ਪ੍ਰਭੂ ਨੇ ਆਪ ਅੰਨ੍ਹਾ ਕਰ ਦਿੱਤਾ ਹੈ, ਉਹ ਤਾਂ ਹੀ ਸੁਜਾਖਾ ਹੋ ਸਕਦਾ ਹੈ ਜੇ ਪ੍ਰਭੂ ਆਪ (ਸੁਜਾਖਾ) ਬਣਾਏ,", wordMeaning = "ਸਾਹਿਬਿ = ਸਾਹਿਬ ਨੇ, ਪ੍ਰਭੂ ਨੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-390", gurmukhi = "ਜਿਥੈ ਸੁ ਵਸਤੁ. ਨ ਜਾਪਈ; ਆਪੇ ਵਰਤਉ ਜਾਣਿ ॥", transliteration = "jithai su vasat. na jaapaee; aape varatau jaan ||", translation = "Where the real thing is not seen, self-conceit prevails there - know this well.", hindi = "जिथै सु वसतु. न जापई; आपे वरतउ जाणि ॥", punjabi = "ਜਿਸ ਮਨੁੱਖ ਦੇ ਅੰਦਰ 'ਨਾਮ'-ਰੂਪ ਪਦਾਰਥ ਦੀ ਸੋਝੀ ਨਹੀਂ ਓਥੇ ਆਪਾ-ਭਾਵ ਦੀ ਵਰਤੋਂ ਹੋ ਰਹੀ ਸਮਝੋ,", wordMeaning = "ਜਿਥੈ = ਜਿਸ ਮਨੁੱਖ ਦੇ ਅੰਦਰ। ਆਪੇ ਵਰਤਉ = ਆਪਾ-ਭਾਵ ਦੀ ਵਰਤਣ, ਆਪਣੀ ਸਮਝ ਦੀ ਵਰਤੋਂ, ਹਉਮੈ ਦਾ ਜ਼ੋਰ। ਜਾਣਿ = ਜਾਣੋ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-391", gurmukhi = "ਨਾਨਕ. ਗਾਹਕੁ ਕਿਉ ਲਏ; ਸਕੈ ਨ. ਵਸਤੁ ਪਛਾਣਿ ॥੨॥", transliteration = "naanak. gaahak kiu lae; skai na. vasat pchhaan ||2||", translation = "O Nanak, how can the purshaser purchase the real thing, if he cannot recognize it? ||2||", hindi = "नानक. गाहकु किउ लए; सकै न. वसतु पछाणि ॥२॥", punjabi = "(ਕਿਉਂਕਿ) ਹੇ ਨਾਨਕ! ਗਾਹਕ ਜਿਸ ਸਉਦੇ ਨੂੰ ਪਛਾਣ ਹੀ ਨਹੀਂ ਸਕਦਾ ਉਸ ਨੂੰ ਉਹ ਵਿਹਾਵੇ ਕਿਵੇਂ? ॥੨॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-392", gurmukhi = "ਸੋ ਕਿਉ ਅੰਧਾ ਆਖੀਐ; ਜਿ ਹੁਕਮਹੁ ਅੰਧਾ ਹੋਇ ॥", transliteration = "so kiu andhaa aakheeai; ji hukamah andhaa hoi ||", translation = "How can someone be called blind, if he was made blind by the Lord's Command?", hindi = "सो किउ अंधा आखीऐ; जि हुकमहु अंधा होइ ॥", punjabi = "ਜੋ ਮਨੁੱਖ ਪ੍ਰਭੂ ਦੀ ਰਜ਼ਾ ਵਿਚ ਨੇਤ੍ਰ-ਹੀਣ ਹੋ ਗਿਆ ਉਸ ਨੂੰ ਅਸੀਂ ਅੰਨ੍ਹਾ ਨਹੀਂ ਆਖਦੇ।", wordMeaning = "ਹੁਕਮਹੁ = ਹੁਕਮ ਨਾਲ, ਰਜ਼ਾ ਵਿਚ। ਅੰਧਾ = ਨੇਤ੍ਰ-ਹੀਣ। (ਨੋਟ: ਅੰਕ ੨ ਦਾ ਭਾਵ ਹੈ ਮ: ੨)।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-393", gurmukhi = "ਨਾਨਕ ਹੁਕਮੁ. ਨ ਬੁਝਈ; ਅੰਧਾ ਕਹੀਐ ਸੋਇ ॥੩॥", transliteration = "naanak hukam. na bujhaee; andhaa kheeai soi ||3||", translation = "O Nanak, one who does not understand the Hukam of the Lord's Command should be called blind. ||3||", hindi = "नानक हुकमु. न बुझई; अंधा कहीऐ सोइ ॥३॥", punjabi = "ਹੇ ਨਾਨਕ! ਉਹ ਮਨੁੱਖ ਅੰਨ੍ਹਾ ਕਿਹਾ ਜਾਂਦਾ ਹੈ ਜੋ ਰਜ਼ਾ ਨੂੰ ਸਮਝਦਾ ਨਹੀਂ ॥੩॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-394", gurmukhi = "ਮਃ ੨ ॥", transliteration = "mh 2 ||", translation = "Second Mehl:", hindi = "मः २ ॥", punjabi = "ਦੂਜੀ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-395", gurmukhi = "ਆਪੇ ਤਾੜੀ ਲਾਈਅਨੁ; ਸਭ ਮਹਿ ਪਰਵੇਸਾ ॥", transliteration = "aape taaree laaeean; sabh mah parvesaa ||", translation = "He Himself sits in primal, profound Samaadhi; He Himself is all-pervading.", hindi = "आपे ताड़ी लाईअनु; सभ महि परवेसा ॥", punjabi = "ਸਾਰੇ ਜੀਵਾਂ ਦੇ ਅੰਦਰ ਪਰਵੇਸ਼ ਕਰ ਕੇ ਉਸ ਨੇ ਆਪ ਹੀ (ਜੀਵਾਂ ਦੇ ਅੰਦਰ) ਤਾੜੀ ਲਾਈ ਹੋਈ ਹੈ (ਉਹ ਆਪ ਹੀ ਜੀਵਾਂ ਦੇ ਅੰਦਰ ਟਿਕਿਆ ਹੋਇਆ ਹੈ)।", wordMeaning = "ਲਾਈਅਨੁ = ਲਾਈ ਹੋਈ ਹੈ ਉਸ ਨੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-396", gurmukhi = "ਪਉੜੀ ॥", transliteration = "pauree ||", translation = "Pauree:", hindi = "पउड़ी ॥", punjabi = "ਪਉੜੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-397", gurmukhi = "ਕਾਇਆ ਅੰਦਰਿ. ਗੜੁ ਕੋਟੁ ਹੈ; ਸਭਿ ਦਿਸੰਤਰ ਦੇਸਾ ॥", transliteration = "kaaiaa andar. gar kot hai; sabh disantar desaa ||", translation = "Deep within the body is the fortress of the Lord, and all lands and countries.", hindi = "काइआ अंदरि. गड़ु कोटु है; सभि दिसंतर देसा ॥", punjabi = "(ਮਨੁੱਖਾ-) ਸਰੀਰ ਦੇ ਅੰਦਰ (ਮਨੁੱਖ ਦਾ ਹਿਰਦਾ-ਰੂਪ) ਜਿਸ ਪ੍ਰਭੂ ਦਾ ਕਿਲ੍ਹਾ ਹੈ ਗੜ੍ਹ ਹੈ ਉਹ ਪ੍ਰਭੂ ਸਾਰੇ ਦੇਸ ਦੇਸਾਂਤਰਾਂ ਵਿਚ ਮੌਜੂਦ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-398", gurmukhi = "ਆਪੇ ਸ੍ਰਿਸਟਿ ਸਾਜੀਅਨੁ; ਆਪਿ ਗੁਪਤੁ ਰਖੇਸਾ ॥", transliteration = "aape srisat saajeean; aap gupat rkhesaa ||", translation = "He Himself created the Universe, and He Himself remains hidden within it.", hindi = "आपे स्रिसटि साजीअनु; आपि गुपतु रखेसा ॥", punjabi = "ਪ੍ਰਭੂ ਨੇ ਆਪ ਹੀ ਸ੍ਰਿਸ਼ਟੀ ਸਾਜੀ ਹੈ ਤੇ ਆਪ ਹੀ (ਉਸ ਸ੍ਰਿਸ਼ਟੀ ਵਿਚ ਉਸ ਨੇ ਆਪਣੇ ਆਪ ਨੂੰ) ਲੁਕਾਇਆ ਹੋਇਆ ਹੈ।", wordMeaning = "ਸਾਜੀਅਨੁ = ਸਾਜੀ ਹੈ ਉਸ ਨੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-399", gurmukhi = "ਗੁਰ ਸੇਵਾ ਤੇ ਜਾਣਿਆ; ਸਚੁ ਪਰਗਟੀਏਸਾ ॥", transliteration = "gur sevaa te jaaniaa; sach paragteeesaa ||", translation = "Serving the Guru, the Lord is known, and the Truth is revealed.", hindi = "गुर सेवा ते जाणिआ; सचु परगटीएसा ॥", punjabi = "ਉਸ ਪ੍ਰਭੂ ਦੀ ਸੂਝ ਸਤਿਗੁਰੂ ਦੇ ਹੁਕਮ ਵਿਚ ਤੁਰਿਆਂ ਆਉਂਦੀ ਹੈ (ਤਾਂ ਹੀ) ਸੱਚਾ ਪ੍ਰਭੂ ਪਰਗਟ ਹੁੰਦਾ ਹੈ।", wordMeaning = "ਗੁਰ ਸੇਵਾ = ਗੁਰੂ ਦੀ ਦੱਸੀ ਸੇਵਾ ਨਾਲ, ਗੁਰੂ ਦੇ ਹੁਕਮ ਵਿਚ ਤੁਰ ਕੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-400", gurmukhi = "ਸਲੋਕ ਮਃ ੧ ॥", transliteration = "salok mh 1 ||", translation = "Salok, First Mehl:", hindi = "सलोक मः १ ॥", punjabi = "ਸਲੋਕ ਪਹਿਲੀ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-401", gurmukhi = "ਸਭੁ ਕਿਛੁ ਸਚੋ ਸਚੁ ਹੈ; ਗੁਰਿ. ਸੋਝੀ ਪਾਈ ॥੧੬॥", transliteration = "sabh kichh scho sach hai; gur. sojhee paaee ||16||", translation = "He is True, the Truest of the True; the Guru has imparted this understanding. ||16||", hindi = "सभु किछु सचो सचु है; गुरि. सोझी पाई ॥१६॥", punjabi = "ਹੈ ਤਾਂ ਹਰ ਥਾਂ ਸੱਚਾ ਪ੍ਰਭੂ ਆਪ ਹੀ ਆਪ, ਪਰ ਇਹ ਸਮਝ ਸਤਿਗੁਰੂ ਦੀ ਰਾਹੀਂ ਹੀ ਪੈਂਦੀ ਹੈ ॥੧੬॥", wordMeaning = "ਗੁਰਿ = ਗੁਰੂ ਦੀ ਰਾਹੀਂ ॥੧੬॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-402", gurmukhi = "ਸਾਵਣੁ ਰਾਤਿ ਅਹਾੜੁ ਦਿਹੁ; ਕਾਮੁ ਕ੍ਰੋਧੁ ਦੁਇ ਖੇਤ ॥", transliteration = "saavan raat ahaar dih; kaam krodh dui khet ||", translation = "Night is the summer season, and day is the winter season; sexual desire and anger are the two fields planted.", hindi = "सावणु राति अहाड़ु दिहु; कामु क्रोधु दुइ खेत ॥", punjabi = "(ਜਿਸ ਜੀਵ ਦੀ) ਰਾਤ ਸਾਉਣੀ ਦੀ ਫ਼ਸਲ ਹੈ ਤੇ 'ਕਾਮ' ਜਿਸ ਦੀ ਪੈਲੀ ਹੈ (ਭਾਵ, ਜੋ ਜੀਵ ਆਪਣੀ ਰਾਤ 'ਕਾਮ' ਦੇ ਅਧੀਨ ਹੋ ਕੇ ਗੁਜ਼ਾਰਦਾ ਹੈ), ਜਿਸ ਦਾ ਦਿਨ ਹਾੜੀ ਦੀ ਫ਼ਸਲ ਹੈ ਤੇ 'ਕ੍ਰੋਧ' ਜਿਸ ਦੀ ਪੈਲੀ ਹੈ (ਭਾਵ, ਜੋ ਦਿਨ ਦਾ ਸਮਾ ਕ੍ਰੋਧ ਦੇ ਅਧੀਨ ਬਿਤਾਂਦਾ ਹੈ),", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-403", gurmukhi = "ਹਲੁ ਬੀਚਾਰੁ, ਵਿਕਾਰ ਮਣ; ਹੁਕਮੀ ਖਟੇ ਖਾਇ ॥", transliteration = "hal beechaar, vikaar man; hukmee khte khaai ||", translation = "Contemplation is the plow, and corruption is the harvest; this is what one earns and eats, according to the Hukam of the Lord's Command.", hindi = "हलु बीचारु, विकार मण; हुकमी खटे खाइ ॥", punjabi = "'ਮੋਹ' ਜਿਸ ਜੀਵ ਲਈ ਹਲ ਵਾਹੁਣ ਵਾਲਾ ਹੈ ਤੇ ਬੀਜ ਬੀਜਣ ਵਾਲਾ ਹੈ; ਵਿਕਾਰਾਂ ਦੀ ਵਿਚਾਰ ਜਿਸ ਜੀਵ ਦਾ 'ਹਲ' ਹੈ; ਵਿਕਾਰਾਂ ਦਾ ਬੋਹਲ ਜਿਸ ਨੇ ਇਕੱਠਾ ਕੀਤਾ ਹੈ, ਉਹ ਮਨੁੱਖ ਪ੍ਰਭੂ ਦੇ ਹੁਕਮ ਵਿਚ ਆਪਣੀ ਕੀਤੀ ਇਸ ਕਮਾਈ ਦਾ ਖਟਿਆ ਖਾਂਦਾ ਹੈ।", wordMeaning = "ਮਣ = ਬੋਹਲ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-404", gurmukhi = "ਲਬੁ ਵਤ੍ਰ, ਦਰੋਗੁ ਬੀਉ; ਹਾਲੀ ਰਾਹਕੁ ਹੇਤ ॥", transliteration = "lab vatr, drog beeu; haalee raahak het ||", translation = "Greed prepares the soil, and the seed of falsehood is planted; attachment and love are the farmer and hired hand.", hindi = "लबु वत्र, दरोगु बीउ; हाली राहकु हेत ॥", punjabi = "ਜਿਸ ਜੀਵ ਲਈ 'ਲੱਬ' ਵੱਤਰ ਦਾ ਕੰਮ ਦੇਂਦਾ) ਹੈ ਤੇ ਝੂਠ (ਜਿਸ ਦੇ ਫ਼ਸਲ ਲਈ) ਬੀਜ ਹੈ (ਭਾਵ, ਜੋ ਲੱਬ ਦਾ ਪ੍ਰੇਰਿਆ ਹੋਇਆ ਝੂਠ ਬੋਲਦਾ ਹੈ)।", wordMeaning = "ਦਰੋਗੁ = ਝੂਠ। ਬੀਉ = ਬੀਜ। ਹਾਲੀ ਰਾਹਕੁ = ਹਲ ਵਾਹੁਣ ਵਾਲਾ, ਬੀਜਣ ਵਾਲਾ। ਹੇਤ = ਮੋਹ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-405", gurmukhi = "ਨਾਨਕ. ਲੇਖੈ ਮੰਗਿਐ; ਅਉਤੁ ਜਣੇਦਾ ਜਾਇ ॥੧॥", transliteration = "naanak. lekhai mangiai; aut jnedaa jaai ||1||", translation = "O Nanak, when one is called to give his account, he will be barren and infertile. ||1||", hindi = "नानक. लेखै मंगिऐ; अउतु जणेदा जाइ ॥१॥", punjabi = "ਹੇ ਨਾਨਕ! ਜਦੋਂ ਜੀਵ ਦੀ ਕਰਤੂਤ ਦਾ ਲੇਖਾ ਮੰਗਿਆ ਜਾਂਦਾ ਹੈ ਤਦੋਂ ਪਤਾ ਲੱਗਦਾ ਹੈ ਕਿ ਅਜੇਹਾ ਜੀਵ-ਰੂਪ) ਪਿਉ (ਜਗਤ ਤੋਂ) ਅਉਤ੍ਰਾ ਹੀ ਜਾਂਦਾ ਹੈ (ਭਾਵ, ਜੀਵਨ ਅਜਾਂਈ ਗੁਆ ਜਾਂਦਾ ਹੈ) ॥੧॥", wordMeaning = "ਅਉਤੁ = (ਅ-ਉਤੁ + ਅ-ਪੁਤੁ) ਅਪੁੱਤ੍ਰਾ, ਅਉਤ੍ਰਾ, ਸੰਤਾਨ = ਹੀਣ। ਜਣੇਦਾ = ਜਣਨ ਵਾਲਾ, ਪਿਉ ॥੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-406", gurmukhi = "ਭਉ ਭੁਇ. ਪਵਿਤੁ ਪਾਣੀ; ਸਤੁ ਸੰਤੋਖੁ ਬਲੇਦ ॥", transliteration = "bhau bhui. pvit paanee; sat santokh bled ||", translation = "Make the Fear of God the farm, purity the water, truth and contentment the cows and bulls,", hindi = "भउ भुइ. पवितु पाणी; सतु संतोखु बलेद ॥", punjabi = "ਜੇ ਪ੍ਰਭੂ ਦਾ ਡਰ ਪੈਲੀ ਬਣੇ, ਸੁੱਧ ਆਚਰਨ (ਉਸ ਪੈਲੀ ਲਈ) ਪਾਣੀ ਹੋਵੇ, ਸਤ ਤੇ ਸੰਤੋਖ (ਉਸ ਪੈਲੀ ਨੂੰ ਵਾਹੁਣ ਲਈ) ਬਲਦ ਹੋਣ;", wordMeaning = "ਭੁਇ = ਪੈਲੀ। ਪਵਿਤੁ = ਸੁੱਧ ਆਚਰਨ। ਬਲੇਦ = ਬਲਦ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-407", gurmukhi = "ਮਃ ੧ ॥", transliteration = "mh 1 ||", translation = "First Mehl:", hindi = "मः १ ॥", punjabi = "ਪਹਿਲੀ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-408", gurmukhi = "ਨਾਉ ਬੀਜੁ. ਬਖਸੀਸ ਬੋਹਲ; ਦੁਨੀਆ ਸਗਲ ਦਰੋਗ ॥", transliteration = "naau beej. bakhsees bohal; duneeaa sagal drog ||", translation = "Let the Lord's Name be the seed, and His Forgiving Grace the harvest. Do this, and the whole world will seem false.", hindi = "नाउ बीजु. बखसीस बोहल; दुनीआ सगल दरोग ॥", punjabi = "ਪ੍ਰਭੂ ਦਾ 'ਨਾਮ' ਬੀਜ ਹੋਵੇ ਤਾਂ ਪ੍ਰਭੂ ਦੀ ਬਖ਼ਸ਼ਸ਼ ਦਾ ਬੋਹਲ ਇਕੱਠਾ ਹੁੰਦਾ ਹੈ ਤੇ ਦੁਨੀਆ ਸਾਰੀ ਝੂਠੀ ਦਿੱਸ ਪੈਂਦੀ ਹੈ (ਭਾਵ, ਇਹ ਸਮਝ ਆ ਜਾਂਦੀ ਹੈ ਕਿ ਦੁਨੀਆ ਦਾ ਸਾਥ ਸਦਾ ਨਿਭਣ ਵਾਲਾ ਨਹੀਂ)।", wordMeaning = "ਦਰੋਗ = ਨਾਸਵੰਤ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-409", gurmukhi = "ਹਲੁ ਹਲੇਮੀ, ਹਾਲੀ ਚਿਤੁ; ਚੇਤਾ ਵਤ੍ਰ. ਵਖਤ ਸੰਜੋਗੁ ॥", transliteration = "hal hlemee, haalee chit; chetaa vatr. vakhat sanjog ||", translation = "humility the plow, consciousness the plowman, remembrance the preparation of the soil, and union with the Lord the planting time.", hindi = "हलु हलेमी, हाली चितु; चेता वत्र. वखत संजोगु ॥", punjabi = "ਨਿਮ੍ਰਤਾ ਦਾ ਹਲ ਹੋਵੇ, (ਜੁੜਿਆ ਹੋਇਆ) ਚਿੱਤ ਹਲ ਵਾਹੁਣ ਵਾਲਾ ਹੋਵੇ, ਪ੍ਰਭੂ ਦੇ ਸਿਮਰਨ ਦਾ ਵੱਤਰ ਹੋਵੇ ਤੇ ਗੁਰੂ ਦਾ ਮਿਲਾਪ (ਬੀਜ ਬੀਜਣ ਦਾ) ਸਮਾ ਹੋਵੇ,", wordMeaning = "ਸੰਜੋਗੁ = ਗੁਰੂ ਨਾਲ ਮੇਲ। ਹਲੇਮੀ = ਨਿਮ੍ਰਤਾ। ਚੇਤਾ = ਸਿਮਰਨ। ਵਖਤ = ਬੀਜਣ ਦਾ ਸਮਾ", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-410", gurmukhi = "ਪਉੜੀ ॥", transliteration = "pauree ||", translation = "Pauree:", hindi = "पउड़ी ॥", punjabi = "ਪਉੜੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-411", gurmukhi = "ਨਾਨਕ. ਨਦਰੀ ਕਰਮੁ ਹੋਇ; ਜਾਵਹਿ ਸਗਲ ਵਿਜੋਗ ॥੨॥", transliteration = "naanak. nadree karam hoi; jaavah sagal vijog ||2||", translation = "O Nanak, if He bestows His Merciful Glance of Grace, then all your separation will be ended. ||2||", hindi = "नानक. नदरी करमु होइ; जावहि सगल विजोग ॥२॥", punjabi = "ਹੇ ਨਾਨਕ! (ਇਸ ਉੱਦਮ ਨਾਲ ਜਦੋਂ) ਪ੍ਰਭੂ ਦੀ ਮੇਹਰ ਹੁੰਦੀ ਹੈ ਤਾਂ (ਉਸ ਨਾਲ) ਸਾਰੇ ਵਿਛੋੜੇ ਦੂਰ ਹੋ ਜਾਂਦੇ ਹਨ ॥੨॥", wordMeaning = "ਕਰਮੁ = ਬਖ਼ਸ਼ਸ਼ ॥੨॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-412", gurmukhi = "ਮਨਮੁਖਿ ਮੋਹੁ ਗੁਬਾਰੁ ਹੈ; ਦੂਜੈ ਭਾਇ ਬੋਲੈ ॥", transliteration = "manmukh moh gubaar hai; doojai bhaai bolai ||", translation = "The self-willed manmukh is trapped in the darkness of emotional attachment; in the love of duality he speaks.", hindi = "मनमुखि मोहु गुबारु है; दूजै भाइ बोलै ॥", punjabi = "ਜੋ ਮਨੁੱਖ ਆਪਣੇ ਮਨ ਦੇ ਪਿੱਛੇ ਤੁਰਦਾ ਹੈ ਉਸ ਦੇ ਅੰਦਰ ਮੋਹ-ਰੂਪ ਘੁੱਪ ਹਨੇਰਾ ਹੈ, (ਉਹ ਜੋ ਬਚਨ ਬੋਲਦਾ ਹੈ) ਮਾਇਆ ਦੇ ਮੋਹ ਵਿਚ ਹੀ ਬੋਲਦਾ ਹੈ।", wordMeaning = "ਗੁਬਾਰੁ = ਡੂੰਘਾ ਹਨੇਰਾ। ਭਾਇ = ਭਾਉ ਵਿਚ, ਪਿਆਰ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-413", gurmukhi = "ਅੰਤਰਿ ਪਰਗਾਸੁ ਘਟਿ ਚਾਨਣਾ; ਹਰਿ ਲਧਾ ਟੋਲੈ ॥", transliteration = "antar pargaas ghat chaannaa; har ldhaa tolai ||", translation = "The Divine Light illuminates his heart deep within; he seeks the Lord, and obtains Him.", hindi = "अंतरि परगासु घटि चानणा; हरि लधा टोलै ॥", punjabi = "ਉਸ ਦੇ ਹਿਰਦੇ ਵਿਚ (ਪ੍ਰਭੂ ਦਾ) ਪ੍ਰਕਾਸ਼ ਹੋ ਜਾਂਦਾ ਹੈ ਦਿਲ ਵਿਚ (ਗਿਆਨ ਦਾ) ਚਾਨਣ ਹੋ ਜਾਂਦਾ ਹੈ, ਉਸ ਨੇ (ਗੁਰੂ ਦੀ ਰਾਹੀਂ) ਭਾਲ ਕਰ ਕੇ ਪ੍ਰਭੂ ਨੂੰ ਲੱਭ ਲਿਆ ਹੈ।", wordMeaning = "ਟੋਲੈ = ਟੋਲਿ, ਟੋਲ ਕੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-414", gurmukhi = "ਦੂਜੈ ਭਾਇ ਸਦਾ ਦੁਖੁ ਹੈ; ਨਿਤ ਨੀਰੁ ਵਿਰੋਲੈ ॥", transliteration = "doojai bhaai sdaa dukh hai; nit neer virolai ||", translation = "The love of duality brings pain forever; he churns the water endlessly.", hindi = "दूजै भाइ सदा दुखु है; नित नीरु विरोलै ॥", punjabi = "ਉਹ (ਮਾਨੋ) ਸਦਾ ਪਾਣੀ ਰਿੜਕਦਾ ਹੈ ਤੇ ਮਾਇਆ ਦੇ ਮੋਹ ਦੇ ਕਾਰਣ ਉਸ ਨੂੰ ਸਦਾ ਦੁੱਖ (ਹੁੰਦਾ) ਹੈ।", wordMeaning = "ਦੂਜੈ ਭਾਇ = ਪ੍ਰਭੂ ਤੋਂ ਬਿਨਾ ਕਿਸੇ ਹੋਰ ਦੇ ਮੋਹ ਵਿਚ। ਨੀਰੁ = ਪਾਣੀ। ਵਿਰੋਲੈ = ਰਿੜਕਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-415", gurmukhi = "ਗੁਰਮੁਖਿ ਨਾਮੁ ਧਿਆਈਐ; ਮਥਿ ਤਤੁ ਕਢੋਲੈ ॥", transliteration = "gurmukh naam dhiaaeeai; math tat kdholai ||", translation = "The Gurmukh meditates on the Naam, the Name of the Lord; he churns, and obtains the essence of reality.", hindi = "गुरमुखि नामु धिआईऐ; मथि ततु कढोलै ॥", punjabi = "ਜੋ ਮਨੁੱਖ ਗੁਰੂ ਦੇ ਹੁਕਮ ਵਿਚ ਤੁਰਦਾ ਹੈ ਉਹ ਪ੍ਰਭੂ ਦਾ ਨਾਮ ਸਿਮਰਦਾ ਹੈ ਉਹ (ਮਾਨੋ, ਦੁੱਧ) ਰਿੜਕ ਕੇ ਪ੍ਰਭੂ ਦਾ ਨਾਮ-ਰੂਪ ਮੱਖਣ ਕੱਢਦਾ ਹੈ।", wordMeaning = "ਮਥਿ = ਰਿੜਕ ਕੇ। ਤਤੁ = ਅਸਲੀਅਤ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-416", gurmukhi = "ਸਲੋਕ ਮਃ ੨ ॥", transliteration = "salok mh 2 ||", translation = "Salok, Second Mehl:", hindi = "सलोक मः २ ॥", punjabi = "ਸਲੋਕ ਦੂਜੀ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L)
)

