    BaniLine(id = "ramkali-ki-vaar-417", gurmukhi = "ਆਪੇ ਭਰਮਿ ਭੁਲਾਇਦਾ; ਕਿਛੁ ਕਹਣੁ. ਨ ਜਾਈ ॥੧੭॥", transliteration = "aape bharam bhulaaidaa; kichh kahan. na jaaee ||17||", translation = "He Himself deludes in doubt; no one can comment on this. ||17||", hindi = "आपे भरमि भुलाइदा; किछु कहणु. न जाई ॥१७॥", punjabi = "(ਜਿਸ ਕਿਸੇ ਨੂੰ ਭੁਲਾਂਦਾ ਹੈ) ਪ੍ਰਭੂ ਆਪ ਹੀ ਭਰਮ ਭੁਲਾਂਦਾ ਹੈ (ਕਿਸੇ ਦੇ ਸਿਰ ਕੀਹ ਦੋਸ਼?) ਕੋਈ ਗੱਲ ਕਹੀ ਨਹੀਂ ਜਾ ਸਕਦੀ ॥੧੭॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
