    BaniLine(id = "ramkali-ki-vaar-419", gurmukhi = "ਓਥੈ ਹਟੁ. ਨ ਚਲਈ; ਨਾ ਕੋ ਕਿਰਸ ਕਰੇਇ ॥", transliteration = "othai hat. na chalaee; naa ko kiras krei ||", translation = "There are no stores open there, and no one farms there.", hindi = "ओथै हटु. न चलई; ना को किरस करेइ ॥", punjabi = "ਪਾਣੀ ਵਿਚ ਨਾਹ ਕੋਈ ਦੁਕਾਨ ਚੱਲਦੀ ਹੈ ਨਾਹ ਓਥੇ ਕੋਈ ਵਾਹੀ ਕਰਦਾ ਹੈ।", wordMeaning = "ਓਥੈ = ਪਾਣੀ ਵਿਚ। ਕਿਰਸ = ਖੇਤੀ, ਵਾਹੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-420", gurmukhi = "ਨਾਨਕ. ਚਿੰਤਾ ਮਤਿ ਕਰਹੁ; ਚਿੰਤਾ ਤਿਸ ਹੀ ਹੇਇ ॥", transliteration = "naanak. chintaa mat karah; chintaa tis hee hei ||", translation = "O Nanak, don't be anxious; the Lord will take care of you.", hindi = "नानक. चिंता मति करहु; चिंता तिस ही हेइ ॥", punjabi = "ਹੇ ਨਾਨਕ! (ਆਪਣੀ ਰੋਜ਼ੀ ਲਈ) ਫ਼ਿਕਰ ਚਿੰਤਾ ਨਾਹ ਕਰੋ, ਇਹ ਫ਼ਿਕਰ ਉਸ ਪ੍ਰਭੂ ਨੂੰ ਆਪ ਹੀ ਹੈ।", wordMeaning = "ਚਿੰਤਾ = ਫ਼ਿਕਰ। ਤਿਸ ਹੀ = ਉਸ ਪ੍ਰਭੂ ਨੂੰ ਹੀ। ਕੋਇ = ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-421", gurmukhi = "ਸਉਦਾ ਮੂਲਿ. ਨ ਹੋਵਈ; ਨਾ ਕੋ ਲਏ. ਨ ਦੇਇ ॥", transliteration = "saudaa mool. na hovaee; naa ko lae. na dei ||", translation = "No business is ever transacted there, and no one buys or sells.", hindi = "सउदा मूलि. न होवई; ना को लए. न देइ ॥", punjabi = "ਨਾਹ ਓਥੇ ਕੋਈ ਸਉਦਾ-ਸੂਤ ਹੋ ਰਿਹਾ ਹੈ ਨਾਹ ਕੋਈ ਲੈਣ-ਦੇਣ ਦਾ ਵਪਾਰ ਹੈ;", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-422", gurmukhi = "ਜੀਆ ਕਾ ਆਹਾਰੁ ਜੀਅ; ਖਾਣਾ ਏਹੁ ਕਰੇਇ ॥", transliteration = "jeeaa kaa aahaar jeea; khaanaa eh krei ||", translation = "Animals eat other animals; this is what the Lord has given them as food.", hindi = "जीआ का आहारु जीअ; खाणा एहु करेइ ॥", punjabi = "ਪਰ ਓਥੇ ਇਹ ਖ਼ੁਰਾਕ ਬਣਾ ਦਿੱਤੀ ਹੈ ਕਿ ਜੀਵਾਂ ਦਾ ਖਾਣਾ ਜੀਵ ਹੀ ਹਨ।", wordMeaning = "ਆਹਾਰੁ = ਖ਼ੁਰਾਕ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-423", gurmukhi = "ਨਾਨਕ. ਚਿੰਤਾ ਮਤ ਕਰਹੁ; ਚਿੰਤਾ ਤਿਸ ਹੀ ਹੇਇ ॥੧॥", transliteration = "naanak. chintaa mat karah; chintaa tis hee hei ||1||", translation = "O Nanak, don't be anxious; the Lord will take care of you. ||1||", hindi = "नानक. चिंता मत करहु; चिंता तिस ही हेइ ॥१॥", punjabi = "ਹੇ ਨਾਨਕ! (ਰੋਜ਼ੀ ਲਈ) ਚਿੰਤਾ ਨਾਹ ਕਰੋ, ਉਸ ਪ੍ਰਭੂ ਨੂੰ ਆਪ ਹੀ ਫ਼ਿਕਰ ਹੈ ॥੧॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-424", gurmukhi = "ਵਿਚਿ ਉਪਾਏ ਸਾਇਰਾ; ਤਿਨਾ ਭਿ ਸਾਰ ਕਰੇਇ ॥", transliteration = "vich upaae saairaa; tinaa bhi saar krei ||", translation = "He created them in the oceans, and He provides for them as well.", hindi = "विचि उपाए साइरा; तिना भि सार करेइ ॥", punjabi = "ਸੋ, ਜਿਨ੍ਹਾਂ ਨੂੰ ਸਮੁੰਦਰਾਂ ਵਿਚ ਉਸ ਨੇ ਪੈਦਾ ਕੀਤਾ ਹੈ ਉਹਨਾਂ ਦੀ ਭੀ ਸੰਭਾਲ ਕਰਦਾ ਹੈ।", wordMeaning = "ਸਾਇਰਾ = ਸਮੁੰਦਰਾਂ। ਸਾਰ = ਸੰਭਾਲ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-425", gurmukhi = "ਮਃ ੧ ॥", transliteration = "mh 1 ||", translation = "First Mehl:", hindi = "मः १ ॥", punjabi = "ਪਹਿਲੀ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-426", gurmukhi = "ਨਾਨਕ. ਇਹੁ ਜੀਉ ਮਛੁਲੀ; ਝੀਵਰੁ ਤ੍ਰਿਸਨਾ ਕਾਲੁ ॥", transliteration = "naanak. ih jeeu mchhulee; jheevar trisnaa kaal ||", translation = "O Nanak, this soul is the fish, and death is the hungry fisherman.", hindi = "नानक. इहु जीउ मछुली; झीवरु त्रिसना कालु ॥", punjabi = "ਹੇ ਨਾਨਕ! ਇਹ ਜਿੰਦ ਨਿੱਕੀ ਜਿਹੀ ਮੱਛੀ ਹੈ, ਆਤਮਕ ਮੌਤ ਲਿਆਉਣ ਵਾਲੀ ਤ੍ਰਿਸ਼ਨਾ ਮਾਛੀ ਹੈ;", wordMeaning = "ਮਛੁਲੀ = ਨਿੱਕੀ ਜਿਹੀ ਮੱਛੀ। ਝੀਵਰੁ = ਮਾਛੀ। ਕਾਲੁ = ਮੌਤ, ਆਤਮਕ ਮੌਤ ਲਿਆਉਣ ਵਾਲਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-427", gurmukhi = "ਮਨੂਆ ਅੰਧੁ. ਨ ਚੇਤਈ; ਪੜੈ ਅਚਿੰਤਾ ਜਾਲੁ ॥", transliteration = "manooaa andh. na chetaee; prai achintaa jaal ||", translation = "The blind man does not even think of this. And suddenly, the net is cast.", hindi = "मनूआ अंधु. न चेतई; पड़ै अचिंता जालु ॥", punjabi = "ਮੂਰਖ ਮਨ (ਇਸ ਤ੍ਰਿਸ਼ਨਾ ਵਿਚ) ਅੰਨ੍ਹਾ (ਹੋਇਆ ਹੋਇਆ ਪਰਮਾਤਮਾ ਨੂੰ) ਯਾਦ ਨਹੀਂ ਕਰਦਾ, ਬੇਖ਼ਬਰੀ ਵਿਚ ਹੀ (ਆਤਮਕ ਮੌਤ ਦਾ) ਜਾਲ (ਇਸ ਉਤੇ) ਪੈਂਦਾ ਜਾਂਦਾ ਹੈ।", wordMeaning = "ਮਨੂਆ = ਮੂਰਖ ਮਨ। ਅਚਿੰਤਾ = ਅਚਨਚੇਤ, ਬੇ-ਖ਼ਬਰੀ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-428", gurmukhi = "ਨਦਰਿ ਕਰੇ ਜੇ ਆਪਣੀ; ਤਾ ਆਪੇ ਲਏ ਮਿਲਾਇ ॥੨॥", transliteration = "nadar kre je aapnee; taa aape lae milaai ||2||", translation = "But if the Lord bestows His Glance of Grace, then He unites the soul with Himself. ||2||", hindi = "नदरि करे जे आपणी; ता आपे लए मिलाइ ॥२॥", punjabi = "ਜੇ ਪ੍ਰਭੂ ਆਪ ਆਪਣੀ ਮੇਹਰ ਦੀ ਨਜ਼ਰ ਕਰੇ ਤਾਂ (ਜਿੰਦ ਨੂੰ ਤ੍ਰਿਸ਼ਨਾ ਵਿਚੋਂ ਕੱਢ ਕੇ) ਆਪਣੇ ਵਿਚ ਮਿਲਾ ਲੈਂਦਾ ਹੈ ॥੨॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-429", gurmukhi = "ਨਾਨਕ. ਚਿਤੁ ਅਚੇਤੁ ਹੈ; ਚਿੰਤਾ ਬਧਾ ਜਾਇ ॥", transliteration = "naanak. chit achet hai; chintaa bdhaa jaai ||", translation = "O Nanak, his consciousness is unconscious, and he departs, bound by anxiety.", hindi = "नानक. चितु अचेतु है; चिंता बधा जाइ ॥", punjabi = "ਹੇ ਨਾਨਕ! (ਤ੍ਰਿਸ਼ਨਾ ਵਿਚ ਫਸਿਆ) ਮਨ ਗ਼ਾਫ਼ਿਲ ਹੋ ਰਿਹਾ ਹੈ, ਸਦਾ ਚਿੰਤਾ ਵਿਚ ਜਕੜਿਆ ਰਹਿੰਦਾ ਹੈ।", wordMeaning = "ਅਚੇਤੁ = ਗਾਫ਼ਲ, ਬੇਪਰਵਾਹ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-430", gurmukhi = "ਗੁਰਮੁਖਿ ਸਚਾ ਮਨਿ ਵਸੈ; ਸਚੁ ਸਉਦਾ ਕੀਤਾ ॥", transliteration = "gurmukh schaa man vsai; sach saudaa keetaa ||", translation = "The True Lord abides in the mind of the Gurmukh; He strikes the true bargain.", hindi = "गुरमुखि सचा मनि वसै; सचु सउदा कीता ॥", punjabi = "ਗੁਰੂ ਦੇ ਹੁਕਮ ਵਿਚ ਤੁਰ ਕੇ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ ਪ੍ਰਭੂ ਉਹਨਾਂ ਦੇ ਮਨ ਵਿਚ ਵੱਸਦਾ ਹੈ, ਉਹਨਾਂ ਪ੍ਰਭੂ ਦਾ ਨਾਮ-ਰੂਪ ਵਣਜ ਕੀਤਾ ਹੈ।", wordMeaning = "ਮਨਿ = ਮਨ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-431", gurmukhi = "ਸੇ ਜਨ ਸਾਚੇ ਸਦਾ ਸਦਾ; ਜਿਨੀ ਹਰਿ ਰਸੁ ਪੀਤਾ ॥", transliteration = "se jan saache sdaa sdaa; jinee har ras peetaa ||", translation = "They are true, forever true, who drink in the sublime essence of the Lord.", hindi = "से जन साचे सदा सदा; जिनी हरि रसु पीता ॥", punjabi = "ਜਿਨ੍ਹਾਂ ਮਨੁੱਖਾਂ ਨੇ ਪ੍ਰਭੂ ਦਾ ਨਾਮ-ਅੰਮ੍ਰਿਤ ਪੀਤਾ ਹੈ ਉਹ ਮਨੁੱਖ ਨਿੱਤ ਪ੍ਰਭੂ ਨਾਲ ਇਕ-ਰੂਪ ਰਹਿੰਦੇ ਹਨ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-432", gurmukhi = "ਪਉੜੀ ॥", transliteration = "pauree ||", translation = "Pauree:", hindi = "पउड़ी ॥", punjabi = "ਪਉੜੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-433", gurmukhi = "ਸਭੁ ਕਿਛੁ ਘਰ ਹੀ ਮਾਹਿ ਹੈ; ਵਡਭਾਗੀ ਲੀਤਾ ॥", transliteration = "sabh kichh ghar hee maah hai; vadbhaagee leetaa ||", translation = "Everything is in the home of the self within; only the very fortunate obtain it.", hindi = "सभु किछु घर ही माहि है; वडभागी लीता ॥", punjabi = "ਇਹ ਨਾਮ-ਰੂਪ ਸਉਦਾ ਹੈ ਤਾਂ ਸਾਰਾ ਮਨੁੱਖ ਦੇ ਹਿਰਦੇ ਵਿਚ ਹੀ, ਪਰ ਵਣਜਿਆ ਹੈ ਵੱਡੇ ਭਾਗਾਂ ਵਾਲਿਆਂ ਨੇ ਹੀ।", wordMeaning = "ਵਡਭਾਗੀ = ਵੱਡੇ ਭਾਗਾਂ ਵਾਲਿਆਂ ਨੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-434", gurmukhi = "ਅੰਤਰਿ ਤ੍ਰਿਸਨਾ ਮਰਿ ਗਈ; ਹਰਿ ਗੁਣ ਗਾਵੀਤਾ ॥", transliteration = "antar trisnaa mar gaee; har gun gaaveetaa ||", translation = "The hunger within is conquered and overcome, singing the Glorious Praises of the Lord.", hindi = "अंतरि त्रिसना मरि गई; हरि गुण गावीता ॥", punjabi = "(ਜਿਨ੍ਹਾਂ ਵਣਜਿਆ ਹੈ) ਪ੍ਰਭੂ ਦੇ ਗੁਣ ਗਾ ਕੇ ਉਹਨਾਂ ਦੇ ਅੰਦਰੋਂ ਤ੍ਰਿਸ਼ਨਾ ਮਰ ਗਈ ਹੈ।", wordMeaning = "ਗਾਵੀਤਾ = ਗਾਂਵਿਆਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-435", gurmukhi = "ਆਪੇ ਮੇਲਿ ਮਿਲਾਇਅਨੁ; ਆਪੇ ਦੇਇ ਬੁਝਾਈ ॥੧੮॥", transliteration = "aape mel milaaian; aape dei bujhaaee ||18||", translation = "He Himself unites in His Union; He Himself blesses them with understanding. ||18||", hindi = "आपे मेलि मिलाइअनु; आपे देइ बुझाई ॥१८॥", punjabi = "(ਇਹ ਨਾਮ-ਰੂਪ ਸਉਦਾ ਕਰਨ ਦੀ) ਮੱਤ ਪ੍ਰਭੂ ਹੀ ਦੇਂਦਾ ਹੈ, ਤੇ ਉਸ ਨੇ ਆਪ ਹੀ (ਨਾਮ ਦੇ ਵਪਾਰੀ ਆਪਣੇ) ਮੇਲ ਵਿਚ ਮਿਲਾਏ ਹਨ ॥੧੮॥", wordMeaning = "ਮਿਲਾਇਅਨੁ = ਮਿਲਾਏ ਹਨ ਉਸ (ਪ੍ਰਭੂ) ਨੇ। ਬੁਝਾਈ = ਮੱਤ, ਸਮਝ ॥੧੮॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-436", gurmukhi = "ਵੇਲਿ ਪਿੰਞਾਇਆ ਕਤਿ; ਵੁਣਾਇਆ ॥", transliteration = "vel pinnaaiaa kat; vunaaiaa ||", translation = "The cotton is ginned, woven and spun;", hindi = "वेलि पिंञाइआ कति; वुणाइआ ॥", punjabi = "(ਰੂੰ ਵੇਲਣੇ ਵਿਚ) ਵੇਲ ਕੇ ਪਿੰਞਾਈਦਾ ਹੈ, ਕੱਤ ਕੇ (ਕੱਪੜਾ) ਉਣਾਈਦਾ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-437", gurmukhi = "ਸਲੋਕ ਮਃ ੧ ॥", transliteration = "salok mh 1 ||", translation = "Salok, First Mehl:", hindi = "सलोक मः १ ॥", punjabi = "ਸਲੋਕ ਪਹਿਲੀ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-438", gurmukhi = "ਕਟਿ ਕੁਟਿ ਕਰਿ; ਖੁੰਬਿ ਚੜਾਇਆ ॥", transliteration = "kat kut kar; khumb chraaiaa ||", translation = "the cloth is laid out, washed and bleached white.", hindi = "कटि कुटि करि; खुंबि चड़ाइआ ॥", punjabi = "ਇਸ ਦੇ ਟੋਟੇ ਕਰ ਕੇ (ਧੁਆਣ ਲਈ) ਖੁੰਬ ਤੇ ਚੜ੍ਹਾਈਦਾ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-439", gurmukhi = "ਇਉ ਪਤਿ ਪਾਟੀ. ਸਿਫਤੀ ਸੀਪੈ; ਨਾਨਕ. ਜੀਵਤ ਜੀਵੈ ॥", transliteration = "iu pat paatee. siphtee seepai; naanak. jeevat jeevai ||", translation = "Thus, the torn and tattered honor is sewn up again, through the Lord's Praise, O Nanak, and one lives the true life.", hindi = "इउ पति पाटी. सिफती सीपै; नानक. जीवत जीवै ॥", punjabi = "(ਜਿਵੇਂ ਇਹ ਕੱਟਿਆ ਪਾੜਿਆ ਹੋਇਆ ਕੱਪੜਾ ਸੂਈ ਧਾਗੇ ਨਾਲ ਸੀਪ ਜਾਂਦਾ ਹੈ) ਤਿਵੇਂ ਹੀ, ਹੇ ਨਾਨਕ! ਮਨੁੱਖ ਦੀ ਗੁਆਚੀ ਹੋਈ ਇੱਜ਼ਤ ਪ੍ਰਭੂ ਦੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਕਰਨ ਨਾਲ ਫਿਰ ਬਣ ਆਉਂਦੀ ਹੈ ਤੇ ਮਨੁੱਖ ਸੁਚੱਜਾ ਜੀਵਨ ਗੁਜ਼ਾਰਨ ਲੱਗ ਪੈਂਦਾ ਹੈ।", wordMeaning = "ਇਉ = ਇਸੇ ਤਰ੍ਹਾਂ ਹੀ। ਪਤਿ ਪਾਟੀ = ਗੁਆਚੀ ਹੋਈ ਇੱਜ਼ਤ। ਸਿਫਤੀ = ਪ੍ਰਭੂ ਦੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ ਕਰਨ ਨਾਲ। ਜੀਵਤ ਜੀਵੈ = ਅਸਲ ਜੀਵਨ ਗੁਜ਼ਾਰਨ ਲੱਗ ਪੈਂਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-440", gurmukhi = "ਲੋਹਾ ਵਢੇ. ਦਰਜੀ ਪਾੜੇ; ਸੂਈ ਧਾਗਾ ਸੀਵੈ ॥", transliteration = "lohaa vdhe. darjee paare; sooee dhaagaa seevai ||", translation = "The tailor cuts it with his scissors, and sews it with his thread.", hindi = "लोहा वढे. दरजी पाड़े; सूई धागा सीवै ॥", punjabi = "(ਇਸ ਕੱਪੜੇ ਨੂੰ) ਕੈਂਚੀ ਕਤਰਦੀ ਹੈ, ਦਰਜ਼ੀ ਇਸ ਨੂੰ ਪਾੜਦਾ ਹੈ, ਤੇ ਸੂਈ ਧਾਗਾ ਸਿਊਂਦਾ ਹੈ।", wordMeaning = "ਲੋਹਾ = ਕੈਂਚੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-441", gurmukhi = "ਮਾਹੁ ਪਖੁ. ਕਿਹੁ ਚਲੈ ਨਾਹੀ; ਘੜੀ ਮੁਹਤੁ ਕਿਛੁ ਹੰਢੈ ॥", transliteration = "maah pakh. kih chlai naahee; ghree muhat kichh handhai ||", translation = "It will not last for a month, or even a week. It barely lasts for an hour, or even a moment.", hindi = "माहु पखु. किहु चलै नाही; घड़ी मुहतु किछु हंढै ॥", punjabi = "(ਪਰ ਇਹ ਗੰਢਿਆ ਹੋਇਆ ਪੁਰਾਣਾ ਕੱਪੜਾ) ਕੋਈ ਮਹੀਨਾ ਅੱਧਾ ਮਹੀਨਾ ਤੱਗਦਾ ਨਹੀਂ, ਸਿਰਫ਼ ਘੜੀ ਦੋ ਘੜੀ (ਥੋੜਾ ਚਿਰ) ਹੀ ਹੰਢਦਾ ਹੈ;", wordMeaning = "ਮਾਹੁ = ਮਹੀਨਾ। ਪਖੁ = (ਚਾਨਣਾ ਤੇ ਹਨੇਰਾ ਪੱਖ) ਅੱਧਾ ਮਹੀਨਾ। ਕਿਹੁ = ਕਿਛੁ, ਕੁਝ। ਚਲੈ = ਤੱਗਦਾ ਹੈ। ਮੁਹਤੁ = ਮੁਹੂਰਤ, ਦੋ ਘੜੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-442", gurmukhi = "ਹੋਇ ਪੁਰਾਣਾ ਕਪੜੁ ਪਾਟੈ; ਸੂਈ ਧਾਗਾ ਗੰਢੈ ॥", transliteration = "hoi puraanaa kapar paatai; sooee dhaagaa gandhai ||", translation = "Becoming worn, the cloth is torn; with needle and thread it is sewn up again.", hindi = "होइ पुराणा कपड़ु पाटै; सूई धागा गंढै ॥", punjabi = "ਕੱਪੜਾ ਪੁਰਾਣਾ ਹੋ ਕੇ ਪਾਟ ਜਾਂਦਾ ਹੈ, ਸੂਈ ਧਾਗਾ ਇਸ ਨੂੰ ਗੰਢ ਦੇਂਦਾ ਹੈ,", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-443", gurmukhi = "ਸਚੁ ਪੁਰਾਣਾ ਹੋਵੈ ਨਾਹੀ; ਸੀਤਾ ਕਦੇ. ਨ ਪਾਟੈ ॥", transliteration = "sach puraanaa hovai naahee; seetaa kde. na paatai ||", translation = "But the Truth does not grow old; and when it is stitched, it is never torn again.", hindi = "सचु पुराणा होवै नाही; सीता कदे. न पाटै ॥", punjabi = "(ਪਰ) ਪ੍ਰਭੂ ਦਾ ਨਾਮ (-ਰੂਪ ਪਟੋਲਾ) ਕਦੇ ਪੁਰਾਣਾ ਨਹੀਂ ਹੁੰਦਾ, ਸੀਤਾ ਹੋਇਆ ਕਦੇ ਪਾਟਦਾ ਨਹੀਂ (ਉਸ ਪ੍ਰਭੂ ਨਾਲ ਜੁੜਿਆ ਹੋਇਆ ਮਨ ਉਸ ਤੋਂ ਟੁੱਟਦਾ ਨਹੀਂ)।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-444", gurmukhi = "ਨਾਨਕ. ਸਾਹਿਬੁ ਸਚੋ ਸਚਾ; ਤਿਚਰੁ ਜਾਪੀ ਜਾਪੈ ॥੧॥", transliteration = "naanak. saahib scho schaa; tichar jaapee jaapai ||1||", translation = "O Nanak, the Lord and Master is the Truest of the True. While we meditate on Him, we see Him. ||1||", hindi = "नानक. साहिबु सचो सचा; तिचरु जापी जापै ॥१॥", punjabi = "ਹੇ ਨਾਨਕ! ਪ੍ਰਭੂ-ਖਸਮ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ ਹੈ, ਪਰ ਇਸ ਗੱਲ ਦੀ ਤਾਂ ਹੀ ਸਮਝ ਪੈਂਦੀ ਹੈ ਜੇ ਉਸ ਨੂੰ ਸਿਮਰੀਏ ॥੧॥", wordMeaning = "ਤਿਚਰੁ ਜਾਪੀ ਜਾਪੇ . . ਤਿਚਰੁ ਜਾਪੀ ਜਿਚਰੁ ਜਾਪੈ = ਉਤਨਾ ਚਿਰ ਦਿੱਸਦਾ ਹੈ ਜਿਤਨਾ ਚਿਰ ਜਪੀਏ ॥੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-445", gurmukhi = "ਮਃ ੧ ॥", transliteration = "mh 1 ||", translation = "First Mehl:", hindi = "मः १ ॥", punjabi = "ਪਹਿਲੀ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-446", gurmukhi = "ਸਚ ਕੀ ਕਾਤੀ; ਸਚੁ ਸਭੁ ਸਾਰੁ ॥", transliteration = "sach kee kaatee; sach sabh saar ||", translation = "The knife is Truth, and its steel is totally True.", hindi = "सच की काती; सचु सभु सारु ॥", punjabi = "ਜੇ ਪ੍ਰਭੂ ਦੇ ਨਾਮ ਦੀ ਛੁਰੀ ਹੋਵੇ, ਪ੍ਰਭੂ ਦਾ ਨਾਮ ਹੀ (ਉਸ ਛੁਰੀ ਦਾ) ਸਾਰਾ ਲੋਹਾ ਹੋਵੇ,", wordMeaning = "ਕਾਤੀ = (ਸੰ: कर्तरी) ਕੈਂਚੀ, ਚਾਕੂ, ਛੁਰੀ। ਸਾਰੁ = ਲੋਹਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-447", gurmukhi = "ਘਾੜਤ ਤਿਸ ਕੀ; ਅਪਰ ਅਪਾਰ ॥", transliteration = "ghaarat tis kee; apar apaar ||", translation = "Its workmanship is incomparably beautiful.", hindi = "घाड़त तिस की; अपर अपार ॥", punjabi = "ਉਸ ਛੁਰੀ ਦੀ ਘਾੜਤ ਬਹੁਤ ਸੁੰਦਰ ਹੁੰਦੀ ਹੈ;", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-448", gurmukhi = "ਸਬਦੇ ਸਾਣ; ਰਖਾਈ ਲਾਇ ॥", transliteration = "sabde saan; rkhaaee laai ||", translation = "It is sharpened on the grindstone of the Shabad.", hindi = "सबदे साण; रखाई लाइ ॥", punjabi = "ਇਹ ਛੁਰੀ ਸਤਿਗੁਰੂ ਦੇ ਸ਼ਬਦ ਦੀ ਸਾਣ ਤੇ ਰੱਖ ਕੇ ਤੇਜ਼ ਕੀਤੀ ਜਾਂਦੀ ਹੈ,", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L)
