    BaniLine(id = "ramkali-ki-vaar-458", gurmukhi = "ਸੋ ਸਤਸੰਗਤਿ ਸਬਦਿ ਮਿਲੈ; ਜੋ ਗੁਰਮੁਖਿ ਚਲੈ ॥", transliteration = "so satasangat sabad milai; jo gurmukh chlai ||", translation = "They alone walk as Gurmukh, who receive the Shabad in the Sat Sangat, the True Congregation.", hindi = "सो सतसंगति सबदि मिलै; जो गुरमुखि चलै ॥", punjabi = "ਜੋ ਮਨੁੱਖ ਗੁਰੂ ਦੇ ਹੁਕਮ ਵਿਚ ਤੁਰਦਾ ਹੈ ਉਹ ਸਾਧ ਸੰਗਤ ਵਿਚ (ਆ ਕੇ) ਗੁਰੂ ਦੇ ਸ਼ਬਦ ਵਿਚ ਜੁੜਦਾ ਹੈ।", wordMeaning = "ਗੁਰਮੁਖਿ = ਗੁਰੂ ਦੇ ਸਨਮੁਖ, ਗੁਰੂ ਦੇ ਹੁਕਮ ਵਿਚ। ਸੋ = ਉਹ ਮਨੁੱਖ। ਸਬਦਿ = ਗੁਰੂ ਦੇ ਸ਼ਬਦ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-459", gurmukhi = "ਪਉੜੀ ॥", transliteration = "pauree ||", translation = "Pauree:", hindi = "पउड़ी ॥", punjabi = "ਪਉੜੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-460", gurmukhi = "ਰਤਨ ਬੀਚਾਰੁ ਮਨਿ ਵਸਿਆ; ਗੁਰ ਕੈ ਸਬਦਿ ਭਲੈ ॥", transliteration = "ratan beechaar man vsiaa; gur kai sabad bhlai ||", translation = "They enshrine the jewel of contemplation within their minds, and the most sublime Word of the Guru's Shabad.", hindi = "रतन बीचारु मनि वसिआ; गुर कै सबदि भलै ॥", punjabi = "ਸਤਿਗੁਰੂ ਦੇ ਸੋਹਣੇ ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ ਉਹਨਾਂ ਦੇ ਮਨ ਵਿਚ ਪ੍ਰਭੂ ਦੇ ਸ੍ਰੇਸ਼ਟ ਨਾਮ ਦੀ ਵਿਚਾਰ ਆ ਵੱਸਦੀ ਹੈ।", wordMeaning = "ਰਤਨ ਬੀਚਾਰੁ = ਪ੍ਰਭੂ ਦੇ ਨਾਮ-ਰਤਨ ਦੀ ਵਿਚਾਰ, ਪ੍ਰਭੂ ਦੇ ਸ੍ਰੇਸ਼ਟ ਨਾਮ ਦੀ ਵਿਚਾਰ। ਸਬਦਿ ਭਲੈ = ਸੋਹਣੇ ਸ਼ਬਦ ਦੀ ਰਾਹੀਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-461", gurmukhi = "ਭਗਤ ਸੋਹਨਿ. ਗੁਣ ਗਾਵਦੇ; ਗੁਰਮਤਿ ਅਚਲੈ ॥", transliteration = "bhagat sohan. gun gaavde; guramat achlai ||", translation = "The devotees look beautiful, singing the Praises of the Lord; following the Guru's Teachings, they become stable and unchanging.", hindi = "भगत सोहनि. गुण गावदे; गुरमति अचलै ॥", punjabi = "ਬੰਦਗੀ ਕਰਨ ਵਾਲੇ ਬੰਦੇ ਪ੍ਰਭੂ ਦੇ ਗੁਣ ਗਾਂਦੇ ਹਨ ਤੇ ਸੋਹਣੇ ਲੱਗਦੇ ਹਨ, ਸਤਿਗੁਰੂ ਦੀ ਮੱਤ ਲੈ ਕੇ ਉਹ ਅਡੋਲ ਹੋ ਜਾਂਦੇ ਹਨ।", wordMeaning = "ਸੋਹਨਿ = ਸੋਭਦੇ ਹਨ। ਅਚਲੈ = ਅਡੋਲ (ਹੋ ਜਾਂਦੇ ਹਨ)।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-462", gurmukhi = "ਆਪੇ ਮੇਲਿ ਮਿਲਾਇਦਾ; ਆਪੇ ਦੇਇ ਵਡਿਆਈ ॥੧੯॥", transliteration = "aape mel milaaidaa; aape dei vdiaaee ||19||", translation = "He Himself unites in His Union; He Himself grants glorious greatness. ||19||", hindi = "आपे मेलि मिलाइदा; आपे देइ वडिआई ॥१९॥", punjabi = "(ਭਗਤ ਜਨਾਂ ਨੂੰ) ਪ੍ਰਭੂ ਆਪ ਹੀ ਆਪਣੇ ਵਿਚ ਮਿਲਾਂਦਾ ਹੈ, ਆਪ ਹੀ ਉਹਨਾਂ ਨੂੰ ਸੋਭਾ ਦੇਂਦਾ ਹੈ ॥੧੯॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-463", gurmukhi = "ਸਲੋਕ ਮਃ ੩ ॥", transliteration = "salok mh 3 ||", translation = "Salok, Third Mehl:", hindi = "सलोक मः ३ ॥", punjabi = "ਸਲੋਕ ਤੀਜੀ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-464", gurmukhi = "ਮਃ ੩ ॥", transliteration = "mh 3 ||", translation = "Third Mehl:", hindi = "मः ३ ॥", punjabi = "ਤੀਜੀ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-465", gurmukhi = "ਆਸਾ ਅੰਦਰਿ ਸਭੁ ਕੋ; ਕੋਇ ਨਿਰਾਸਾ ਹੋਇ ॥", transliteration = "aasaa andar sabh ko; koi niraasaa hoi ||", translation = "Everyone is filled with hope; hardly anyone is free of hope.", hindi = "आसा अंदरि सभु को; कोइ निरासा होइ ॥", punjabi = "ਹਰੇਕ ਜੀਵ ਆਸਾਂ ਵਿਚ (ਫਸਿਆ ਪਿਆ) ਹੈ (ਭਾਵ, ਨਿੱਤ ਨਵੀਆਂ ਆਸਾਂ ਬਣਾਂਦਾ ਰਹਿੰਦਾ ਹੈ), ਕੋਈ ਵਿਰਲਾ ਮਨੁੱਖ ਹੈ ਜੋ ਆਸਾਂ ਤੋਂ ਬਚਿਆ ਰਹਿੰਦਾ ਹੈ।", wordMeaning = "ਸਭੁ ਕੋ = ਹਰੇਕ ਜੀਵ। ਕੋਇ = ਕੋਈ ਵਿਰਲਾ। ਨਿਰਾਸਾ = ਆਸਾਂ ਤੋਂ ਬਚਿਆ ਹੋਇਆ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-466", gurmukhi = "ਨਾਨਕ. ਜੋ ਮਰਿ ਜੀਵਿਆ; ਸਹਿਲਾ ਆਇਆ ਸੋਇ ॥੧॥", transliteration = "naanak. jo mar jeeviaa; shilaa aaiaa soi ||1||", translation = "O Nanak, blessed is the birth of one, who remains dead while yet alive. ||1||", hindi = "नानक. जो मरि जीविआ; सहिला आइआ सोइ ॥१॥", punjabi = "ਹੇ ਨਾਨਕ! ਜੋ ਮਨੁੱਖ ਆਸਾਂ ਵਲੋਂ ਹਟ ਕੇ (ਪ੍ਰਭੂ ਦੇ ਸਿਮਰਨ ਵਿਚ) ਜੀਵਨ ਗੁਜ਼ਾਰਦਾ ਹੈ ਉਸ ਦਾ ਆਉਣਾ ਸਫਲ ਹੈ ॥੧॥", wordMeaning = "ਮਰਿ = ਮਰ ਕੇ, ਆਸਾਂ ਵਲੋਂ ਹਟ ਕੇ। ਸਹਿਲਾ = ਸਫਲਾ ॥੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-467", gurmukhi = "ਪਉੜੀ ॥", transliteration = "pauree ||", translation = "Pauree:", hindi = "पउड़ी ॥", punjabi = "ਪਉੜੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-468", gurmukhi = "ਕਿਆ ਕਰੇ ਏਹ ਬਪੁੜੀ; ਜਾਂ ਭੋੁਲਾਏ ਸੋਇ ॥੨॥", transliteration = "kiaa kre eh bpuree; jaan bhoulaae soi ||2||", translation = "What can this poor being do? The Lord Himself creates confusion. ||2||", hindi = "किआ करे एह बपुड़ी; जां भोुलाए सोइ ॥२॥", punjabi = "ਇਹ ਵਿਚਾਰੀ 'ਆਸਾ' ਕੀਹ ਕਰ ਸਕਦੀ ਹੈ? ਭੁਲਾਉਂਦਾ ਤਾਂ ਉਹ ਪ੍ਰਭੂ ਆਪ ਹੈ ॥੨॥", wordMeaning = "ਏਹ = ਇਹ ਆਸਾ। ਬਪੁੜੀ = ਵਿਚਾਰੀ। ਸੋਇ = ਉਹ ਪ੍ਰਭੂ ਆਪ। ਭਲਾਏ = {ਅੱਖਰ 'ਭ' ਦੀ ਲਗ (ੋ) ਇਥੇ ਪੜ੍ਹਨੀ ਹੈ, ਭਾਵ, ਇਸ ਲਫ਼ਜ਼ ਨੂੰ 'ਭੋਲਾਏ' ਪੜ੍ਹਨਾ ਹੈ, ਅਸਲ ਲਫ਼ਜ਼ 'ਭੁਲਾਇ' ਹੈ} ॥੨॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-469", gurmukhi = "ਨਾ ਕਿਛੁ ਆਸਾ ਹਥਿ ਹੈ; ਕੇਉ ਨਿਰਾਸਾ ਹੋਇ ॥", transliteration = "naa kichh aasaa hath hai; keu niraasaa hoi ||", translation = "Nothing is in the hands of hope. How can one become free of hope?", hindi = "ना किछु आसा हथि है; केउ निरासा होइ ॥", punjabi = "'ਆਸਾ' ਦੇ ਹੱਥ ਵਿਚ ਕੋਈ ਤਾਕਤ ਨਹੀਂ (ਕਿ ਜੀਵਾਂ ਨੂੰ ਫਸਾ ਸਕੇ; ਸੋ, ਆਪਣੇ ਉੱਦਮ ਨਾਲ ਭੀ) ਮਨੁੱਖ 'ਆਸਾ' ਤੋਂ ਨਹੀਂ ਬਚ ਸਕਦਾ।", wordMeaning = "ਆਸਾ ਹਥਿ = ਆਸਾ ਦੇ ਹੱਥ ਵਿਚ, ਆਸਾ ਦੇ ਵੱਸ ਵਿਚ। ਕੇਉ = ਕਿਵੇਂ, ਕਿਸ ਤਰ੍ਹਾਂ?", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-470", gurmukhi = "ਸਾਸਿ ਸਾਸਿ ਆਰਾਧੇ; ਨਿਰਮਲੁ ਸੋਇ ਜਨੁ ॥", transliteration = "saas saas aaraadhe; niramal soi jan ||", translation = "That humble being is immaculate, who worships the Lord with each and every breath.", hindi = "सासि सासि आराधे; निरमलु सोइ जनु ॥", punjabi = "ਉਹੀ ਮਨੁੱਖ ਪਵਿਤ੍ਰ (ਜੀਵਨ ਵਾਲਾ) ਹੈ ਜੋ (ਪ੍ਰਭੂ ਨੂੰ) ਹਰੇਕ ਸਾਹ ਦੇ ਨਾਲ ਯਾਦ ਕਰਦਾ ਹੈ।", wordMeaning = "ਸਾਸਿ ਸਾਸਿ = ਹਰੇਕ ਸਾਹ ਵਿਚ। ਸੋਇ = ਸੋ ਹੀ, ਉਹੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-471", gurmukhi = "ਪ੍ਰਭੁ ਦਾਤਾ ਦਾਤਾਰ; ਨਿਹਚਲੁ ਏਹੁ ਧਨੁ ॥", transliteration = "prabh daataa daataar; nihachal eh dhan ||", translation = "God is the Great Giver of givers. His wealth is permanent and unchanging.", hindi = "प्रभु दाता दातार; निहचलु एहु धनु ॥", punjabi = "ਪ੍ਰਭੂ ਹੀ (ਸਭ ਦਾ) ਦਾਤਾ ਹੈ ਸਭ ਦਾਤਾਂ ਦੇਣ ਵਾਲਾ ਹੈ; ਸੋ, ਉਸ ਦਾ ਇਹ (ਨਾਮ-) ਧਨ ਹੀ (ਐਸਾ ਹੈ ਜੋ) ਕਦੇ ਨਾਸ ਹੋਣ ਵਾਲਾ ਨਹੀਂ।", wordMeaning = "ਨਿਹਚਲੁ = ਨਾਹ ਨਾਸ ਹੋਣ ਵਾਲਾ। ਏਹੁ = ਇਹ ਨਾਮ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-472", gurmukhi = "ਧ੍ਰਿਗੁ ਜੀਵਣੁ ਸੰਸਾਰ; ਸਚੇ ਨਾਮ ਬਿਨੁ ॥", transliteration = "dhrig jeevan sansaar; sche naam bin ||", translation = "Cursed is the life in this world, without the True Name.", hindi = "ध्रिगु जीवणु संसार; सचे नाम बिनु ॥", punjabi = "ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲੇ ਪ੍ਰਭੂ ਦਾ ਨਾਮ ਸਿਮਰਨ ਤੋਂ ਬਿਨਾ ਜਗਤ ਦਾ ਜੀਊਣਾ ਫਿਟਕਾਰ-ਜੋਗ ਹੈ।", wordMeaning = "ਧ੍ਰਿਗੁ = ਫਿਟਕਾਰ-ਯੋਗ। ਸੰਸਾਰ ਜੀਵਣੁ = ਦੁਨੀਆ ਦਾ ਜੀਊਣਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-473", gurmukhi = "ਰਵਿ ਰਹਿਆ ਸਰਬਤਿ; ਨਾਨਕੁ ਬਲਿ ਜਾਈ ॥੨੦॥", transliteration = "rav rhiaa sarabat; naanak bal jaaee ||20||", translation = "He is all-pervading everywhere. Nanak is a sacrifice to Him. ||20||", hindi = "रवि रहिआ सरबति; नानकु बलि जाई ॥२०॥", punjabi = "ਨਾਨਕ ਉਸ ਪ੍ਰਭੂ ਤੋਂ ਸਦਕੇ ਹੈ ਜੋ ਸਾਰਿਆਂ ਵਿਚ ਵਿਆਪਕ ਹੈ ॥੨੦॥", wordMeaning = "ਰਵਿ ਰਹਿਆ = ਵਿਆਪਕ ਹੈ। ਸਰਬਤਿ = ਸਾਰਿਆਂ ਵਿਚ ॥੨੦॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-474", gurmukhi = "ਅੰਤਰਜਾਮੀ ਅਗਮੁ; ਰਸਨਾ ਏਕੁ ਭਨੁ ॥", transliteration = "antarjaamee agam; rasnaa ek bhan ||", translation = "With your tongue, vibrate the One Inaccessible Lord, the Inner-knower, the Searcher of hearts.", hindi = "अंतरजामी अगमु; रसना एकु भनु ॥", punjabi = "ਜੀਭ ਨਾਲ ਉਸ ਇਕ ਪ੍ਰਭੂ ਨੂੰ ਯਾਦ ਕਰ ਜੋ ਸਭ ਦੇ ਦਿਲ ਦੀ ਜਾਣਦਾ ਹੈ ਤੇ ਜੋ (ਜੀਵਾਂ ਦੀ) ਪਹੁੰਚ ਤੋਂ ਪਰੇ ਹੈ।", wordMeaning = "ਅੰਤਰਜਾਮੀ = ਹਰੇਕ ਦੇ ਦਿਲ ਦੀ ਜਾਣਨ ਵਾਲਾ। ਅਗਮੁ = ਅ-ਗਮੁ, ਜਿਸ ਤਕ ਪਹੁੰਚ ਨਾਹ ਹੋ ਸਕੇ। ਰਸਨਾ = ਜੀਭ। ਭਨੁ = ਉੱਚਾਰ, ਜਪ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-475", gurmukhi = "ਸਰਵਰ ਹੰਸ. ਧੁਰੇ ਹੀ ਮੇਲਾ; ਖਸਮੈ ਏਵੈ ਭਾਣਾ ॥", transliteration = "saravar hans. dhure hee melaa; khasmai evai bhaanaa ||", translation = "The union between the lake of the True Guru, and the swan of the soul, was pre-ordained from the very beginning, by the Pleasure of the Lord's Will.", hindi = "सरवर हंस. धुरे ही मेला; खसमै एवै भाणा ॥", punjabi = "(ਗੁਰੂ-) ਸਰੋਵਰ ਅਤੇ (ਗੁਰਮੁਖ-) ਹੰਸ ਦਾ ਜੋੜ ਮੁੱਢੋਂ ਹੀ ਚਲਿਆ ਆਉਂਦਾ ਹੈ, ਖਸਮ-ਪ੍ਰਭੂ ਨੂੰ ਇਹੀ ਗੱਲ ਚੰਗੀ ਲੱਗਦੀ ਹੈ।", wordMeaning = "ਧੁਰੇ ਹੀ = ਧੁਰ ਤੋਂ ਹੀ, ਮੁੱਢ ਤੋਂ ਹੀ। ਮੇਲਾ = ਜੋੜ। ਖਸਮੈ = ਖਸਮ ਨੂੰ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-476", gurmukhi = "ਸਲੋਕੁ ਮਃ ੧ ॥", transliteration = "salok mh 1 ||", translation = "Salok, First Mehl:", hindi = "सलोकु मः १ ॥", punjabi = "ਸਲੋਕ ਪਹਿਲੀ ਪਾਤਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-477", gurmukhi = "ਸਰਵਰ ਅੰਦਰਿ ਹੀਰਾ ਮੋਤੀ; ਸੋ ਹੰਸਾ ਕਾ ਖਾਣਾ ॥", transliteration = "saravar andar heeraa motee; so hansaa kaa khaanaa ||", translation = "The diamonds are in this lake; they are the food of the swans.", hindi = "सरवर अंदरि हीरा मोती; सो हंसा का खाणा ॥", punjabi = "ਹੰਸਾਂ (ਗੁਰਮੁਖਾਂ) ਦੀ ਖ਼ੁਰਾਕ (ਪ੍ਰਭੂ ਦੀ ਸਿਫ਼ਤ-ਸਾਲਾਹ-ਰੂਪ) ਹੀਰੇ ਮੋਤੀ ਹੈ ਜੋ (ਗੁਰੂ-) ਸਰੋਵਰ ਵਿਚ ਮਿਲਦੇ ਹਨ।", wordMeaning = "ਖਾਣਾ = ਖ਼ੁਰਾਕ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "ramkali-ki-vaar-478", gurmukhi = "ਓਨਾ ਰਿਜਕੁ. ਨ ਪਇਓ ਓਥੈ; ਓਨੑਾ ਹੋਰੋ ਖਾਣਾ ॥", transliteration = "onaa rijak. na paio othai; onhaa horo khaanaa ||", translation = "They do not find their food there; their food is different.", hindi = "ओना रिजकु. न पइओ ओथै; ओन्हा होरो खाणा ॥", punjabi = "(ਕਿਉਂਕਿ) ਉਹਨਾਂ (ਕਾਂ ਬਗੁਲੇ ਮਨਮੁਖਾਂ) ਦੀ ਖ਼ੁਰਾਕ ਓਥੇ ਨਹੀਂ ਹੈ, ਉਹਨਾਂ ਦੀ ਖ਼ੁਰਾਕ ਵੱਖਰੀ ਹੀ ਹੁੰਦੀ ਹੈ।", wordMeaning = "ਓਨਾ = ਉਹਨਾਂ ਕਾਂ ਤੇ ਬਗਲਿਆਂ ਦਾ।", startsAtMs = 0L, endsAtMs = 0L),
